from (values
(385518,42836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jemand beim Essen des letzten Kuchens erwischt ..., schämt er sich.'::text,'wird'::text,'wurde'::text,'werden wird'::text,'Wenn jemand beim Essen des letzten Kuchens erwischt wird, schämt er sich.'::text),
(385522,42836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо когось ... за поїданням останнього торта, йому соромно.'::text,'ловлять'::text,'спіймали'::text,'спіймають'::text,'Якщо когось ловлять за поїданням останнього торта, йому соромно.'::text),
(385521,42836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si a alguien lo ... comiéndose el último pastel, siente vergüenza.'::text,'pillan'::text,'pillaron'::text,'pillarán'::text,'Si a alguien lo pillan comiéndose el último pastel, siente vergüenza.'::text),
(385520,42836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si quelqu''un ... surpris en train de manger le dernier gâteau, il a honte.'::text,'est'::text,'a été'::text,'sera'::text,'Si quelqu''un est surpris en train de manger le dernier gâteau, il a honte.'::text),
(385523,42836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri son pastayı yerken ..., utanç duyar.'::text,'yakalanırsa'::text,'yakalandıysa'::text,'yakalanacaksa'::text,'Biri son pastayı yerken yakalanırsa, utanç duyar.'::text),
(385524,42836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha valakit ... azon, hogy az utolsó tortát eszi, szégyent érez.'::text,'rajtakapnak'::text,'rajtakaptak'::text,'rajta fognak kapni'::text,'Ha valakit rajtakapnak azon, hogy az utolsó tortát eszi, szégyent érez.'::text),
(385536,42838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, wenn ich ihren Kuchen essen würde, ... ich vor Scham auch den Kopf hängen lassen, echt jetzt.'::text,'würde'::text,'werde'::text,'lasse'::text,'Nee, wenn ich ihren Kuchen essen würde, würde ich vor Scham auch den Kopf hängen lassen, echt jetzt.'::text),
(385540,42838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, якби я з''їв її торт, я теж ... голову від сорому, чесно.'::text,'опустив би'::text,'опущу'::text,'опускаю'::text,'Не, якби я з''їв її торт, я теж опустив би голову від сорому, чесно.'::text),
(385539,42838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, si me comiera su pastel, yo también ... la cabeza de vergüenza, en serio.'::text,'agacharía'::text,'agacharé'::text,'agacho'::text,'Nah, si me comiera su pastel, yo también agacharía la cabeza de vergüenza, en serio.'::text),
(385538,42838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, si je mangeais son gâteau, moi aussi je ... la tête de honte, sérieux.'::text,'baisserais'::text,'baisserai'::text,'baisse'::text,'Nan, si je mangeais son gâteau, moi aussi je baisserais la tête de honte, sérieux.'::text),
(385541,42838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok ya, onun pastasını yesem, ben de utançtan başımı ..., cidden.'::text,'eğerdim'::text,'eğeceğim'::text,'eğerim'::text,'Yok ya, onun pastasını yesem, ben de utançtan başımı eğerdim, cidden.'::text),
(385542,42838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, ha megenném a tortáját, én is ... a fejem szégyenemben, komolyan.'::text,'lehajtanám'::text,'le fogom hajtani'::text,'lehajtom'::text,'Á, ha megenném a tortáját, én is lehajtanám a fejem szégyenemben, komolyan.'::text),
(385545,42839,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kuchen ... in unter 60 Sekunden gegessen, und Scham ist jetzt der wichtigste Tagesordnungspunkt.'::text,'wurde'::text,'aß'::text,'wird'::text,'Der Kuchen wurde in unter 60 Sekunden gegessen, und Scham ist jetzt der wichtigste Tagesordnungspunkt.'::text),
(385549,42839,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Торт ... менш ніж за 60 секунд, і сором тепер головний пункт порядку денного.'::text,'був з''їдений'::text,'з''їв'::text,'з''їдається'::text,'Торт був з''їдений менш ніж за 60 секунд, і сором тепер головний пункт порядку денного.'::text),
(385548,42839,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pastel ... en menos de 60 segundos, y la vergüenza es ahora el punto principal del orden del día.'::text,'fue comido'::text,'comió'::text,'es comido'::text,'El pastel fue comido en menos de 60 segundos, y la vergüenza es ahora el punto principal del orden del día.'::text),
(385547,42839,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gâteau ... en moins de 60 secondes, et la honte est désormais le point principal de l''ordre du jour.'::text,'a été mangé'::text,'a mangé'::text,'est mangé'::text,'Le gâteau a été mangé en moins de 60 secondes, et la honte est désormais le point principal de l''ordre du jour.'::text),
(385550,42839,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pasta 60 saniyeden kısa sürede ... ve utanç artık gündemin ilk maddesi.'::text,'yendi'::text,'yedi'::text,'yenir'::text,'Pasta 60 saniyeden kısa sürede yendi ve utanç artık gündemin ilk maddesi.'::text),
(385551,42839,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tortát kevesebb mint 60 másodperc alatt ..., és most a szégyen a napirend első pontja.'::text,'megették'::text,'megette'::text,'megeszik'::text,'A tortát kevesebb mint 60 másodperc alatt megették, és most a szégyen a napirend első pontja.'::text),
(385554,42840,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... vor Scham seinen Mund, weil er nicht wollte, dass sie seinen Mund sieht.'::text,'versteckte'::text,'wurde versteckt'::text,'versteckend'::text,'Er versteckte vor Scham seinen Mund, weil er nicht wollte, dass sie seinen Mund sieht.'::text),
(385558,42840,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... рот від сорому, бо не хотів, щоб вона бачила його рот.'::text,'сховав'::text,'був схований'::text,'ховаючи'::text,'Він сховав рот від сорому, бо не хотів, щоб вона бачила його рот.'::text),
(385557,42840,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la boca de vergüenza porque no quería que ella le viera la boca.'::text,'se tapó'::text,'fue tapado'::text,'tapando'::text,'Él se tapó la boca de vergüenza porque no quería que ella le viera la boca.'::text),
(385556,42840,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sa bouche de honte parce qu''il ne voulait pas qu''elle voie sa bouche.'::text,'a caché'::text,'a été caché'::text,'cachant'::text,'Il a caché sa bouche de honte parce qu''il ne voulait pas qu''elle voie sa bouche.'::text),
(385559,42840,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Utançtan ağzını ..., çünkü onun ağzını görmesini istemiyordu.'::text,'sakladı'::text,'saklandı'::text,'saklayarak'::text,'Utançtan ağzını sakladı, çünkü onun ağzını görmesini istemiyordu.'::text),
(385560,42840,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szégyenében ... a száját, mert nem akarta, hogy a lány lássa a száját.'::text,'eltakarta'::text,'el lett takarva'::text,'eltakarva'::text,'Szégyenében eltakarta a száját, mert nem akarta, hogy a lány lássa a száját.'::text),
(385563,42841,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein gesenkter Kopf zeigt deutlich, dass das Subjekt Scham empfinden ...'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Sein gesenkter Kopf zeigt deutlich, dass das Subjekt Scham empfinden muss.'::text),
(385567,42841,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його опущена голова чітко вказує на те, що суб''єкт ... відчувати сором.'::text,'мусить'::text,'не може'::text,'повинен'::text,'Його опущена голова чітко вказує на те, що суб''єкт мусить відчувати сором.'::text),
(385566,42841,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su cabeza agachada indica claramente que el sujeto ... sentir vergüenza.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Su cabeza agachada indica claramente que el sujeto debe de sentir vergüenza.'::text),
(385565,42841,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa tête baissée indique clairement que le sujet ... ressentir de la honte.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Sa tête baissée indique clairement que le sujet doit ressentir de la honte.'::text),
(385568,42841,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğik başı açıkça gösteriyor ki denek utanç hissediyor ...'::text,'olmalı'::text,'olamaz'::text,'olması gerekir'::text,'Eğik başı açıkça gösteriyor ki denek utanç hissediyor olmalı.'::text),
(385569,42841,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lehajtott feje egyértelműen jelzi, hogy az alany ... szégyent érez.'::text,'biztosan'::text,'nem lehet, hogy'::text,'elvileg'::text,'Lehajtott feje egyértelműen jelzi, hogy az alany biztosan szégyent érez.'::text),
(385572,42842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Kuchen er zerstört hat, starrt ihn an, und seine Scham ist total!'::text,'deren'::text,'die'::text,'welche'::text,'Die Frau, deren Kuchen er zerstört hat, starrt ihn an, und seine Scham ist total!'::text),
(385576,42842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... торт він знищив, дивиться на нього, і його сором абсолютний!'::text,'чий'::text,'яка'::text,'який'::text,'Жінка, чий торт він знищив, дивиться на нього, і його сором абсолютний!'::text),
(385575,42842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La mujer ... pastel él destrozó lo está mirando fijamente, y su vergüenza es absoluta!'::text,'cuyo'::text,'que'::text,'el cual'::text,'¡La mujer cuyo pastel él destrozó lo está mirando fijamente, y su vergüenza es absoluta!'::text),
(385574,42842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... il a détruit le gâteau le fixe, et sa honte est absolue !'::text,'dont'::text,'qui'::text,'lequel'::text,'La femme dont il a détruit le gâteau le fixe, et sa honte est absolue !'::text),
(385577,42842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Pastasını mahvettiği kadın ona dik dik bakıyor ve utancı mutlak!'::text,''::text,NULL::text,NULL::text,'Pastasını mahvettiği kadın ona dik dik bakıyor ve utancı mutlak!'::text),
(385578,42842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... tortáját tönkretette, bámulja őt, és a szégyene teljes!'::text,'akinek a'::text,'aki'::text,'amely'::text,'A nő, akinek a tortáját tönkretette, bámulja őt, és a szégyene teljes!'::text),
(385581,42843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, er ... nie wieder ihren Kuchen essen, und seine Scham war absolut unerträglich!'::text,'würde'::text,'werde'::text,'ist'::text,'Er sagte, er würde nie wieder ihren Kuchen essen, und seine Scham war absolut unerträglich!'::text),
(385585,42843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що більше ніколи ... її торт, і його сором був абсолютно нестерпним!'::text,'не з''їсть'::text,'не з''їсть'::text,'не є'::text,'Він сказав, що більше ніколи не з''їсть її торт, і його сором був абсолютно нестерпним!'::text),
(385584,42843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dijo que nunca más ... su pastel, y su vergüenza era absolutamente insoportable!'::text,'comería'::text,'comerá'::text,'es'::text,'¡Dijo que nunca más comería su pastel, y su vergüenza era absolutamente insoportable!'::text),
(385583,42843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ne ... plus jamais son gâteau, et sa honte était absolument insupportable !'::text,'mangerait'::text,'mangera'::text,'est'::text,'Il a dit qu''il ne mangerait plus jamais son gâteau, et sa honte était absolument insupportable !'::text),
(385586,42843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha asla onun pastasını ... söyledi ve utancı kesinlikle dayanılmazdı!'::text,'yemeyeceğini'::text,'yemeyeceğini'::text,'yemediğini'::text,'Bir daha asla onun pastasını yemeyeceğini söyledi ve utancı kesinlikle dayanılmazdı!'::text),
(385587,42843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy soha többé ... a tortáját, és a szégyene teljesen elviselhetetlen volt!'::text,'nem enné meg'::text,'nem fogja megenni'::text,'nem eszi meg'::text,'Azt mondta, hogy soha többé nem enné meg a tortáját, és a szégyene teljesen elviselhetetlen volt!'::text),
(385590,42844,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... jeden Abend ohne jede Scham ihren Kuchen, bis zur Katastrophe heute Abend!'::text,'aß immer'::text,'aß früher'::text,'war gewohnt zu essen'::text,'Er aß immer jeden Abend ohne jede Scham ihren Kuchen, bis zur Katastrophe heute Abend!'::text),
(385594,42844,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... її торт щовечора без жодного сорому, аж до сьогоднішньої катастрофи!'::text,'їв'::text,'колись їв'::text,'звик їсти'::text,'Він їв її торт щовечора без жодного сорому, аж до сьогоднішньої катастрофи!'::text),
(385593,42844,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... su pastel cada noche sin ninguna vergüenza, hasta el desastre de esta noche!'::text,'comía'::text,'solía comer'::text,'estaba acostumbrado a comer'::text,'¡Él comía su pastel cada noche sin ninguna vergüenza, hasta el desastre de esta noche!'::text),
(385592,42844,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... son gâteau chaque soir sans aucune honte, jusqu''au désastre de ce soir !'::text,'mangeait'::text,'avait l''habitude de manger'::text,'était habitué à manger'::text,'Il mangeait son gâteau chaque soir sans aucune honte, jusqu''au désastre de ce soir !'::text),
(385595,42844,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her akşam hiç utanmadan onun pastasını ..., ta ki bu akşamki felakete kadar!'::text,'yerdi'::text,'yerdi'::text,'yemeye alışkındı'::text,'Her akşam hiç utanmadan onun pastasını yerdi, ta ki bu akşamki felakete kadar!'::text),
(385596,42844,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden este szégyenérzet nélkül ... a tortáját, egészen a ma esti katasztrófáig!'::text,'ette'::text,'régen ette'::text,'hozzá volt szokva, hogy egye'::text,'Minden este szégyenérzet nélkül ette a tortáját, egészen a ma esti katasztrófáig!'::text),
(385599,42845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kann es nicht vermeiden, Scham ..., wenn sie ihn mit dem Kuchen erwischt.'::text,'zu empfinden'::text,'zu empfinden'::text,'empfinden'::text,'Er kann es nicht vermeiden, Scham zu empfinden, wenn sie ihn mit dem Kuchen erwischt.'::text),
(385603,42845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не може уникнути ... сорому, коли вона ловить його з тортом.'::text,'відчуття'::text,'відчути'::text,'відчувати'::text,'Він не може уникнути відчуття сорому, коли вона ловить його з тортом.'::text),
(385602,42845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede evitar ... vergüenza cuando ella lo pilla con el pastel.'::text,'sentir'::text,'sentir'::text,'siente'::text,'No puede evitar sentir vergüenza cuando ella lo pilla con el pastel.'::text),
(385601,42845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne peut pas s''empêcher de ... de la honte quand elle le surprend avec le gâteau.'::text,'ressentir'::text,'ressentir'::text,'ressent'::text,'Il ne peut pas s''empêcher de ressentir de la honte quand elle le surprend avec le gâteau.'::text),
(385604,42845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pastayla onu yakaladığında utanç ... kaçamıyor.'::text,'hissetmekten'::text,'hissetmeye'::text,'hisset'::text,'Pastayla onu yakaladığında utanç hissetmekten kaçamıyor.'::text),
(385605,42845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem tudja elkerülni, hogy szégyent ..., amikor rajtakapja a tortával.'::text,'érezzen'::text,'érezni'::text,'érez'::text,'Nem tudja elkerülni, hogy szégyent érezzen, amikor rajtakapja a tortával.'::text),
(385608,42846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit ihrem Kuchen erwischt zu werden, war ein Moment echter Scham, ...?'::text,'oder?'::text,'nicht wahr?'::text,'stimmt''s?'::text,'Mit ihrem Kuchen erwischt zu werden, war ein Moment echter Scham, oder?'::text),
(385612,42846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бути спійманим з її тортом — це був момент справжнього сорому, ...?'::text,'правда?'::text,'так?'::text,'хіба ні?'::text,'Бути спійманим з її тортом — це був момент справжнього сорому, правда?'::text),
(385611,42846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Que te pillaran con su pastel fue un momento de verdadera vergüenza, ¿...?'::text,'verdad'::text,'no'::text,'cierto'::text,'Que te pillaran con su pastel fue un momento de verdadera vergüenza, ¿verdad?'::text),
(385610,42846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se faire prendre avec son gâteau, c''était un vrai moment de honte, ... ?'::text,'n''est-ce pas'::text,'non'::text,'hein'::text,'Se faire prendre avec son gâteau, c''était un vrai moment de honte, n''est-ce pas ?'::text),
(385613,42846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun pastasıyla yakalanmak gerçek bir utanç anıydı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Onun pastasıyla yakalanmak gerçek bir utanç anıydı, değil mi?'::text),
(385614,42846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lebukni a tortájával igazi szégyenteljes pillanat volt, ...?'::text,'ugye?'::text,'nem?'::text,'igaz?'::text,'Lebukni a tortájával igazi szégyenteljes pillanat volt, ugye?'::text),
(385644,42850,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... 30 Minuten auf den Decken, bevor die Verteilung der Anteile begann.'::text,'saßen schon'::text,'sitzen schon'::text,'saßen'::text,'Sie saßen schon 30 Minuten auf den Decken, bevor die Verteilung der Anteile begann.'::text),
(385648,42850,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... на ковдрах 30 хвилин, перш ніж почався розподіл часток.'::text,'сиділи вже'::text,'сидять вже'::text,'сиділи'::text,'Вони сиділи вже на ковдрах 30 хвилин, перш ніж почався розподіл часток.'::text),
(385647,42850,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... sentados en las mantas 30 minutos antes de que empezara el reparto de porciones.'::text,'llevaban'::text,'han estado'::text,'estaban'::text,'Ellos llevaban sentados en las mantas 30 minutos antes de que empezara el reparto de porciones.'::text),
(385646,42850,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... sur les couvertures depuis 30 minutes quand la répartition des parts a commencé.'::text,'étaient assis'::text,'sont assis'::text,'étaient assis'::text,'Ils étaient assis sur les couvertures depuis 30 minutes quand la répartition des parts a commencé.'::text),
(385649,42850,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pay dağıtımı başlamadan önce 30 dakikadır battaniyelerin üzerinde ...'::text,'oturuyorlardı'::text,'oturuyorlar'::text,'oturuyorlardı'::text,'Pay dağıtımı başlamadan önce 30 dakikadır battaniyelerin üzerinde oturuyorlardı.'::text),
(385650,42850,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már 30 perce ... a takarókon, mielőtt elkezdődött az adagok elosztása.'::text,'ültek'::text,'ülnek'::text,'ültek'::text,'Már 30 perce ültek a takarókon, mielőtt elkezdődött az adagok elosztása.'::text),
(385653,42851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Picknicks wird jeder seinen Anteil an der Pizza ...'::text,'gegessen haben'::text,'essen'::text,'am Essen sein'::text,'Bis zum Ende des Picknicks wird jeder seinen Anteil an der Pizza gegessen haben.'::text),
(385657,42851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця пікніка кожен ... свою частку піци.'::text,'вже з''їсть'::text,'з''їсть'::text,'їстиме'::text,'До кінця пікніка кожен вже з''їсть свою частку піци.'::text),
(385656,42851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del pícnic, todos ... su parte de la pizza.'::text,'se habrán comido'::text,'se comerán'::text,'estarán comiendo'::text,'Para el final del pícnic, todos se habrán comido su parte de la pizza.'::text),
(385655,42851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du pique-nique, tout le monde ... sa part de pizza.'::text,'aura mangé'::text,'mangera'::text,'sera en train de manger'::text,'D''ici la fin du pique-nique, tout le monde aura mangé sa part de pizza.'::text),
(385658,42851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Piknik bitene kadar herkes pizzadan payını ...'::text,'yemiş olacak'::text,'yiyecek'::text,'yiyor olacak'::text,'Piknik bitene kadar herkes pizzadan payını yemiş olacak.'::text),
(385659,42851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piknik végére mindenki ... a saját pizzaszeletét.'::text,'megeszi'::text,'meg fogja enni'::text,'eszi majd'::text,'A piknik végére mindenki megeszi a saját pizzaszeletét.'::text),
(385662,42852,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei Sonnenuntergang ... die Gruppe schon etwa eine Stunde lang ihren Anteil Pizza essen.'::text,'wird'::text,'wird'::text,'wird'::text,'Bei Sonnenuntergang wird die Gruppe schon etwa eine Stunde lang ihren Anteil Pizza essen.'::text),
(385666,42852,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця група ... свою частку піци приблизно годину.'::text,'їстиме вже'::text,'з''їсть'::text,'їстиме'::text,'До заходу сонця група їстиме вже свою частку піци приблизно годину.'::text),
(385665,42852,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, el grupo ... su parte de pizza aproximadamente una hora.'::text,'llevará comiendo'::text,'comerá'::text,'estará comiendo'::text,'Para el atardecer, el grupo llevará comiendo su parte de pizza aproximadamente una hora.'::text),
(385664,42852,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au coucher du soleil, le groupe ... sa part de pizza depuis environ une heure.'::text,'sera en train de manger'::text,'mangera'::text,'sera en train de manger'::text,'Au coucher du soleil, le groupe sera en train de manger sa part de pizza depuis environ une heure.'::text),
(385667,42852,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar grup yaklaşık bir saattir pizza payını ...'::text,'yiyor olacak'::text,'yiyecek'::text,'yiyor olacak'::text,'Gün batımına kadar grup yaklaşık bir saattir pizza payını yiyor olacak.'::text),
(385668,42852,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára a csoport már körülbelül egy órája ... a pizzából a részét.'::text,'eszi majd'::text,'megeszi'::text,'eszi majd'::text,'Napnyugtára a csoport már körülbelül egy órája eszi majd a pizzából a részét.'::text),
(385671,42853,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Jogger ein größeres Stück genommen hätte, ... für sie nichts übrig geblieben! Eine Katastrophe!'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn der Jogger ein größeres Stück genommen hätte, wäre für sie nichts übrig geblieben! Eine Katastrophe!'::text),
(385675,42853,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби бігун узяв більшу частку, для неї ... нічого! Катастрофа!'::text,'не залишилося б'::text,'не залишиться'::text,'не залишилося'::text,'Якби бігун узяв більшу частку, для неї не залишилося б нічого! Катастрофа!'::text),
(385674,42853,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si el corredor hubiera cogido una parte más grande, no ... nada para ella! ¡Un desastre!'::text,'habría quedado'::text,'quedará'::text,'quedó'::text,'¡Si el corredor hubiera cogido una parte más grande, no habría quedado nada para ella! ¡Un desastre!'::text),
(385673,42853,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le joggeur avait pris une plus grosse part, il ne ... rien resté pour elle ! Une catastrophe !'::text,'serait'::text,'sera'::text,'était'::text,'Si le joggeur avait pris une plus grosse part, il ne serait rien resté pour elle ! Une catastrophe !'::text),
(385676,42853,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koşucu daha büyük bir pay alsaydı, ona hiçbir şey ...! Felaket!'::text,'kalmazdı'::text,'kalmayacak'::text,'kalmadı'::text,'Koşucu daha büyük bir pay alsaydı, ona hiçbir şey kalmazdı! Felaket!'::text),
(385677,42853,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a futó nagyobb részt vett volna el, neki semmi sem ...! Katasztrófa!'::text,'maradt volna'::text,'marad majd'::text,'maradt'::text,'Ha a futó nagyobb részt vett volna el, neki semmi sem maradt volna! Katasztrófa!'::text),
(385680,42854,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie jedes Stück für sich behalten hätte, ... sie jetzt völlig allein!'::text,'wäre'::text,'wäre gewesen'::text,'wird sein'::text,'Wenn sie jedes Stück für sich behalten hätte, wäre sie jetzt völlig allein!'::text),
(385684,42854,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона залишила кожну частку собі, вона ... зараз зовсім сама!'::text,'була б'::text,'була б'::text,'буде'::text,'Якби вона залишила кожну частку собі, вона була б зараз зовсім сама!'::text),
(385683,42854,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si se hubiera quedado cada porción para ella, ahora ... completamente sola!'::text,'estaría'::text,'habría estado'::text,'estará'::text,'¡Si se hubiera quedado cada porción para ella, ahora estaría completamente sola!'::text),
(385682,42854,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait gardé chaque part pour elle, elle ... complètement seule maintenant !'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si elle avait gardé chaque part pour elle, elle serait complètement seule maintenant !'::text),
(385685,42854,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her payı kendine saklasaydı, şimdi tamamen yalnız ...!'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Her payı kendine saklasaydı, şimdi tamamen yalnız olurdu!'::text),
(385686,42854,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha minden szeletet megtartott volna magának, most teljesen egyedül ...!'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha minden szeletet megtartott volna magának, most teljesen egyedül lenne!'::text),
(385689,42855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pizza soll in perfekte Stücke ..., und niemand wird es je vergessen!'::text,'geschnitten worden sein'::text,'schneiden'::text,'schneidend'::text,'Die Pizza soll in perfekte Stücke geschnitten worden sein, und niemand wird es je vergessen!'::text),
(385693,42855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що піцу ... на ідеальні частки, і ніхто цього ніколи не забуде!'::text,'розрізали'::text,'різати'::text,'різання'::text,'Кажуть, що піцу розрізали на ідеальні частки, і ніхто цього ніколи не забуде!'::text),
(385692,42855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dicen que la pizza ... en porciones perfectas, y nadie lo olvidará jamás!'::text,'fue cortada'::text,'cortar'::text,'cortando'::text,'¡Dicen que la pizza fue cortada en porciones perfectas, y nadie lo olvidará jamás!'::text),
(385691,42855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que la pizza ... en parts parfaites, et personne ne l''oubliera jamais !'::text,'a été coupée'::text,'couper'::text,'coupant'::text,'On dit que la pizza a été coupée en parts parfaites, et personne ne l''oubliera jamais !'::text),
(385694,42855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pizzanın mükemmel paylara ... söyleniyor ve bunu kimse asla unutmayacak!'::text,'kesildiği'::text,'kesmeyi'::text,'keserek'::text,'Pizzanın mükemmel paylara kesildiği söyleniyor ve bunu kimse asla unutmayacak!'::text),
(385695,42855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag a pizzát tökéletes szeletekre ..., és ezt soha senki nem fogja elfelejteni!'::text,'vágták'::text,'vágni'::text,'vágva'::text,'Állítólag a pizzát tökéletes szeletekre vágták, és ezt soha senki nem fogja elfelejteni!'::text),
(385698,42856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, der Jogger hat angeblich abgestritten, mehr als seinen Anteil ...'::text,'genommen zu haben'::text,'zu nehmen'::text,'nahm'::text,'Bestie, der Jogger hat angeblich abgestritten, mehr als seinen Anteil genommen zu haben.'::text),
(385702,42856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, бігун заперечив, що ... більше за свою частку.'::text,'взяв'::text,'взяти'::text,'взяв'::text,'Подруго, кажуть, бігун заперечив, що взяв більше за свою частку.'::text),
(385701,42856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el corredor negó ... más de su parte.'::text,'haber cogido'::text,'coger'::text,'cogió'::text,'Tía, al parecer el corredor negó haber cogido más de su parte.'::text),
(385700,42856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment le joggeur a nié ... plus que sa part.'::text,'avoir pris'::text,'prendre'::text,'a pris'::text,'Bestie, apparemment le joggeur a nié avoir pris plus que sa part.'::text),
(385703,42856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, koşucu kendi payından fazlasını ... inkâr etmiş.'::text,'aldığını'::text,'almayı'::text,'aldı'::text,'Kanka, koşucu kendi payından fazlasını aldığını inkâr etmiş.'::text),
(385704,42856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a futó tagadta, hogy többet ... a részénél.'::text,'vett el'::text,'elvenni'::text,'vett el'::text,'Csajszi, állítólag a futó tagadta, hogy többet vett el a részénél.'::text),
(385707,42857,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jogger ... nicht fragen müssen, bevor er ein Stück nahm, denn sie hatte es zuerst angeboten.'::text,'hätte'::text,'durfte'::text,'konnte'::text,'Der Jogger hätte nicht fragen müssen, bevor er ein Stück nahm, denn sie hatte es zuerst angeboten.'::text),
(385711,42857,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бігунові ... питати, перш ніж узяти частку, бо вона запропонувала першою.'::text,'не треба було'::text,'не можна було'::text,'не вдалося'::text,'Бігунові не треба було питати, перш ніж узяти частку, бо вона запропонувала першою.'::text),
(385710,42857,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El corredor no ... preguntado antes de coger una porción, porque ella se la ofreció primero.'::text,'tenía por qué haber'::text,'debía haber'::text,'pudo'::text,'El corredor no tenía por qué haber preguntado antes de coger una porción, porque ella se la ofreció primero.'::text),
(385709,42857,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joggeur ... demandé avant de prendre une part, car elle l''a proposée en premier.'::text,'n''avait pas besoin d''avoir'::text,'n''aurait pas dû'::text,'n''a pas pu'::text,'Le joggeur n''avait pas besoin d''avoir demandé avant de prendre une part, car elle l''a proposée en premier.'::text),
(385712,42857,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koşucunun pay almadan önce ... gerek yoktu, çünkü önce kadın teklif etti.'::text,'sormasına'::text,'sormamalıydı'::text,'soramadı'::text,'Koşucunun pay almadan önce sormasına gerek yoktu, çünkü önce kadın teklif etti.'::text),
(385713,42857,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A futónak nem ... megkérdeznie, mielőtt elvett egy szeletet, mert a lány kínálta először.'::text,'kellett volna'::text,'lett volna szabad'::text,'tudott'::text,'A futónak nem kellett volna megkérdeznie, mielőtt elvett egy szeletet, mert a lány kínálta először.'::text),
(385716,42858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... bekommen Fremde ein Stück Picknick-Pizza wie dieses.'::text,''::text,NULL::text,NULL::text,'Selten bekommen Fremde ein Stück Picknick-Pizza wie dieses.'::text),
(385720,42858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... незнайомці отримують частку такої піци з пікніка.'::text,''::text,NULL::text,NULL::text,'Рідко незнайомці отримують частку такої піци з пікніка.'::text),
(385719,42858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... reciben unos desconocidos una porción de una pizza de pícnic como esta.'::text,''::text,NULL::text,NULL::text,'Rara vez reciben unos desconocidos una porción de una pizza de pícnic como esta.'::text),
(385718,42858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... des inconnus reçoivent une part d''une pizza de pique-nique comme celle-ci.'::text,''::text,NULL::text,NULL::text,'Rarement des inconnus reçoivent une part d''une pizza de pique-nique comme celle-ci.'::text),
(385721,42858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yabancılar nadiren ... böyle bir piknik pizzasından pay alır.'::text,''::text,NULL::text,NULL::text,'Yabancılar nadiren böyle bir piknik pizzasından pay alır.'::text),
(385722,42858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Idegenek ritkán ... kapnak részt egy ilyen piknikpizzából.'::text,''::text,NULL::text,NULL::text,'Idegenek ritkán kapnak részt egy ilyen piknikpizzából.'::text),
(385896,42878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... das Sofa über den Boden, als das Sonnenlicht hereinkam, und ehrlich, was für ein Zimmer.'::text,'schobst gerade'::text,'schobst'::text,'hast geschoben'::text,'Du schobst gerade das Sofa über den Boden, als das Sonnenlicht hereinkam, und ehrlich, was für ein Zimmer.'::text),
(385900,42878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... диван по підлозі, коли зайшло сонячне світло, і чесно, яка кімната.'::text,'пересувала'::text,'пересунула'::text,'пересунула'::text,'Ти пересувала диван по підлозі, коли зайшло сонячне світло, і чесно, яка кімната.'::text),
(385899,42878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... el sofá por el suelo cuando entró la luz del sol y, sinceramente, vaya salón.'::text,'estabas moviendo'::text,'moviste'::text,'has movido'::text,'Tú estabas moviendo el sofá por el suelo cuando entró la luz del sol y, sinceramente, vaya salón.'::text),
(385898,42878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... le canapé sur le sol quand la lumière du soleil est entrée, et franchement, quelle pièce.'::text,'déplaçais'::text,'as déplacé'::text,'as déplacé'::text,'Tu déplaçais le canapé sur le sol quand la lumière du soleil est entrée, et franchement, quelle pièce.'::text),
(385901,42878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş ışığı içeri girdiğinde sen kanepeyi yerde ..., ve açıkçası, ne oda ama.'::text,'kaydırıyordun'::text,'kaydırdın'::text,'kaydırdın'::text,'Güneş ışığı içeri girdiğinde sen kanepeyi yerde kaydırıyordun, ve açıkçası, ne oda ama.'::text),
(385902,42878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a kanapét a padlón, amikor besütött a nap, és őszintén, micsoda szoba.'::text,'tologattad'::text,'eltoltad'::text,'eltoltad'::text,'Épp tologattad a kanapét a padlón, amikor besütött a nap, és őszintén, micsoda szoba.'::text),
(385905,42879,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit drei Stunden Möbel herum, für ein leicht anderes Zimmer.'::text,'schiebt'::text,'schiebt'::text,'schiebt'::text,'Sie schiebt seit drei Stunden Möbel herum, für ein leicht anderes Zimmer.'::text),
(385909,42879,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... меблі вже три години заради трохи іншої кімнати.'::text,'пересуває'::text,'пересуває'::text,'пересуває'::text,'Вона пересуває меблі вже три години заради трохи іншої кімнати.'::text),
(385908,42879,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... muebles desde hace tres horas para una habitación apenas distinta.'::text,'lleva moviendo'::text,'está moviendo'::text,'mueve'::text,'Ella lleva moviendo muebles desde hace tres horas para una habitación apenas distinta.'::text),
(385907,42879,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des meubles depuis trois heures pour une pièce à peine différente.'::text,'déplace'::text,'déplace'::text,'déplace'::text,'Elle déplace des meubles depuis trois heures pour une pièce à peine différente.'::text),
(385910,42879,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz farklı bir oda için üç saattir mobilyaları ...'::text,'kaydırıyor'::text,'kaydırıyor'::text,'kaydırır'::text,'Biraz farklı bir oda için üç saattir mobilyaları kaydırıyor.'::text),
(385911,42879,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Három órája ... a bútorokat egy kicsit más szobáért.'::text,'tologatja'::text,'tologatja'::text,'tologatja'::text,'Három órája tologatja a bútorokat egy kicsit más szobáért.'::text),
(385914,42880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Couchtisch auf den Teppich und ordnete dann natürlich die Bücher neu.'::text,'schob'::text,'schob gerade'::text,'hat geschoben'::text,'Sie schob den Couchtisch auf den Teppich und ordnete dann natürlich die Bücher neu.'::text),
(385918,42880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... журнальний столик на килим, а потім, звісно, переставила книжки.'::text,'пересунула'::text,'пересувала'::text,'пересунула'::text,'Вона пересунула журнальний столик на килим, а потім, звісно, переставила книжки.'::text),
(385917,42880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la mesa de centro sobre la alfombra y luego, por supuesto, reordenó los libros.'::text,'movió'::text,'estaba moviendo'::text,'ha movido'::text,'Ella movió la mesa de centro sobre la alfombra y luego, por supuesto, reordenó los libros.'::text),
(385916,42880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la table basse sur le tapis et puis, bien sûr, a réorganisé les livres.'::text,'a poussé'::text,'poussait'::text,'a poussé'::text,'Elle a poussé la table basse sur le tapis et puis, bien sûr, a réorganisé les livres.'::text),
(385919,42880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehpayı halının üstüne ... ve sonra, tabii ki, kitapları yeniden dizdi.'::text,'kaydırdı'::text,'kaydırıyordu'::text,'kaydırdı'::text,'Sehpayı halının üstüne kaydırdı ve sonra, tabii ki, kitapları yeniden dizdi.'::text),
(385920,42880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a dohányzóasztalt a szőnyegre, aztán persze átrendezte a könyveket.'::text,'Áttolta'::text,'Tolta'::text,'Áttolta'::text,'Áttolta a dohányzóasztalt a szőnyegre, aztán persze átrendezte a könyveket.'::text),
(385932,42882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, ich ... mein Sofa so verschieben, mein Wohnzimmer ist eine totale Katastrophe!'::text,'könnte'::text,'kann'::text,'werde'::text,'Ich wünschte, ich könnte mein Sofa so verschieben, mein Wohnzimmer ist eine totale Katastrophe!'::text),
(385936,42882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ж я ... так пересунути свій диван, моя вітальня — повна катастрофа!'::text,'міг'::text,'можу'::text,'буду'::text,'Якби ж я міг так пересунути свій диван, моя вітальня — повна катастрофа!'::text),
(385935,42882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá ... mi sofá así, mi salón es un desastre total!'::text,'pudiera mover'::text,'puedo mover'::text,'moveré'::text,'¡Ojalá pudiera mover mi sofá así, mi salón es un desastre total!'::text),
(385934,42882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement je ... mon canapé comme ça, mon salon est une catastrophe totale !'::text,'pouvais déplacer'::text,'peux déplacer'::text,'déplacerai'::text,'Si seulement je pouvais déplacer mon canapé comme ça, mon salon est une catastrophe totale !'::text),
(385937,42882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke ben de kanepemi böyle ..., oturma odam tam bir felaket!'::text,'kaydırabilsem'::text,'kaydırabilirim'::text,'kaydıracağım'::text,'Keşke ben de kanepemi böyle kaydırabilsem, oturma odam tam bir felaket!'::text),
(385938,42882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak én is így ... a kanapémat, a nappalim egy totális katasztrófa!'::text,'tudnám eltolni'::text,'tudom eltolni'::text,'fogom eltolni'::text,'Bárcsak én is így tudnám eltolni a kanapémat, a nappalim egy totális katasztrófa!'::text),
(385941,42883,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Sofa, ... sie über den Boden geschoben hat, steht jetzt zum Fenster.'::text,'das'::text,'das'::text,'wer'::text,'Das Sofa, das sie über den Boden geschoben hat, steht jetzt zum Fenster.'::text),
(385945,42883,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Диван, ... вона пересунула по підлозі, тепер стоїть до вікна.'::text,'який'::text,'що'::text,'хто'::text,'Диван, який вона пересунула по підлозі, тепер стоїть до вікна.'::text),
(385944,42883,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sofá, ... ella movió por el suelo, ahora mira hacia la ventana.'::text,'que'::text,'que'::text,'quien'::text,'El sofá, que ella movió por el suelo, ahora mira hacia la ventana.'::text),
(385943,42883,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canapé, ... elle a poussé sur le sol, fait maintenant face à la fenêtre.'::text,'qu'''::text,'qu'''::text,'qui'::text,'Le canapé, qu'' elle a poussé sur le sol, fait maintenant face à la fenêtre.'::text),
(385946,42883,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yerde ... kaydırdığı kanepe artık pencereye bakıyor.'::text,''::text,NULL::text,NULL::text,'Yerde kaydırdığı kanepe artık pencereye bakıyor.'::text),
(385947,42883,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kanapé, ... a padlón áttolt, most az ablak felé néz.'::text,'amelyet'::text,'amit'::text,'aki'::text,'A kanapé, amelyet a padlón áttolt, most az ablak felé néz.'::text),
(385950,42884,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des Verschiebens des schweren Sofas hatte sie noch Energie, das Bild aufzuhängen.'::text,'Trotz'::text,'Obwohl'::text,'Im Falle'::text,'Trotz des Verschiebens des schweren Sofas hatte sie noch Energie, das Bild aufzuhängen.'::text),
(385954,42884,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... те, що пересунула важкий диван, вона ще мала сили повісити картину.'::text,'Попри'::text,'Хоча'::text,'У разі'::text,'Попри те, що пересунула важкий диван, вона ще мала сили повісити картину.'::text),
(385953,42884,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mover el sofá pesado, todavía tenía energía para colgar el cuadro.'::text,'A pesar de'::text,'Aunque'::text,'En caso de'::text,'A pesar de mover el sofá pesado, todavía tenía energía para colgar el cuadro.'::text),
(385952,42884,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... avoir déplacé le lourd canapé, elle avait encore l''énergie d''accrocher le tableau.'::text,'Malgré'::text,'Bien que'::text,'En cas de'::text,'Malgré avoir déplacé le lourd canapé, elle avait encore l''énergie d''accrocher le tableau.'::text),
(385955,42884,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağır kanepeyi kaydırmasına ..., tabloyu asacak enerjisi hâlâ vardı.'::text,'rağmen'::text,'karşın'::text,'durumunda'::text,'Ağır kanepeyi kaydırmasına rağmen, tabloyu asacak enerjisi hâlâ vardı.'::text),
(385956,42884,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... eltolta a nehéz kanapét, még maradt ereje felakasztani a képet.'::text,'Annak ellenére, hogy'::text,'Bár'::text,'Abban az esetben, ha'::text,'Annak ellenére, hogy eltolta a nehéz kanapét, még maradt ereje felakasztani a képet.'::text),
(385959,42885,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie anfing, wusste sie, dass sie jedes Möbelstück im Zimmer ...'::text,'verschieben würde'::text,'verschieben wird'::text,'gerade verschiebt'::text,'Als sie anfing, wusste sie, dass sie jedes Möbelstück im Zimmer verschieben würde.'::text),
(385963,42885,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона почала, вона знала, що ... кожен предмет меблів у кімнаті.'::text,'пересуне'::text,'пересуне'::text,'пересуває'::text,'Коли вона почала, вона знала, що пересуне кожен предмет меблів у кімнаті.'::text),
(385962,42885,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando empezó, sabía que ... cada mueble de la habitación.'::text,'movería'::text,'moverá'::text,'está moviendo'::text,'Cuando empezó, sabía que movería cada mueble de la habitación.'::text),
(385961,42885,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle a commencé, elle savait qu''elle ... chaque meuble de la pièce.'::text,'déplacerait'::text,'déplacera'::text,'déplace'::text,'Quand elle a commencé, elle savait qu''elle déplacerait chaque meuble de la pièce.'::text),
(385964,42885,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başladığında, odadaki her mobilyayı ... biliyordu.'::text,'kaydıracağını'::text,'kaydıracağını'::text,'kaydırdığını'::text,'Başladığında, odadaki her mobilyayı kaydıracağını biliyordu.'::text),
(385965,42885,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor elkezdte, tudta, hogy a szobában minden bútort ...'::text,'el fog tolni'::text,'el fog tolni'::text,'tologat'::text,'Amikor elkezdte, tudta, hogy a szobában minden bútort el fog tolni.'::text),
(385977,42887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... jedes Teil verschoben, bevor du dich hingesetzt hast, und ehrlich, der Platz fürs Sofa ist perfekt.'::text,'hattest'::text,'hast'::text,'warst gerade'::text,'Du hattest jedes Teil verschoben, bevor du dich hingesetzt hast, und ehrlich, der Platz fürs Sofa ist perfekt.'::text),
(385981,42887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... кожну річ, перш ніж сіла, і чесно, це місце для дивана ідеальне.'::text,'вже пересунула'::text,'пересунула'::text,'пересувала'::text,'Ти вже пересунула кожну річ, перш ніж сіла, і чесно, це місце для дивана ідеальне.'::text),
(385980,42887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... cada mueble antes de sentarte y, sinceramente, ese sitio para el sofá es perfecto.'::text,'habías movido'::text,'moviste'::text,'estabas moviendo'::text,'Tú habías movido cada mueble antes de sentarte y, sinceramente, ese sitio para el sofá es perfecto.'::text),
(385979,42887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... chaque meuble avant de t''asseoir, et franchement, cet emplacement pour le canapé est parfait.'::text,'avais déplacé'::text,'as déplacé'::text,'déplaçais'::text,'Tu avais déplacé chaque meuble avant de t''asseoir, et franchement, cet emplacement pour le canapé est parfait.'::text),
(385982,42887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oturmadan önce her parçayı ..., ve açıkçası, o kanepe yeri mükemmel.'::text,'kaydırmıştın'::text,'kaydırdın'::text,'kaydırıyordun'::text,'Oturmadan önce her parçayı kaydırmıştın, ve açıkçası, o kanepe yeri mükemmel.'::text),
(385983,42887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt leültél, már minden darabot ..., és őszintén, az a kanapéhely tökéletes.'::text,'arrébb toltál'::text,'arrébb toltál'::text,'tologattál'::text,'Mielőtt leültél, már minden darabot arrébb toltál, és őszintén, az a kanapéhely tökéletes.'::text),
(385986,42888,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis nächste Woche ... du das Sofa wieder verschoben haben, ganz ehrlich.'::text,'wirst'::text,'wirst'::text,'verschiebst'::text,'Bis nächste Woche wirst du das Sofa wieder verschoben haben, ganz ehrlich.'::text),
(385990,42888,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступного тижня ти знову ... цей диван, чесно кажучи.'::text,'пересунеш'::text,'пересунеш'::text,'пересуваєш'::text,'До наступного тижня ти знову пересунеш цей диван, чесно кажучи.'::text),
(385989,42888,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la semana que viene, ya ... ese sofá otra vez, no te voy a mentir.'::text,'habrás movido'::text,'moverás'::text,'mueves'::text,'Para la semana que viene, ya habrás movido ese sofá otra vez, no te voy a mentir.'::text),
(385988,42888,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la semaine prochaine, tu ... encore ce canapé, je vais pas mentir.'::text,'auras déplacé'::text,'déplaceras'::text,'déplaces'::text,'D''ici la semaine prochaine, tu auras déplacé encore ce canapé, je vais pas mentir.'::text),
(385991,42888,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek haftaya kadar o kanepeyi yine ..., yalan yok.'::text,'kaydırmış olacaksın'::text,'kaydıracaksın'::text,'kaydırıyorsun'::text,'Gelecek haftaya kadar o kanepeyi yine kaydırmış olacaksın, yalan yok.'::text),
(385992,42888,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő hétig megint ... azt a kanapét, nem hazudok.'::text,'el fogod tolni'::text,'el fogod tolni'::text,'eltolod'::text,'Jövő hétig megint el fogod tolni azt a kanapét, nem hazudok.'::text),
(381036,42338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn sie mit dem Gewehr alle fünf Ziele trifft, ... sie das Rennen, ohne Witz.'::text,'gewinnt'::text,'würde gewinnen'::text,'gewann'::text,'Bro, wenn sie mit dem Gewehr alle fünf Ziele trifft, gewinnt sie das Rennen, ohne Witz.'::text),
(381040,42338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо вона влучить у всі п''ять мішеней із цієї гвинтівки, вона ... гонку, без жартів.'::text,'виграє'::text,'виграла б'::text,'виграла'::text,'Бро, якщо вона влучить у всі п''ять мішеней із цієї гвинтівки, вона виграє гонку, без жартів.'::text),
(381039,42338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si acierta los cinco blancos con ese rifle, ... la carrera, en serio.'::text,'ganará'::text,'ganaría'::text,'ganó'::text,'Bro, si acierta los cinco blancos con ese rifle, ganará la carrera, en serio.'::text),
(381038,42338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si elle touche les cinq cibles avec ce fusil, elle ... la course, sans mentir.'::text,'gagnera'::text,'gagnerait'::text,'a gagné'::text,'Frérot, si elle touche les cinq cibles avec ce fusil, elle gagnera la course, sans mentir.'::text),
(381041,42338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o tüfekle beş hedefin hepsini vurursa yarışı ..., yemin ederim.'::text,'kazanacak'::text,'kazanırdı'::text,'kazandı'::text,'Kanka, o tüfekle beş hedefin hepsini vurursa yarışı kazanacak, yemin ederim.'::text),
(381042,42338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha azzal a puskával mind az öt célt eltalálja, ... a versenyt, komolyan.'::text,'megnyeri'::text,'megnyerné'::text,'megnyerte'::text,'Tesó, ha azzal a puskával mind az öt célt eltalálja, megnyeri a versenyt, komolyan.'::text),
(381045,42339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihr Gewehr leichter wäre, ... sie es müheloser halten.'::text,'würde'::text,'wird'::text,'hält'::text,'Wenn ihr Gewehr leichter wäre, würde sie es müheloser halten.'::text),
(381049,42339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби її гвинтівка була легшою, вона ... її легше.'::text,'тримала б'::text,'триматиме'::text,'тримає'::text,'Якби її гвинтівка була легшою, вона тримала б її легше.'::text),
(381048,42339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su rifle fuera más ligero, lo ... con más facilidad.'::text,'sostendría'::text,'sostendrá'::text,'sostiene'::text,'Si su rifle fuera más ligero, lo sostendría con más facilidad.'::text),
(381047,42339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son fusil était plus léger, elle le ... plus facilement.'::text,'tiendrait'::text,'tiendra'::text,'tient'::text,'Si son fusil était plus léger, elle le tiendrait plus facilement.'::text),
(381050,42339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüfeği daha hafif olsaydı, onu daha kolay ...'::text,'tutardı'::text,'tutacak'::text,'tutuyor'::text,'Tüfeği daha hafif olsaydı, onu daha kolay tutardı.'::text),
(381051,42339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha könnyebb lenne a puskája, könnyebben ...'::text,'tartaná'::text,'fogja tartani'::text,'tartja'::text,'Ha könnyebb lenne a puskája, könnyebben tartaná.'::text),
(381054,42340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Gewehr ... bei jedem Schuss fest an der Schulter.'::text,'wird gehalten'::text,'hält'::text,'hält gerade'::text,'Das Gewehr wird gehalten bei jedem Schuss fest an der Schulter.'::text),
(381058,42340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гвинтівку ... міцно притиснутою до плеча під час кожного пострілу.'::text,'тримають'::text,'тримає'::text,'тримає'::text,'Гвинтівку тримають міцно притиснутою до плеча під час кожного пострілу.'::text),
(381057,42340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El rifle ... firmemente contra su hombro durante cada disparo.'::text,'se sujeta'::text,'sujeta'::text,'está sujetando'::text,'El rifle se sujeta firmemente contra su hombro durante cada disparo.'::text),
(381056,42340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fusil ... fermement contre son épaule à chaque tir.'::text,'est tenu'::text,'tient'::text,'est en train de tenir'::text,'Le fusil est tenu fermement contre son épaule à chaque tir.'::text),
(381059,42340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüfek her atışta omzuna sıkıca ...'::text,'tutulur'::text,'tutar'::text,'tutuyor'::text,'Tüfek her atışta omzuna sıkıca tutulur.'::text),
(381060,42340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A puskát minden lövés alatt erősen a vállához ...'::text,'szorítják'::text,'szorítja'::text,'szorítja éppen'::text,'A puskát minden lövés alatt erősen a vállához szorítják.'::text),
(381072,42342,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ihr Gewehr ... neu sein, weil sie mir gesagt hat, dass sie es erst letzte Woche bekommen hat.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Hör mal, ihr Gewehr muss neu sein, weil sie mir gesagt hat, dass sie es erst letzte Woche bekommen hat.'::text),
(381076,42342,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, її гвинтівка ... бути новою, бо вона сказала мені, що отримала її лише минулого тижня.'::text,'мусить'::text,'може'::text,'не може'::text,'Слухай, її гвинтівка мусить бути новою, бо вона сказала мені, що отримала її лише минулого тижня.'::text),
(381075,42342,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, su rifle ... ser nuevo, porque me dijo que lo consiguió la semana pasada.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Oye, su rifle debe de ser nuevo, porque me dijo que lo consiguió la semana pasada.'::text),
(381074,42342,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, son fusil ... être neuf, parce qu''elle m''a dit qu''elle l''avait eu seulement la semaine dernière.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Écoute, son fusil doit être neuf, parce qu''elle m''a dit qu''elle l''avait eu seulement la semaine dernière.'::text),
(381077,42342,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, tüfeği yeni ..., çünkü bana onu daha geçen hafta aldığını söyledi.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Dinle, tüfeği yeni olmalı, çünkü bana onu daha geçen hafta aldığını söyledi.'::text),
(381078,42342,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a puskája ... új, mert azt mondta, csak múlt héten kapta.'::text,'biztosan'::text,'talán'::text,'nem lehet'::text,'Figyelj, a puskája biztosan új, mert azt mondta, csak múlt héten kapta.'::text),
(381081,42343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, die Athletin, ... Gewehr alle fünf Ziele getroffen hat, ist angeblich die Favoritin.'::text,'deren'::text,'die'::text,'welche'::text,'Hör mal, die Athletin, deren Gewehr alle fünf Ziele getroffen hat, ist angeblich die Favoritin.'::text),
(381085,42343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, спортсменка, ... гвинтівка влучила в усі п''ять мішеней, кажуть, фаворитка.'::text,'чия'::text,'яка'::text,'котра'::text,'Слухай, спортсменка, чия гвинтівка влучила в усі п''ять мішеней, кажуть, фаворитка.'::text),
(381084,42343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la atleta ... rifle acertó los cinco blancos es la favorita, al parecer.'::text,'cuyo'::text,'que'::text,'la cual'::text,'Oye, la atleta cuyo rifle acertó los cinco blancos es la favorita, al parecer.'::text),
(381083,42343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, l''athlète ... le fusil a touché les cinq cibles est la favorite, apparemment.'::text,'dont'::text,'qui'::text,'lequel'::text,'Écoute, l''athlète dont le fusil a touché les cinq cibles est la favorite, apparemment.'::text),
(381086,42343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ... tüfeği beş hedefin hepsini vuran sporcu favoriymiş.'::text,''::text,NULL::text,NULL::text,'Dinle, tüfeği beş hedefin hepsini vuran sporcu favoriymiş.'::text),
(381087,42343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a sportoló, ... puskája mind az öt célt eltalálta, állítólag a favorit.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Figyelj, a sportoló, akinek a puskája mind az öt célt eltalálta, állítólag a favorit.'::text),
(381090,42344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, sie hat mir erzählt, dass sie monatelang jeden Tag mit ihrem Gewehr ...'::text,'trainiert hatte'::text,'trainiert hat'::text,'trainiert'::text,'Also, sie hat mir erzählt, dass sie monatelang jeden Tag mit ihrem Gewehr trainiert hatte.'::text),
(381094,42344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, вона сказала мені, що ... зі своєю гвинтівкою щодня протягом місяців.'::text,'тренувалася'::text,'тренувалася'::text,'тренується'::text,'Коротше, вона сказала мені, що тренувалася зі своєю гвинтівкою щодня протягом місяців.'::text),
(381093,42344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues me dijo que ... con su rifle todos los días durante meses.'::text,'había entrenado'::text,'ha entrenado'::text,'entrena'::text,'Vale, pues me dijo que había entrenado con su rifle todos los días durante meses.'::text),
(381092,42344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, elle m''a dit qu''elle ... avec son fusil tous les jours pendant des mois.'::text,'s''était entraînée'::text,'s''est entraînée'::text,'s''entraîne'::text,'Bon, elle m''a dit qu''elle s''était entraînée avec son fusil tous les jours pendant des mois.'::text),
(381095,42344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, bana aylardır her gün tüfeğiyle ... söyledi.'::text,'antrenman yaptığını'::text,'antrenman yaptığını'::text,'antrenman yapıyor'::text,'Neyse, bana aylardır her gün tüfeğiyle antrenman yaptığını söyledi.'::text),
(381096,42344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, hogy hónapokig minden nap ... a puskájával.'::text,'edzett'::text,'edzett'::text,'edz'::text,'Szóval azt mondta, hogy hónapokig minden nap edzett a puskájával.'::text),
(381099,42345,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... Angst, ein Gewehr zu halten? Ehrlich, jetzt nicht mehr.'::text,'hattest früher'::text,'hattest immer'::text,'warst gewohnt'::text,'Du hattest früher Angst, ein Gewehr zu halten? Ehrlich, jetzt nicht mehr.'::text),
(381103,42345,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... боялася тримати гвинтівку? Чесно, вже ні.'::text,'колись'::text,'бувало'::text,'звикла'::text,'Ти колись боялася тримати гвинтівку? Чесно, вже ні.'::text),
(381102,42345,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Tú ... tener miedo de sujetar un rifle? Sinceramente, ya no.'::text,'solías'::text,'solías'::text,'estabas acostumbrada a'::text,'¿Tú solías tener miedo de sujetar un rifle? Sinceramente, ya no.'::text),
(381101,42345,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, tu ... peur de tenir un fusil ? Franchement, plus maintenant.'::text,'avais'::text,'avais'::text,'étais habituée à avoir'::text,'Avant, tu avais peur de tenir un fusil ? Franchement, plus maintenant.'::text),
(381104,42345,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen tüfek tutmaktan ...? Açıkçası, artık değil.'::text,'korkardın'::text,'korkardın'::text,'korkmaya alışkındın'::text,'Sen tüfek tutmaktan korkardın? Açıkçası, artık değil.'::text),
(381105,42345,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... féltél puskát fogni? Őszintén, már nem.'::text,'régen'::text,'mindig'::text,'hozzá voltál szokva, hogy'::text,'Te régen féltél puskát fogni? Őszintén, már nem.'::text),
(381108,42346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast es geschafft, das Gewehr fünf Schüsse lang perfekt ruhig ..., ehrlich.'::text,'zu halten'::text,'haltend'::text,'halten'::text,'Du hast es geschafft, das Gewehr fünf Schüsse lang perfekt ruhig zu halten, ehrlich.'::text),
(381112,42346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тобі вдалося ... гвинтівку ідеально нерухомо п''ять пострілів, чесно.'::text,'втримати'::text,'тримання'::text,'тримати'::text,'Тобі вдалося втримати гвинтівку ідеально нерухомо п''ять пострілів, чесно.'::text),
(381111,42346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Conseguiste ... el rifle perfectamente quieto durante cinco disparos, en serio.'::text,'mantener'::text,'manteniendo'::text,'mantener'::text,'Conseguiste mantener el rifle perfectamente quieto durante cinco disparos, en serio.'::text),
(381110,42346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as réussi à ... le fusil parfaitement immobile pendant cinq tirs, franchement.'::text,'tenir'::text,'tenant'::text,'tenir'::text,'Tu as réussi à tenir le fusil parfaitement immobile pendant cinq tirs, franchement.'::text),
(381113,42346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüfeği beş atış boyunca kusursuzca sabit ... başardın, açıkçası.'::text,'tutmayı'::text,'tutarak'::text,'tut'::text,'Tüfeği beş atış boyunca kusursuzca sabit tutmayı başardın, açıkçası.'::text),
(381114,42346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sikerült tökéletesen mozdulatlanul ... a puskát öt lövésen át, őszintén.'::text,'tartanod'::text,'tartva'::text,'tartani'::text,'Sikerült tökéletesen mozdulatlanul tartanod a puskát öt lövésen át, őszintén.'::text),
(381126,42348,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sie den Kopf vom Gewehr, offensichtlich unzufrieden mit fünf Treffern.'::text,'hebt'::text,'hebt'::text,'hat gehoben'::text,'Gerade hebt sie den Kopf vom Gewehr, offensichtlich unzufrieden mit fünf Treffern.'::text),
(381130,42348,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз вона ... голову від гвинтівки, явно незадоволена п''ятьма влучаннями.'::text,'піднімає'::text,'піднімає'::text,'підняла'::text,'Саме зараз вона піднімає голову від гвинтівки, явно незадоволена п''ятьма влучаннями.'::text),
(381129,42348,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... la cabeza del rifle, claramente descontenta con cinco aciertos.'::text,'está levantando'::text,'levanta'::text,'ha levantado'::text,'Ahora mismo está levantando la cabeza del rifle, claramente descontenta con cinco aciertos.'::text),
(381128,42348,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... la tête du fusil, visiblement mécontente de cinq touches.'::text,'relève'::text,'relève'::text,'a relevé'::text,'En ce moment, elle relève la tête du fusil, visiblement mécontente de cinq touches.'::text),
(381131,42348,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda başını tüfekten ..., beş isabetten belli ki memnun değil.'::text,'kaldırıyor'::text,'kaldırır'::text,'kaldırdı'::text,'Şu anda başını tüfekten kaldırıyor, beş isabetten belli ki memnun değil.'::text),
(381132,42348,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a fejét a puskáról, láthatóan elégedetlen az öt találattal.'::text,'emeli fel'::text,'felemeli'::text,'felemelte'::text,'Épp most emeli fel a fejét a puskáról, láthatóan elégedetlen az öt találattal.'::text),
(377544,41950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um sechs Uhr ... sie schon seit fünf Stunden Geschenke in der Stadt kaufen.'::text,'wird'::text,'wird'::text,'kauft'::text,'Um sechs Uhr wird sie schon seit fünf Stunden Geschenke in der Stadt kaufen.'::text),
(377548,41950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О шостій вона ... подарунки в місті вже п''ять годин.'::text,'купуватиме'::text,'купуватиме'::text,'купить'::text,'О шостій вона купуватиме подарунки в місті вже п''ять годин.'::text),
(377547,41950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A las seis, ella ... cinco horas comprando regalos en la ciudad.'::text,'llevará'::text,'estará'::text,'comprará'::text,'A las seis, ella llevará cinco horas comprando regalos en la ciudad.'::text),
(377546,41950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À six heures, elle ... des cadeaux en ville depuis cinq heures.'::text,'sera en train d''acheter'::text,'sera en train d''acheter'::text,'achètera'::text,'À six heures, elle sera en train d''acheter des cadeaux en ville depuis cinq heures.'::text),
(377549,41950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat altıda şehirde beş saattir hediye ...'::text,'alıyor olacak'::text,'alıyor olacak'::text,'alacak'::text,'Saat altıda şehirde beş saattir hediye alıyor olacak.'::text),
(377550,41950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hat órára már öt órája ... ajándékokat a városban.'::text,'vásárol majd'::text,'vásárol majd'::text,'vesz majd'::text,'Hat órára már öt órája vásárol majd ajándékokat a városban.'::text),
(377553,41951,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der olivgrüne Mantel zu teuer gewesen wäre, ... sie ihn nicht gekauft.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn der olivgrüne Mantel zu teuer gewesen wäre, hätte sie ihn nicht gekauft.'::text),
(377557,41951,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби оливкове пальто було надто дорогим, вона ...'::text,'не купила б його'::text,'не купить його'::text,'не купила його'::text,'Якби оливкове пальто було надто дорогим, вона не купила б його.'::text),
(377556,41951,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el abrigo verde oliva hubiera sido demasiado caro, ella no lo ...'::text,'habría comprado'::text,'comprará'::text,'compró'::text,'Si el abrigo verde oliva hubiera sido demasiado caro, ella no lo habría comprado.'::text),
(377555,41951,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le manteau olive avait été trop cher, elle ...'::text,'ne l''aurait pas acheté'::text,'ne l''achètera pas'::text,'ne l''a pas acheté'::text,'Si le manteau olive avait été trop cher, elle ne l''aurait pas acheté.'::text),
(377558,41951,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zeytin yeşili mont çok pahalı olsaydı, onu ...'::text,'almazdı'::text,'almayacak'::text,'almadı'::text,'Zeytin yeşili mont çok pahalı olsaydı, onu almazdı.'::text),
(377559,41951,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az olajzöld kabát túl drága lett volna, ...'::text,'nem vette volna meg'::text,'nem fogja megvenni'::text,'nem vette meg'::text,'Ha az olajzöld kabát túl drága lett volna, nem vette volna meg.'::text),
(377562,41952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte sie den olivgrünen Mantel nicht gekauft, ... ihre Geschenktüte jetzt viel leichter. Offensichtlich.'::text,'wäre'::text,'wäre gewesen'::text,'wird sein'::text,'Hätte sie den olivgrünen Mantel nicht gekauft, wäre ihre Geschenktüte jetzt viel leichter. Offensichtlich.'::text),
(377566,41952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не купила те оливкове пальто, її подарунковий пакет ... зараз набагато легшим. Очевидно.'::text,'був би'::text,'був би'::text,'буде'::text,'Якби вона не купила те оливкове пальто, її подарунковий пакет був би зараз набагато легшим. Очевидно.'::text),
(377565,41952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera comprado ese abrigo verde oliva, su bolsa de regalos ... mucho más ligera ahora. Obviamente.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si no hubiera comprado ese abrigo verde oliva, su bolsa de regalos estaría mucho más ligera ahora. Obviamente.'::text),
(377564,41952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas acheté ce manteau olive, son sac cadeau ... beaucoup plus léger maintenant. Évidemment.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si elle n''avait pas acheté ce manteau olive, son sac cadeau serait beaucoup plus léger maintenant. Évidemment.'::text),
(377567,41952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki: o zeytin yeşili montu almasaydı, hediye çantası şimdi çok daha hafif ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Tabii ki: o zeytin yeşili montu almasaydı, hediye çantası şimdi çok daha hafif olurdu.'::text),
(377568,41952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem vette volna meg azt az olajzöld kabátot, az ajándékszatyra most ... sokkal könnyebb. Nyilván.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha nem vette volna meg azt az olajzöld kabátot, az ajándékszatyra most lenne sokkal könnyebb. Nyilván.'::text),
(377571,41953,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der olivgrüne Mantel soll mit einem völlig vernünftigen Budget ..., offensichtlich.'::text,'gekauft worden sein'::text,'kaufen'::text,'kaufend'::text,'Der olivgrüne Mantel soll mit einem völlig vernünftigen Budget gekauft worden sein, offensichtlich.'::text),
(377575,41953,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що оливкове пальто ... з цілком розумним бюджетом, очевидно.'::text,'купили'::text,'купувати'::text,'купування'::text,'Вважається, що оливкове пальто купили з цілком розумним бюджетом, очевидно.'::text),
(377574,41953,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el abrigo verde oliva ... con un presupuesto totalmente sensato, obviamente.'::text,'fue comprado'::text,'comprar'::text,'comprando'::text,'Se cree que el abrigo verde oliva fue comprado con un presupuesto totalmente sensato, obviamente.'::text),
(377573,41953,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le manteau olive ... avec un budget tout à fait raisonnable, évidemment.'::text,'a été acheté'::text,'acheter'::text,'achetant'::text,'On pense que le manteau olive a été acheté avec un budget tout à fait raisonnable, évidemment.'::text),
(377576,41953,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zeytin yeşili montun tamamen makul bir bütçeyle ... düşünülüyor, tabii ki.'::text,'alındığı'::text,'almak'::text,'alarak'::text,'Zeytin yeşili montun tamamen makul bir bütçeyle alındığı düşünülüyor, tabii ki.'::text),
(377577,41953,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy az olajzöld kabátot egy teljesen észszerű keretből ..., nyilván.'::text,'vették'::text,'venni'::text,'véve'::text,'Úgy tartják, hogy az olajzöld kabátot egy teljesen észszerű keretből vették, nyilván.'::text),
(377580,41954,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gab zu, viel zu viel ..., und ihr Budget ist völlig zerstört!'::text,'gekauft zu haben'::text,'zu kaufen'::text,'kaufte'::text,'Sie gab zu, viel zu viel gekauft zu haben, und ihr Budget ist völlig zerstört!'::text),
(377584,41954,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона зізналася, що ... занадто багато, і її бюджет повністю знищено!'::text,'накупила'::text,'накупити'::text,'накупила'::text,'Вона зізналася, що накупила занадто багато, і її бюджет повністю знищено!'::text),
(377583,41954,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Admitió ... demasiado, y su presupuesto está completamente destrozado!'::text,'haber comprado'::text,'comprar'::text,'compró'::text,'¡Admitió haber comprado demasiado, y su presupuesto está completamente destrozado!'::text),
(377582,41954,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a avoué ... beaucoup trop, et son budget est complètement détruit !'::text,'avoir acheté'::text,'acheter'::text,'a acheté'::text,'Elle a avoué avoir acheté beaucoup trop, et son budget est complètement détruit !'::text),
(377585,41954,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok fazla ... itiraf etti ve bütçesi tamamen mahvoldu!'::text,'alışveriş yaptığını'::text,'alışveriş yapmayı'::text,'alışveriş yaptı'::text,'Çok fazla alışveriş yaptığını itiraf etti ve bütçesi tamamen mahvoldu!'::text),
(377586,41954,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevallotta, hogy túl sokat ..., és a kerete teljesen tönkrement!'::text,'vásárolt'::text,'vásárolni'::text,'vásárolt'::text,'Bevallotta, hogy túl sokat vásárolt, és a kerete teljesen tönkrement!'::text),
(377589,41955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Mantel nicht kaufen sollen; jetzt ist ihr ganzes Budget für immer ruiniert!'::text,'hätte'::text,'durfte'::text,'konnte'::text,'Sie hätte den Mantel nicht kaufen sollen; jetzt ist ihr ganzes Budget für immer ruiniert!'::text),
(377593,41955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй ... купувати те пальто; тепер увесь її бюджет зруйновано назавжди!'::text,'не слід було'::text,'не можна було'::text,'не вдалося'::text,'Їй не слід було купувати те пальто; тепер увесь її бюджет зруйновано назавжди!'::text),
(377592,41955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella no ... comprado ese abrigo; ahora todo su presupuesto está arruinado para siempre!'::text,'debería haber'::text,'debía haber'::text,'pudo'::text,'¡Ella no debería haber comprado ese abrigo; ahora todo su presupuesto está arruinado para siempre!'::text),
(377591,41955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... ce manteau ; maintenant tout son budget est ruiné pour toujours !'::text,'n''aurait pas dû acheter'::text,'n''a pas dû acheter'::text,'n''a pas pu acheter'::text,'Elle n''aurait pas dû acheter ce manteau ; maintenant tout son budget est ruiné pour toujours !'::text),
(377594,41955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O montu ...; şimdi bütün bütçesi sonsuza kadar mahvoldu!'::text,'almamalıydı'::text,'almamış olmalı'::text,'alamadı'::text,'O montu almamalıydı; şimdi bütün bütçesi sonsuza kadar mahvoldu!'::text),
(377595,41955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem ... volna megvennie azt a kabátot; most az egész kerete örökre tönkrement!'::text,'kellett'::text,'szabadott'::text,'tudta'::text,'Nem kellett volna megvennie azt a kabátot; most az egész kerete örökre tönkrement!'::text),
(377598,41956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht nur ... Schokolade, sondern sie kaufte auch einen Mantel.'::text,'kaufte sie'::text,'sie kaufte'::text,'kaufte sie'::text,'Nicht nur kaufte sie Schokolade, sondern sie kaufte auch einen Mantel.'::text),
(377602,41956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не лише ... шоколад, а й купила пальто.'::text,'купила'::text,'купила'::text,'купила'::text,'Вона не лише купила шоколад, а й купила пальто.'::text),
(377601,41956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No solo ... chocolate, sino que también se compró un abrigo.'::text,'compró ella'::text,'ella compró'::text,'compró ella'::text,'No solo compró ella chocolate, sino que también se compró un abrigo.'::text),
(377600,41956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement ... du chocolat, mais elle a aussi acheté un manteau.'::text,'a-t-elle acheté'::text,'elle a acheté'::text,'elle a acheté'::text,'Non seulement a-t-elle acheté du chocolat, mais elle a aussi acheté un manteau.'::text),
(377603,41956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sadece çikolata ..., bir mont da aldı.'::text,'almakla kalmadı'::text,'almakla kalmadı'::text,'almakla kalmadı'::text,'Sadece çikolata almakla kalmadı, bir mont da aldı.'::text),
(377604,41956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nemcsak csokoládét ..., hanem egy kabátot is vett.'::text,'vett'::text,'vett'::text,'vett'::text,'Nemcsak csokoládét vett, hanem egy kabátot is vett.'::text),
(377607,41957,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, sie hat das Geschenk nach dem Kauf in Goldband ... lassen.'::text,'einpacken'::text,'einpacken'::text,'einpackend'::text,'Hör mal, ich hab gehört, sie hat das Geschenk nach dem Kauf in Goldband einpacken lassen.'::text),
(377611,41957,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що після покупки вона попросила ... подарунок золотою стрічкою.'::text,'перев''язати'::text,'перев''язати'::text,'перев''язування'::text,'Слухай, я чула, що після покупки вона попросила перев''язати подарунок золотою стрічкою.'::text),
(377610,41957,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que, después de comprarlo, hizo que le ... el regalo con cinta dorada.'::text,'envolvieran'::text,'envolver'::text,'envolviendo'::text,'Oye, me han dicho que, después de comprarlo, hizo que le envolvieran el regalo con cinta dorada.'::text),
(377609,41957,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu qu''elle a fait ... le cadeau avec un ruban doré après l''avoir acheté.'::text,'emballer'::text,'emballer'::text,'emballant'::text,'Écoute, j''ai entendu qu''elle a fait emballer le cadeau avec un ruban doré après l''avoir acheté.'::text),
(377612,41957,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki satın aldıktan sonra hediyeyi altın kurdeleyle ...'::text,'sardırmış'::text,'sar'::text,'sararak'::text,'Dinle, duydum ki satın aldıktan sonra hediyeyi altın kurdeleyle sardırmış.'::text),
(377613,41957,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy miután megvette, aranyszalaggal ... az ajándékot.'::text,'becsomagoltatta'::text,'becsomagol'::text,'becsomagolva'::text,'Figyelj, azt hallottam, hogy miután megvette, aranyszalaggal becsomagoltatta az ajándékot.'::text),
(377616,41958,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ich wünschte, ich ... mir so einen Mantel kaufen, der ist lowkey ikonisch.'::text,'könnte'::text,'kann'::text,'würde'::text,'Bro, ich wünschte, ich könnte mir so einen Mantel kaufen, der ist lowkey ikonisch.'::text),
(377620,41958,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби ж я ... купити таке пальто, це трохи легендарно.'::text,'міг'::text,'можу'::text,'б'::text,'Бро, якби ж я міг купити таке пальто, це трохи легендарно.'::text),
(377619,41958,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ojalá ... comprarme un abrigo así, es medio icónico.'::text,'pudiera'::text,'puedo'::text,'querría'::text,'Bro, ojalá pudiera comprarme un abrigo así, es medio icónico.'::text),
(377618,41958,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si seulement je ... m''acheter un manteau comme ça, c''est un peu iconique.'::text,'pouvais'::text,'peux'::text,'voudrais'::text,'Frérot, si seulement je pouvais m''acheter un manteau comme ça, c''est un peu iconique.'::text),
(377621,41958,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke böyle bir mont ..., bayağı ikonik.'::text,'alabilsem'::text,'alabilirim'::text,'alsam'::text,'Kanka, keşke böyle bir mont alabilsem, bayağı ikonik.'::text),
(377622,41958,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, bárcsak ... venni egy ilyen kabátot, elég ikonikus.'::text,'tudnék'::text,'tudok'::text,'akarnék'::text,'Tesó, bárcsak tudnék venni egy ilyen kabátot, elég ikonikus.'::text),
(377625,41959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Laden, ... sie die Schokolade gekauft hat, war echt süß, ehrlich.'::text,'wo'::text,'welchen'::text,'wer'::text,'Yo, der Laden, wo sie die Schokolade gekauft hat, war echt süß, ehrlich.'::text),
(377629,41959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, магазин, ... вона купила той шоколад, був доволі милий, чесно.'::text,'де'::text,'який'::text,'хто'::text,'Йо, магазин, де вона купила той шоколад, був доволі милий, чесно.'::text),
(377628,41959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la tienda ... compró ese chocolate era bastante mona, en serio.'::text,'donde'::text,'que'::text,'quien'::text,'Oye, la tienda donde compró ese chocolate era bastante mona, en serio.'::text),
(377627,41959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la boutique ... elle a acheté ce chocolat était trop mignonne, sérieux.'::text,'où'::text,'que'::text,'qui'::text,'Yo, la boutique où elle a acheté ce chocolat était trop mignonne, sérieux.'::text),
(377630,41959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... o çikolatayı aldığı dükkân bayağı tatlıydı, cidden.'::text,''::text,NULL::text,NULL::text,'Yo, o çikolatayı aldığı dükkân bayağı tatlıydı, cidden.'::text),
(377631,41959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jó, a bolt, ... azt a csokit vette, elég cuki volt, komolyan.'::text,'ahol'::text,'amely'::text,'aki'::text,'Jó, a bolt, ahol azt a csokit vette, elég cuki volt, komolyan.'::text),
(360048,40006,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Drei sehr stille Wanderer, offensichtlich: Sie ... seit fünf Minuten über den Canyon.'::text,'jubeln'::text,'jubeln'::text,'jubeln'::text,'Drei sehr stille Wanderer, offensichtlich: Sie jubeln seit fünf Minuten über den Canyon.'::text),
(360052,40006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Троє дуже тихих туристів, очевидно: вони ... над каньйоном уже п''ять хвилин.'::text,'вигукують'::text,'вигукують'::text,'вигукують'::text,'Троє дуже тихих туристів, очевидно: вони вигукують над каньйоном уже п''ять хвилин.'::text),
(360051,40006,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tres excursionistas muy silenciosos, obviamente: ... sobre el cañón desde hace cinco minutos.'::text,'llevan gritando'::text,'están gritando'::text,'gritan'::text,'Tres excursionistas muy silenciosos, obviamente: llevan gritando sobre el cañón desde hace cinco minutos.'::text),
(360050,40006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trois randonneurs très silencieux, évidemment : ils ... au-dessus du canyon depuis cinq minutes.'::text,'crient'::text,'crient'::text,'crient'::text,'Trois randonneurs très silencieux, évidemment : ils crient au-dessus du canyon depuis cinq minutes.'::text),
(360053,40006,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç çok sessiz yürüyüşçü, tabii ki: beş dakikadır kanyonun üzerine ...'::text,'bağırıyorlar'::text,'bağırıyorlar'::text,'bağırırlar'::text,'Üç çok sessiz yürüyüşçü, tabii ki: beş dakikadır kanyonun üzerine bağırıyorlar.'::text),
(360054,40006,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Három nagyon csendes túrázó, nyilván: öt perce ... a kanyon felett.'::text,'üvöltöznek'::text,'üvöltöznek'::text,'üvöltöznek'::text,'Három nagyon csendes túrázó, nyilván: öt perce üvöltöznek a kanyon felett.'::text),
(360057,40007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein ruhiger Wanderer, ganz klar: Er brüllte den Canyon an, während sie auf ihn ...'::text,'zeigte'::text,'zeigte'::text,'hat gezeigt'::text,'Ein ruhiger Wanderer, ganz klar: Er brüllte den Canyon an, während sie auf ihn zeigte.'::text),
(360061,40007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спокійний турист, ясно: він ревів на каньйон, поки вона ... на нього.'::text,'показувала'::text,'показала'::text,'показала'::text,'Спокійний турист, ясно: він ревів на каньйон, поки вона показувала на нього.'::text),
(360060,40007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un excursionista tranquilo, claramente: le rugió al cañón mientras ella lo ...'::text,'estaba señalando'::text,'señaló'::text,'ha señalado'::text,'Un excursionista tranquilo, claramente: le rugió al cañón mientras ella lo estaba señalando.'::text),
(360059,40007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un randonneur calme, clairement : il a rugi vers le canyon pendant qu''elle le ...'::text,'montrait du doigt'::text,'a montré du doigt'::text,'a montré du doigt'::text,'Un randonneur calme, clairement : il a rugi vers le canyon pendant qu''elle le montrait du doigt.'::text),
(360062,40007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakin bir yürüyüşçü, belli ki: kadın onu ... kanyona kükredi.'::text,'işaret ederken'::text,'işaret etti'::text,'işaret etti'::text,'Sakin bir yürüyüşçü, belli ki: kadın onu işaret ederken kanyona kükredi.'::text),
(360063,40007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyugodt túrázó, egyértelműen: ráüvöltött a kanyonra, miközben a lány rá ...'::text,'mutatott'::text,'mutatott'::text,'rámutatott'::text,'Nyugodt túrázó, egyértelműen: ráüvöltött a kanyonra, miközben a lány rá mutatott.'::text),
(360066,40008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Wanderer ... seit so zehn Minuten den Canyon an, ohne Witz.'::text,'brüllen'::text,'haben gebrüllt'::text,'brüllen'::text,'Bro, die Wanderer brüllen seit so zehn Minuten den Canyon an, ohne Witz.'::text),
(360070,40008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ці туристи ... на каньйон уже хвилин десять, без жартів.'::text,'кричать'::text,'накричали'::text,'кричать'::text,'Бро, ці туристи кричать на каньйон уже хвилин десять, без жартів.'::text),
(360069,40008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, estos excursionistas ... como diez minutos gritándole al cañón, en serio.'::text,'llevan'::text,'han estado'::text,'gritan'::text,'Bro, estos excursionistas llevan como diez minutos gritándole al cañón, en serio.'::text),
(360068,40008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ces randonneurs ... sur le canyon depuis genre dix minutes, sans mentir.'::text,'crient'::text,'ont crié'::text,'crient'::text,'Frérot, ces randonneurs crient sur le canyon depuis genre dix minutes, sans mentir.'::text),
(360071,40008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu yürüyüşçüler on dakikadır falan kanyona ..., yemin ederim.'::text,'bağırıyor'::text,'bağırdı'::text,'bağırır'::text,'Kanka, bu yürüyüşçüler on dakikadır falan kanyona bağırıyor, yemin ederim.'::text),
(360072,40008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ezek a túrázók már vagy tíz perce ... a kanyonra, komolyan.'::text,'kiabálnak'::text,'kiabáltak'::text,'kiabálnak'::text,'Tesó, ezek a túrázók már vagy tíz perce kiabálnak a kanyonra, komolyan.'::text),
(360075,40009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, als sie das Geländer erreichten, ... die Wanderer schon so fünf Meilen gelaufen.'::text,'waren'::text,'sind'::text,'laufen'::text,'Nee Bro, als sie das Geländer erreichten, waren die Wanderer schon so fünf Meilen gelaufen.'::text),
(360079,40009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, поки вони дійшли до поручнів, туристи ... десь п''ять миль.'::text,'вже пройшли'::text,'пройшли'::text,'йдуть'::text,'Не, бро, поки вони дійшли до поручнів, туристи вже пройшли десь п''ять миль.'::text),
(360078,40009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, bro, cuando llegaron a la barandilla, los excursionistas ... como cinco millas.'::text,'habían caminado'::text,'han caminado'::text,'caminan'::text,'Nah, bro, cuando llegaron a la barandilla, los excursionistas habían caminado como cinco millas.'::text),
(360077,40009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, quand ils ont atteint la rambarde, les randonneurs ... genre cinq miles.'::text,'avaient marché'::text,'ont marché'::text,'marchent'::text,'Nan frérot, quand ils ont atteint la rambarde, les randonneurs avaient marché genre cinq miles.'::text),
(360080,40009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, korkuluğa vardıklarında yürüyüşçüler beş mil falan ...'::text,'yürümüştü'::text,'yürüdü'::text,'yürüyor'::text,'Yok kanka, korkuluğa vardıklarında yürüyüşçüler beş mil falan yürümüştü.'::text),
(360081,40009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, mire a korláthoz értek, a túrázók már vagy öt mérföldet ...'::text,'gyalogoltak'::text,'gyalogoltak'::text,'gyalogolnak'::text,'Á, tesó, mire a korláthoz értek, a túrázók már vagy öt mérföldet gyalogoltak.'::text),
(360084,40010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wanderer erreichten ... um 9 Uhr, genau im Zeitplan.'::text,'den Grand Canyon'::text,'Grand Canyon'::text,'einen Grand Canyon'::text,'Die Wanderer erreichten den Grand Canyon um 9 Uhr, genau im Zeitplan.'::text),
(360088,40010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туристи дісталися до ... о 9:00, точно за планом.'::text,'Гранд-Каньйону'::text,'Гранд-Каньйону'::text,'Гранд-Каньйону'::text,'Туристи дісталися до Гранд-Каньйону о 9:00, точно за планом.'::text),
(360087,40010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los excursionistas alcanzaron ... a las 9 a. m., justo según lo previsto.'::text,'el Gran Cañón'::text,'Gran Cañón'::text,'un Gran Cañón'::text,'Los excursionistas alcanzaron el Gran Cañón a las 9 a. m., justo según lo previsto.'::text),
(360086,40010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les randonneurs ont atteint ... à 9 h, pile dans les objectifs.'::text,'le Grand Canyon'::text,'Grand Canyon'::text,'un Grand Canyon'::text,'Les randonneurs ont atteint le Grand Canyon à 9 h, pile dans les objectifs.'::text),
(360089,40010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşçüler sabah 9''da ... vardı, tam hedeflendiği gibi.'::text,'Grand Canyon''a'::text,'Grand Canyon''a'::text,'bir Grand Canyon''a'::text,'Yürüyüşçüler sabah 9''da Grand Canyon''a vardı, tam hedeflendiği gibi.'::text),
(360090,40010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A túrázók reggel 9-kor ... értek, pont a terv szerint.'::text,'a Grand Canyonhoz'::text,'Grand Canyonhoz'::text,'egy Grand Canyonhoz'::text,'A túrázók reggel 9-kor a Grand Canyonhoz értek, pont a terv szerint.'::text),
(360093,40011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der langen Wanderung hatten die Wanderer noch Energie, über den Canyon zu rufen.'::text,'Trotz'::text,'Aufgrund'::text,'Vorausgesetzt'::text,'Trotz der langen Wanderung hatten die Wanderer noch Energie, über den Canyon zu rufen.'::text),
(360097,40011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... довгу прогулянку, туристи ще мали сили кричати над каньйоном.'::text,'Попри'::text,'Завдяки'::text,'За умови'::text,'Попри довгу прогулянку, туристи ще мали сили кричати над каньйоном.'::text),
(360096,40011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la larga caminata, los excursionistas aún tenían energía para gritar sobre el cañón.'::text,'A pesar de'::text,'Debido a'::text,'Siempre que'::text,'A pesar de la larga caminata, los excursionistas aún tenían energía para gritar sobre el cañón.'::text),
(360095,40011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la longue marche, les randonneurs avaient encore l''énergie de crier au-dessus du canyon.'::text,'Malgré'::text,'En raison de'::text,'Pourvu que'::text,'Malgré la longue marche, les randonneurs avaient encore l''énergie de crier au-dessus du canyon.'::text),
(360098,40011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun yürüyüşe ..., yürüyüşçülerin kanyona bağıracak enerjisi hâlâ vardı.'::text,'rağmen'::text,'nedeniyle'::text,'şartıyla'::text,'Uzun yürüyüşe rağmen, yürüyüşçülerin kanyona bağıracak enerjisi hâlâ vardı.'::text),
(360099,40011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hosszú séta ..., a túrázóknak még volt energiájuk kiabálni a kanyon felett.'::text,'ellenére'::text,'miatt'::text,'feltéve'::text,'A hosszú séta ellenére, a túrázóknak még volt energiájuk kiabálni a kanyon felett.'::text),
(360102,40012,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wanderer wussten, dass der Canyon ihre Stimmen als Echo zurückschicken ..., ein dokumentiertes Phänomen.'::text,'würde'::text,'wird'::text,'schickt'::text,'Die Wanderer wussten, dass der Canyon ihre Stimmen als Echo zurückschicken würde, ein dokumentiertes Phänomen.'::text),
(360106,40012,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туристи знали, що каньйон ... їхні голоси назад луною, задокументоване явище.'::text,'поверне'::text,'поверне'::text,'повертає'::text,'Туристи знали, що каньйон поверне їхні голоси назад луною, задокументоване явище.'::text),
(360105,40012,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los excursionistas sabían que el cañón les ... sus voces como eco, un fenómeno documentado.'::text,'devolvería'::text,'devolverá'::text,'devuelve'::text,'Los excursionistas sabían que el cañón les devolvería sus voces como eco, un fenómeno documentado.'::text),
(360104,40012,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les randonneurs savaient que le canyon leur ... leurs voix en écho, un phénomène documenté.'::text,'renverrait'::text,'renverra'::text,'renvoie'::text,'Les randonneurs savaient que le canyon leur renverrait leurs voix en écho, un phénomène documenté.'::text),
(360107,40012,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşçüler kanyonun seslerini yankı olarak geri ... biliyordu, belgelenmiş bir olgu.'::text,'göndereceğini'::text,'göndereceğini'::text,'gönderdiğini'::text,'Yürüyüşçüler kanyonun seslerini yankı olarak geri göndereceğini biliyordu, belgelenmiş bir olgu.'::text),
(360108,40012,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A túrázók tudták, hogy a kanyon visszhangként ... a hangjukat, ez egy dokumentált jelenség.'::text,'visszaküldi majd'::text,'vissza fogja küldeni'::text,'visszaküldi'::text,'A túrázók tudták, hogy a kanyon visszhangként visszaküldi majd a hangjukat, ez egy dokumentált jelenség.'::text),
(360120,40014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wanderer ... stundenlang gelaufen, bevor sie am Geländer des Canyons anhielten.'::text,'waren'::text,'sind'::text,'laufen'::text,'Die Wanderer waren stundenlang gelaufen, bevor sie am Geländer des Canyons anhielten.'::text),
(360124,40014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туристи ... годинами, перш ніж зупинилися біля поручнів каньйону.'::text,'йшли'::text,'йдуть'::text,'йдуть'::text,'Туристи йшли годинами, перш ніж зупинилися біля поручнів каньйону.'::text),
(360123,40014,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los excursionistas ... durante horas antes de detenerse en la barandilla del cañón.'::text,'habían estado caminando'::text,'han estado caminando'::text,'están caminando'::text,'Los excursionistas habían estado caminando durante horas antes de detenerse en la barandilla del cañón.'::text),
(360122,40014,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les randonneurs ... depuis des heures quand ils se sont arrêtés à la rambarde du canyon.'::text,'marchaient'::text,'marchent'::text,'marchent'::text,'Les randonneurs marchaient depuis des heures quand ils se sont arrêtés à la rambarde du canyon.'::text),
(360125,40014,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşçüler kanyon korkuluğunda durmadan önce saatlerdir ...'::text,'yürüyordu'::text,'yürüyor'::text,'yürüyor'::text,'Yürüyüşçüler kanyon korkuluğunda durmadan önce saatlerdir yürüyordu.'::text),
(360126,40014,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A túrázók órák óta ..., mielőtt megálltak a kanyon korlátjánál.'::text,'gyalogoltak'::text,'gyalogolnak'::text,'gyalogolnak'::text,'A túrázók órák óta gyalogoltak, mielőtt megálltak a kanyon korlátjánál.'::text),
(360129,40015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... die drei Wanderer zu ihrem Lager zurückgelaufen sein.'::text,'werden'::text,'werden'::text,'laufen'::text,'Bis Sonnenuntergang werden die drei Wanderer zu ihrem Lager zurückgelaufen sein.'::text),
(360133,40015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця троє туристів ... назад до свого табору.'::text,'дійдуть'::text,'підуть'::text,'ідуть'::text,'До заходу сонця троє туристів дійдуть назад до свого табору.'::text),
(360132,40015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, los tres excursionistas ... a su campamento.'::text,'habrán vuelto'::text,'volverán'::text,'vuelven'::text,'Para el atardecer, los tres excursionistas habrán vuelto a su campamento.'::text),
(360131,40015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, les trois randonneurs ... à leur camp.'::text,'seront rentrés'::text,'rentreront'::text,'rentrent'::text,'D''ici le coucher du soleil, les trois randonneurs seront rentrés à leur camp.'::text),
(360134,40015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar üç yürüyüşçü kamplarına geri ...'::text,'dönmüş olacak'::text,'dönecek'::text,'döner'::text,'Gün batımına kadar üç yürüyüşçü kamplarına geri dönmüş olacak.'::text),
(360135,40015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára a három túrázó ... a táborukba.'::text,'visszaér'::text,'vissza fog menni'::text,'visszamegy'::text,'Napnyugtára a három túrázó visszaér a táborukba.'::text),
(369462,41052,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Model noch einmal auf die Uhr schaut, ... die Show Verspätung haben, offensichtlich.'::text,'wird'::text,'würde'::text,'hatte'::text,'Wenn das Model noch einmal auf die Uhr schaut, wird die Show Verspätung haben, offensichtlich.'::text),
(369466,41052,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо модель ще раз гляне на годинник, показ ..., очевидно.'::text,'запізниться'::text,'запізнився б'::text,'запізнився'::text,'Якщо модель ще раз гляне на годинник, показ запізниться, очевидно.'::text),
(369465,41052,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el modelo mira el reloj una vez más, el desfile ... con retraso, obviamente.'::text,'irá'::text,'iría'::text,'fue'::text,'Si el modelo mira el reloj una vez más, el desfile irá con retraso, obviamente.'::text),
(369464,41052,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le mannequin regarde encore sa montre, le défilé ... du retard, évidemment.'::text,'aura'::text,'aurait'::text,'a eu'::text,'Si le mannequin regarde encore sa montre, le défilé aura du retard, évidemment.'::text),
(369467,41052,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Model saatine bir kez daha bakarsa, defile ..., tabii ki.'::text,'gecikecek'::text,'gecikirdi'::text,'gecikti'::text,'Model saatine bir kez daha bakarsa, defile gecikecek, tabii ki.'::text),
(369468,41052,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a modell még egyszer ránéz az órájára, a show ..., nyilván.'::text,'csúszni fog'::text,'csúszna'::text,'csúszott'::text,'Ha a modell még egyszer ránéz az órájára, a show csúszni fog, nyilván.'::text),
(369480,41054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die gelbe Jeansjacke ... vom Model zu Beginn der Show getragen.'::text,'wurde'::text,'trug'::text,'trägt'::text,'Die gelbe Jeansjacke wurde vom Model zu Beginn der Show getragen.'::text),
(369484,41054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жовта джинсова куртка ... моделлю на початку показу.'::text,'була вдягнена'::text,'вдягнув'::text,'вдягає'::text,'Жовта джинсова куртка була вдягнена моделлю на початку показу.'::text),
(369483,41054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La chaqueta vaquera amarilla ... por el modelo al inicio del desfile.'::text,'fue llevada'::text,'llevó'::text,'lleva'::text,'La chaqueta vaquera amarilla fue llevada por el modelo al inicio del desfile.'::text),
(369482,41054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La veste en jean jaune ... par le mannequin au début du défilé.'::text,'a été portée'::text,'a porté'::text,'porte'::text,'La veste en jean jaune a été portée par le mannequin au début du défilé.'::text),
(369485,41054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarı kot ceket, defilenin başında model tarafından ...'::text,'giyildi'::text,'giydi'::text,'giyiyor'::text,'Sarı kot ceket, defilenin başında model tarafından giyildi.'::text),
(369486,41054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sárga farmerdzsekit a show elején a modell ...'::text,'viselte'::text,'viselte'::text,'viseli'::text,'A sárga farmerdzsekit a show elején a modell viselte.'::text),
(369489,41055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Model ... den Laufsteg in 45 Sekunden ab, deutlich innerhalb des Show-Zeitplans.'::text,'lief'::text,'wurde gelaufen'::text,'laufend'::text,'Das Model lief den Laufsteg in 45 Sekunden ab, deutlich innerhalb des Show-Zeitplans.'::text),
(369493,41055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Модель ... подіум за 45 секунд, цілком у межах таймінгу показу.'::text,'пройшов'::text,'був пройдений'::text,'проходячи'::text,'Модель пройшов подіум за 45 секунд, цілком у межах таймінгу показу.'::text),
(369492,41055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El modelo ... la pasarela en 45 segundos, holgadamente dentro del horario del desfile.'::text,'recorrió'::text,'fue recorrido'::text,'recorriendo'::text,'El modelo recorrió la pasarela en 45 segundos, holgadamente dentro del horario del desfile.'::text),
(369491,41055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mannequin ... le podium en 45 secondes, largement dans le planning du défilé.'::text,'a parcouru'::text,'a été parcouru'::text,'parcourant'::text,'Le mannequin a parcouru le podium en 45 secondes, largement dans le planning du défilé.'::text),
(369494,41055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Model podyumu 45 saniyede ..., defile takviminin rahatça içinde.'::text,'yürüdü'::text,'yürütüldü'::text,'yürüyerek'::text,'Model podyumu 45 saniyede yürüdü, defile takviminin rahatça içinde.'::text),
(369495,41055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modell 45 másodperc alatt ... a kifutót, bőven a show ütemtervén belül.'::text,'végigment'::text,'végig lett menve'::text,'végigmenve'::text,'A modell 45 másodperc alatt végigment a kifutót, bőven a show ütemtervén belül.'::text),
(369498,41056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Model schaut ständig auf die Uhr, also ... er es eilig haben.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Das Model schaut ständig auf die Uhr, also muss er es eilig haben.'::text),
(369502,41056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Модель постійно дивиться на годинник, тож він ... поспішати.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Модель постійно дивиться на годинник, тож він мусить поспішати.'::text),
(369501,41056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El modelo no para de mirar el reloj, así que ... tener prisa.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'El modelo no para de mirar el reloj, así que debe de tener prisa.'::text),
(369500,41056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mannequin n''arrête pas de regarder sa montre, donc il ... être pressé.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Le mannequin n''arrête pas de regarder sa montre, donc il doit être pressé.'::text),
(369503,41056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Model sürekli saatine bakıyor, yani acelesi ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Model sürekli saatine bakıyor, yani acelesi olmalı.'::text),
(369504,41056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modell folyton az óráját nézi, tehát ... siet.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem szabad'::text,'A modell folyton az óráját nézi, tehát biztosan siet.'::text),
(369507,41057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Model, ... eine gelbe Jeansjacke trägt, wird dabei beobachtet, wie es sich am Ende des Laufstegs umdreht.'::text,'das'::text,'welches'::text,'dessen'::text,'Das Model, das eine gelbe Jeansjacke trägt, wird dabei beobachtet, wie es sich am Ende des Laufstegs umdreht.'::text),
(369511,41057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Модель, ... носить жовту джинсову куртку, спостерігається під час розвороту в кінці подіуму.'::text,'який'::text,'котрий'::text,'чий'::text,'Модель, який носить жовту джинсову куртку, спостерігається під час розвороту в кінці подіуму.'::text),
(369510,41057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El modelo, ... lleva una chaqueta vaquera amarilla, es observado girando al final de la pasarela.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El modelo, que lleva una chaqueta vaquera amarilla, es observado girando al final de la pasarela.'::text),
(369509,41057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mannequin, ... porte une veste en jean jaune, est observé en train de se retourner au bout du podium.'::text,'qui'::text,'lequel'::text,'dont'::text,'Le mannequin, qui porte une veste en jean jaune, est observé en train de se retourner au bout du podium.'::text),
(369512,41057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Sarı kot ceket giyen model, podyumun sonunda dönerken gözlemleniyor.'::text,''::text,NULL::text,NULL::text,'Sarı kot ceket giyen model, podyumun sonunda dönerken gözlemleniyor.'::text),
(369513,41057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modell, ... sárga farmerdzsekit visel, megfigyelhetően megfordul a kifutó végén.'::text,'aki'::text,'amely'::text,'akinek'::text,'A modell, aki sárga farmerdzsekit visel, megfigyelhetően megfordul a kifutó végén.'::text),
(369516,41058,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Model sagte, dieser Laufsteg ... der schrecklichste Gang seines ganzen Lebens gewesen!'::text,'sei'::text,'ist'::text,'ist'::text,'Das Model sagte, dieser Laufsteg sei der schrecklichste Gang seines ganzen Lebens gewesen!'::text),
(369520,41058,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Модель сказав, що той подіум ... найстрашнішою прогулянкою в його житті!'::text,'був'::text,'був'::text,'є'::text,'Модель сказав, що той подіум був найстрашнішою прогулянкою в його житті!'::text),
(369519,41058,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El modelo dijo que esa pasarela ... el paseo más aterrador de toda su vida!'::text,'había sido'::text,'ha sido'::text,'es'::text,'¡El modelo dijo que esa pasarela había sido el paseo más aterrador de toda su vida!'::text),
(369518,41058,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mannequin a dit que ce défilé ... la marche la plus terrifiante de toute sa vie !'::text,'avait été'::text,'a été'::text,'est'::text,'Le mannequin a dit que ce défilé avait été la marche la plus terrifiante de toute sa vie !'::text),
(369521,41058,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Model o podyumun hayatının en korkunç yürüyüşü ... söyledi!'::text,'olduğunu'::text,'olduğunu'::text,'olduğunu'::text,'Model o podyumun hayatının en korkunç yürüyüşü olduğunu söyledi!'::text),
(369522,41058,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modell azt mondta, az a kifutó ... egész élete legfélelmetesebb sétája!'::text,'volt'::text,'volt'::text,NULL::text,'A modell azt mondta, az a kifutó volt egész élete legfélelmetesebb sétája!'::text),
(369525,41059,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Model ... knallige Farben, aber heute trägt es Gelb und Lila.'::text,'hasste früher'::text,'hasste'::text,'ist gewohnt zu hassen'::text,'Das Model hasste früher knallige Farben, aber heute trägt es Gelb und Lila.'::text),
(369529,41059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Модель ... яскраві кольори, але сьогодні він носить жовте й фіолетове.'::text,'колись ненавидів'::text,'ненавидів'::text,'звик ненавидіти'::text,'Модель колись ненавидів яскраві кольори, але сьогодні він носить жовте й фіолетове.'::text),
(369528,41059,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El modelo ... odiar los colores vivos, pero hoy lleva amarillo y morado.'::text,'solía'::text,'solía'::text,'está acostumbrado a'::text,'El modelo solía odiar los colores vivos, pero hoy lleva amarillo y morado.'::text),
(369527,41059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mannequin ... les couleurs vives, mais aujourd''hui il porte du jaune et du violet.'::text,'détestait avant'::text,'détestait'::text,'est habitué à détester'::text,'Le mannequin détestait avant les couleurs vives, mais aujourd''hui il porte du jaune et du violet.'::text),
(369530,41059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Model eskiden parlak renklerden ..., ama bugün sarı ve mor giyiyor.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkın'::text,'Model eskiden parlak renklerden nefret ederdi, ama bugün sarı ve mor giyiyor.'::text),
(369531,41059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modell ... az élénk színeket, de ma sárgát és lilát visel.'::text,'régen utálta'::text,'utálta'::text,'hozzá van szokva, hogy utálja'::text,'A modell régen utálta az élénk színeket, de ma sárgát és lilát visel.'::text),
(369534,41060,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Model genießt das ... für die Gäste am Ende des Laufstegs.'::text,'Posieren'::text,'zu posieren'::text,'posiert'::text,'Das Model genießt das Posieren für die Gäste am Ende des Laufstegs.'::text),
(369538,41060,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Моделі подобається ... для гостей у кінці подіуму.'::text,'позувати'::text,'позувати'::text,'позує'::text,'Моделі подобається позувати для гостей у кінці подіуму.'::text),
(369537,41060,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al modelo le encanta ... para los invitados al final de la pasarela.'::text,'posar'::text,'posar'::text,'posa'::text,'Al modelo le encanta posar para los invitados al final de la pasarela.'::text),
(369536,41060,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mannequin aime ... pour les invités au bout du podium.'::text,'poser'::text,'poser'::text,'pose'::text,'Le mannequin aime poser pour les invités au bout du podium.'::text),
(369539,41060,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Model, podyumun sonunda konuklar için ... seviyor.'::text,'poz vermeyi'::text,'poz vermek'::text,'poz ver'::text,'Model, podyumun sonunda konuklar için poz vermeyi seviyor.'::text),
(369540,41060,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A modell élvezi, hogy ... a vendégeknek a kifutó végén.'::text,'pózolhat'::text,'pózolni'::text,'pózol'::text,'A modell élvezi, hogy pózolhat a vendégeknek a kifutó végén.'::text),
(369543,41061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Moment ... das Model am Ende des Laufstegs seine Sonnenbrille auf.'::text,'setzt'::text,'setzt'::text,'hat aufgesetzt'::text,'In diesem Moment setzt das Model am Ende des Laufstegs seine Sonnenbrille auf.'::text),
(369547,41061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цієї миті модель ... сонцезахисні окуляри в кінці подіуму.'::text,'надягає'::text,'надягає'::text,'надяг'::text,'Цієї миті модель надягає сонцезахисні окуляри в кінці подіуму.'::text),
(369546,41061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, el modelo ... las gafas de sol al final de la pasarela.'::text,'se está poniendo'::text,'se pone'::text,'se ha puesto'::text,'En este momento, el modelo se está poniendo las gafas de sol al final de la pasarela.'::text),
(369545,41061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le mannequin ... ses lunettes de soleil au bout du podium.'::text,'met'::text,'met'::text,'a mis'::text,'En ce moment, le mannequin met ses lunettes de soleil au bout du podium.'::text),
(369548,41061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda model podyumun sonunda güneş gözlüklerini ...'::text,'takıyor'::text,'takar'::text,'taktı'::text,'Şu anda model podyumun sonunda güneş gözlüklerini takıyor.'::text),
(369549,41061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a pillanatban a modell ... a napszemüvegét a kifutó végén.'::text,'veszi fel'::text,'felveszi'::text,'felvette'::text,'Ebben a pillanatban a modell veszi fel a napszemüvegét a kifutó végén.'::text),
(388992,43222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, morgen um 7 ... er wieder klatschnass in dieser Dusche stehen, ohne Witz.'::text,'wird'::text,'wird'::text,'steht'::text,'Bro, morgen um 7 wird er wieder klatschnass in dieser Dusche stehen, ohne Witz.'::text),
(388996,43222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, завтра о 7 він знову ... мокрий до нитки в тому душі, без жартів.'::text,'стоятиме'::text,'стане'::text,'стоїть'::text,'Бро, завтра о 7 він знову стоятиме мокрий до нитки в тому душі, без жартів.'::text),
(388995,43222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, mañana a las 7 ... otra vez empapado en esa ducha, en serio.'::text,'va a estar'::text,'estará'::text,'está'::text,'Bro, mañana a las 7 va a estar otra vez empapado en esa ducha, en serio.'::text),
(388994,43222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, demain à 7 h, il ... encore trempé sous cette douche, sans mentir.'::text,'sera'::text,'se tiendra'::text,'est'::text,'Frérot, demain à 7 h, il sera encore trempé sous cette douche, sans mentir.'::text),
(388997,43222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın saat 7''de yine o duşta sırılsıklam ..., yemin ederim.'::text,'duruyor olacak'::text,'duracak'::text,'duruyor'::text,'Kanka, yarın saat 7''de yine o duşta sırılsıklam duruyor olacak, yemin ederim.'::text),
(388998,43222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap 7-kor megint bőrig ázva ... abban a zuhanyban, komolyan.'::text,'fog állni'::text,'áll majd'::text,'áll'::text,'Tesó, holnap 7-kor megint bőrig ázva fog állni abban a zuhanyban, komolyan.'::text),
(389001,43223,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich verspreche, dass ich pünktlich am Meeting um 8 Uhr ..., nass oder nicht.'::text,'teilnehmen werde'::text,'teilnehmen werde'::text,'teilnehme'::text,'Ich verspreche, dass ich pünktlich am Meeting um 8 Uhr teilnehmen werde, nass oder nicht.'::text),
(389005,43223,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обіцяю, що вчасно ... на зустріч о 8:00, мокрий чи ні.'::text,'прийду'::text,'приходитиму'::text,'приходжу'::text,'Обіцяю, що вчасно прийду на зустріч о 8:00, мокрий чи ні.'::text),
(389004,43223,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prometo que ... a la reunión de las 8 a tiempo, empapado o no.'::text,'asistiré'::text,'estaré asistiendo'::text,'asisto'::text,'Prometo que asistiré a la reunión de las 8 a tiempo, empapado o no.'::text),
(389003,43223,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je promets que j''... à la réunion de 8 h à l''heure, trempé ou pas.'::text,'assisterai'::text,'serai en train d''assister'::text,'assiste'::text,'Je promets que j''assisterai à la réunion de 8 h à l''heure, trempé ou pas.'::text),
(389006,43223,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söz veriyorum, sabah 8 toplantısına zamanında ..., ıslak olsam da olmasam da.'::text,'katılacağım'::text,'katılıyor olacağım'::text,'katılıyorum'::text,'Söz veriyorum, sabah 8 toplantısına zamanında katılacağım, ıslak olsam da olmasam da.'::text),
(389007,43223,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérem, hogy időben ... a 8 órás megbeszélésen, akár eláztam, akár nem.'::text,'részt veszek'::text,'részt fogok venni'::text,'részt veszek'::text,'Megígérem, hogy időben részt veszek a 8 órás megbeszélésen, akár eláztam, akár nem.'::text),
(389010,43224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du unter einer laufenden Dusche ..., wirst du klatschnass, weil das Wasser nass ist.'::text,'stehst'::text,'standest'::text,'stehen wirst'::text,'Wenn du unter einer laufenden Dusche stehst, wirst du klatschnass, weil das Wasser nass ist.'::text),
(389014,43224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти ... під увімкненим душем, ти промокаєш, бо вода мокра.'::text,'стоїш'::text,'стояв'::text,'стоятимеш'::text,'Якщо ти стоїш під увімкненим душем, ти промокаєш, бо вода мокра.'::text),
(389013,43224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... bajo una ducha abierta, te empapas porque el agua está mojada.'::text,'estás'::text,'estuviste'::text,'estarás'::text,'Si estás bajo una ducha abierta, te empapas porque el agua está mojada.'::text),
(389012,43224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ... sous une douche qui coule, tu es trempé parce que l''eau est mouillée.'::text,'restes'::text,'es resté'::text,'resteras'::text,'Si tu restes sous une douche qui coule, tu es trempé parce que l''eau est mouillée.'::text),
(389015,43224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açık bir duşun altında ..., ıslanırsın çünkü su ıslaktır.'::text,'durursan'::text,'durduysan'::text,'duracaksan'::text,'Açık bir duşun altında durursan, ıslanırsın çünkü su ıslaktır.'::text),
(389016,43224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy folyó zuhany alatt ..., bőrig ázol, mert a víz vizes.'::text,'állsz'::text,'álltál'::text,'fogsz állni'::text,'Ha egy folyó zuhany alatt állsz, bőrig ázol, mert a víz vizes.'::text),
(389028,43226,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du warst nicht bereit, klatschnass zu werden, und ganz ehrlich, ...'::text,'das Handtuch auch nicht.'::text,'das Handtuch auch nicht.'::text,'das Handtuch auch.'::text,'Du warst nicht bereit, klatschnass zu werden, und ganz ehrlich, das Handtuch auch nicht.'::text),
(389032,43226,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти не був готовий промокнути, і чесно, ...'::text,'рушник теж ні.'::text,'рушник теж ні.'::text,'рушник теж.'::text,'Ти не був готовий промокнути, і чесно, рушник теж ні.'::text),
(389031,43226,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No estabas listo para empaparte y, no te voy a mentir, ...'::text,'la toalla tampoco.'::text,'la toalla tampoco.'::text,'la toalla también.'::text,'No estabas listo para empaparte y, no te voy a mentir, la toalla tampoco.'::text),
(389030,43226,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu n''étais pas prêt à te faire tremper, et franchement, ...'::text,'la serviette non plus.'::text,'la serviette non plus.'::text,'la serviette aussi.'::text,'Tu n''étais pas prêt à te faire tremper, et franchement, la serviette non plus.'::text),
(389033,43226,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırılsıklam olmaya hazır değildin ve yalan yok, ...'::text,'havlu da değildi.'::text,'havlu da değildi.'::text,'havlu da hazırdı.'::text,'Sırılsıklam olmaya hazır değildin ve yalan yok, havlu da değildi.'::text),
(389034,43226,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem voltál felkészülve, hogy bőrig ázz, és őszintén, ...'::text,'a törölköző sem.'::text,'a törölköző sem.'::text,'a törölköző is.'::text,'Nem voltál felkészülve, hogy bőrig ázz, és őszintén, a törölköző sem.'::text),
(389037,43227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis du mit dem Shampoo fertig bist, ... du schon zehn Minuten lang klatschnass gewesen sein, Respekt.'::text,'wirst'::text,'wirst'::text,'bist'::text,'Bis du mit dem Shampoo fertig bist, wirst du schon zehn Minuten lang klatschnass gewesen sein, Respekt.'::text),
(389041,43227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти доробиш із шампунем, ти ... мокрий уже десять хвилин, респект.'::text,'будеш'::text,'будеш'::text,'є'::text,'Поки ти доробиш із шампунем, ти будеш мокрий уже десять хвилин, респект.'::text),
(389040,43227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando termines con ese champú, ... empapado diez minutos, respeto.'::text,'llevarás'::text,'estarás'::text,'estás'::text,'Para cuando termines con ese champú, llevarás empapado diez minutos, respeto.'::text),
(389039,43227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que tu finisses ce shampooing, tu ... trempé depuis dix minutes, respect.'::text,'seras'::text,'seras'::text,'es'::text,'Le temps que tu finisses ce shampooing, tu seras trempé depuis dix minutes, respect.'::text),
(389042,43227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şampuanı bitirdiğinde on dakikadır sırılsıklam ..., helal.'::text,'olmuş olacaksın'::text,'olacaksın'::text,NULL::text,'O şampuanı bitirdiğinde on dakikadır sırılsıklam olmuş olacaksın, helal.'::text),
(389043,43227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire végzel azzal a samponnal, már tíz perce bőrig ázva ..., respekt.'::text,'leszel'::text,'leszel'::text,'vagy'::text,'Mire végzel azzal a samponnal, már tíz perce bőrig ázva leszel, respekt.'::text),
(389046,43228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er das Wasser nicht zuerst getestet hätte, ... er in kaltem Wasser klatschnass geworden.'::text,'wäre'::text,'wird'::text,'wurde'::text,'Wenn er das Wasser nicht zuerst getestet hätte, wäre er in kaltem Wasser klatschnass geworden.'::text),
(389050,43228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він спершу не перевірив воду, він ... в холодній воді.'::text,'промок би'::text,'промокне'::text,'промок'::text,'Якби він спершу не перевірив воду, він промок би в холодній воді.'::text),
(389049,43228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera probado el agua primero, ... empapado de agua fría.'::text,'habría acabado'::text,'acabará'::text,'acabó'::text,'Si no hubiera probado el agua primero, habría acabado empapado de agua fría.'::text),
(389048,43228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas testé l''eau d''abord, il ... trempé d''eau froide.'::text,'aurait été'::text,'sera'::text,'a été'::text,'S''il n''avait pas testé l''eau d''abord, il aurait été trempé d''eau froide.'::text),
(389051,43228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önce suyu denemeseydi, soğuk suyla sırılsıklam ...'::text,'olurdu'::text,'olacak'::text,'oldu'::text,'Önce suyu denemeseydi, soğuk suyla sırılsıklam olurdu.'::text),
(389052,43228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem próbálta volna ki előbb a vizet, bőrig ... a hideg vízben.'::text,'ázott volna'::text,'ázik majd'::text,'ázott'::text,'Ha nem próbálta volna ki előbb a vizet, bőrig ázott volna a hideg vízben.'::text),
(389055,43229,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er bestritt, aus Versehen klatschnass ...; er hatte das Wasser vorher getestet.'::text,'geworden zu sein'::text,'zu werden'::text,'wurde'::text,'Er bestritt, aus Versehen klatschnass geworden zu sein; er hatte das Wasser vorher getestet.'::text),
(389059,43229,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він заперечив, що ... випадково; він спершу перевірив воду.'::text,'промок'::text,'промокнути'::text,'промок'::text,'Він заперечив, що промок випадково; він спершу перевірив воду.'::text),
(389058,43229,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... empapado por accidente; había probado el agua antes.'::text,'haber acabado'::text,'acabar'::text,'acabó'::text,'Negó haber acabado empapado por accidente; había probado el agua antes.'::text),
(389057,43229,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a nié ... trempé par accident ; il avait testé l''eau avant.'::text,'avoir été'::text,'être'::text,'a été'::text,'Il a nié avoir été trempé par accident ; il avait testé l''eau avant.'::text),
(389060,43229,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kazara sırılsıklam ... inkâr etti; önce suyu denemişti.'::text,'olduğunu'::text,'olmayı'::text,'oldu'::text,'Kazara sırılsıklam olduğunu inkâr etti; önce suyu denemişti.'::text),
(389061,43229,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy véletlenül ... el; előbb kipróbálta a vizet.'::text,'ázott'::text,'elázni'::text,'ázott'::text,'Tagadta, hogy véletlenül ázott el; előbb kipróbálta a vizet.'::text),
(389064,43230,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Unterhemd hängt trocken auf der Stange, also ... er es ausgezogen haben, bevor er klatschnass wurde.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Sein Unterhemd hängt trocken auf der Stange, also muss er es ausgezogen haben, bevor er klatschnass wurde.'::text),
(389068,43230,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його майка суха на поручні, тож він ... зняв її, перш ніж промок.'::text,'мабуть'::text,'мав би'::text,'не міг'::text,'Його майка суха на поручні, тож він мабуть зняв її, перш ніж промок.'::text),
(389067,43230,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su camiseta de tirantes está seca en la barra, así que ... quitado antes de empaparse.'::text,'se la debe de haber'::text,'se la debería haber'::text,'no se la puede haber'::text,'Su camiseta de tirantes está seca en la barra, así que se la debe de haber quitado antes de empaparse.'::text),
(389066,43230,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son débardeur est sec sur la barre, donc il ... l''enlever avant d''être trempé.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Son débardeur est sec sur la barre, donc il a dû l''enlever avant d''être trempé.'::text),
(389069,43230,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Atleti askıda kuru, yani sırılsıklam olmadan önce onu çıkarmış ...'::text,'olmalı'::text,'olmalıydı'::text,'olamaz'::text,'Atleti askıda kuru, yani sırılsıklam olmadan önce onu çıkarmış olmalı.'::text),
(389070,43230,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A trikója szárazon lóg a rúdon, tehát ... levette, mielőtt bőrig ázott.'::text,'biztosan'::text,'jobb lett volna, ha'::text,'nem lehet, hogy'::text,'A trikója szárazon lóg a rúdon, tehát biztosan levette, mielőtt bőrig ázott.'::text),
(389082,43232,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, als er rauskam, ... er schon 20 Minuten unter dem Wasser gestanden, klatschnass, echt.'::text,'hatte'::text,'hat'::text,'steht'::text,'Bro, als er rauskam, hatte er schon 20 Minuten unter dem Wasser gestanden, klatschnass, echt.'::text),
(389086,43232,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки він вийшов, він ... під водою 20 хвилин, реально мокрий.'::text,'простояв'::text,'стоїть'::text,'стоїть'::text,'Бро, поки він вийшов, він простояв під водою 20 хвилин, реально мокрий.'::text),
(389085,43232,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para cuando salió, ... 20 minutos bajo el agua, empapado de verdad.'::text,'llevaba'::text,'ha estado'::text,'está'::text,'Bro, para cuando salió, llevaba 20 minutos bajo el agua, empapado de verdad.'::text),
(389084,43232,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, quand il est sorti, il ... sous l''eau depuis 20 minutes, trempé pour de vrai.'::text,'était'::text,'est'::text,'est'::text,'Frérot, quand il est sorti, il était sous l''eau depuis 20 minutes, trempé pour de vrai.'::text),
(389087,43232,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, çıktığında 20 dakikadır suyun altında ..., cidden sırılsıklam.'::text,'duruyordu'::text,'duruyor'::text,'duruyor'::text,'Kanka, çıktığında 20 dakikadır suyun altında duruyordu, cidden sırılsıklam.'::text),
(389088,43232,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire kijött, már 20 perce ... a víz alatt, komolyan bőrig ázva.'::text,'állt'::text,'áll'::text,'áll'::text,'Tesó, mire kijött, már 20 perce állt a víz alatt, komolyan bőrig ázva.'::text),
(386715,42969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mein Geschwisterteil ... nach dem letzten Keks, als ich mir den Teller schnappte! Totaler Krieg!'::text,'griff gerade'::text,'griff'::text,'hat gegriffen'::text,'Mein Geschwisterteil griff gerade nach dem letzten Keks, als ich mir den Teller schnappte! Totaler Krieg!'::text),
(386719,42969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Моя сестра ... по останнє печиво, коли я схопила тарілку! Тотальна війна!'::text,'тягнулася'::text,'потягнулася'::text,'потягнулася'::text,'Моя сестра тягнулася по останнє печиво, коли я схопила тарілку! Тотальна війна!'::text),
(386718,42969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mi hermana ... la mano hacia la última galleta cuando agarré el plato! ¡Guerra total!'::text,'estaba estirando'::text,'estiró'::text,'ha estirado'::text,'¡Mi hermana estaba estirando la mano hacia la última galleta cuando agarré el plato! ¡Guerra total!'::text),
(386717,42969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma sœur ... la main vers le dernier cookie quand j''ai attrapé l''assiette ! Guerre totale !'::text,'tendait'::text,'a tendu'::text,'a tendu'::text,'Ma sœur tendait la main vers le dernier cookie quand j''ai attrapé l''assiette ! Guerre totale !'::text),
(386720,42969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabağı kaptığımda kardeşim son kurabiyeye ...! Tam bir savaş!'::text,'uzanıyordu'::text,'uzandı'::text,'uzandı'::text,'Tabağı kaptığımda kardeşim son kurabiyeye uzanıyordu! Tam bir savaş!'::text),
(386721,42969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A testvérem épp ... az utolsó kekszért, amikor elkaptam a tányért! Totális háború!'::text,'nyúlt'::text,'nyúlt'::text,'nyúlt'::text,'A testvérem épp nyúlt az utolsó kekszért, amikor elkaptam a tányért! Totális háború!'::text),
(386724,42970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Echt jetzt, ich hab gehört, die Geschwister ... sich seit dem Frühstück um Kekse.'::text,'streiten'::text,'streiten'::text,'streiten'::text,'Echt jetzt, ich hab gehört, die Geschwister streiten sich seit dem Frühstück um Kekse.'::text),
(386728,42970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, я чула, що ці сестри ... через печиво ще від сніданку.'::text,'сваряться'::text,'сваряться'::text,'сваряться'::text,'Та ну, я чула, що ці сестри сваряться через печиво ще від сніданку.'::text),
(386727,42970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede ser, me han dicho que esas hermanas ... por las galletas desde el desayuno.'::text,'llevan peleándose'::text,'se están peleando'::text,'se pelean'::text,'No puede ser, me han dicho que esas hermanas llevan peleándose por las galletas desde el desayuno.'::text),
(386726,42970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, j''ai entendu que ces sœurs se ... pour des cookies depuis le petit-déj.'::text,'disputent'::text,'disputent'::text,'disputent'::text,'Sérieux, j''ai entendu que ces sœurs se disputent pour des cookies depuis le petit-déj.'::text),
(386729,42970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, duydum ki o kardeşler kahvaltıdan beri kurabiye yüzünden ...'::text,'kavga ediyormuş'::text,'kavga ediyormuş'::text,'kavga edermiş'::text,'Yok artık, duydum ki o kardeşler kahvaltıdan beri kurabiye yüzünden kavga ediyormuş.'::text),
(386730,42970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, azt hallottam, hogy azok a testvérek reggeli óta ... a kekszeken.'::text,'veszekednek'::text,'veszekednek'::text,'veszekednek'::text,'Ne már, azt hallottam, hogy azok a testvérek reggeli óta veszekednek a kekszeken.'::text),
(386733,42971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, die Geschwister ... sich angeblich unter der Decke, als ihre Mama reinkam.'::text,'versteckten'::text,'versteckten'::text,'haben versteckt'::text,'Hör mal, die Geschwister versteckten sich angeblich unter der Decke, als ihre Mama reinkam.'::text),
(386737,42971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, сестри ... під ковдрою, коли зайшла їхня мама.'::text,'ховалися'::text,'сховалися'::text,'сховалися'::text,'Слухай, кажуть, сестри ховалися під ковдрою, коли зайшла їхня мама.'::text),
(386736,42971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer las hermanas se ... bajo la manta cuando entró su madre.'::text,'estaban escondiendo'::text,'escondieron'::text,'han escondido'::text,'Oye, al parecer las hermanas se estaban escondiendo bajo la manta cuando entró su madre.'::text),
(386735,42971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment les sœurs se ... sous la couverture quand leur mère est entrée.'::text,'cachaient'::text,'sont cachées'::text,'sont cachées'::text,'Écoute, apparemment les sœurs se cachaient sous la couverture quand leur mère est entrée.'::text),
(386738,42971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, anneleri içeri girdiğinde kardeşler battaniyenin altında ...'::text,'saklanıyormuş'::text,'saklanmış'::text,'saklanmış'::text,'Dinle, anneleri içeri girdiğinde kardeşler battaniyenin altında saklanıyormuş.'::text),
(386739,42971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a testvérek a takaró alatt ..., amikor bejött az anyjuk.'::text,'bujkáltak'::text,'elbújtak'::text,'elbújtak'::text,'Figyelj, állítólag a testvérek a takaró alatt bujkáltak, amikor bejött az anyjuk.'::text),
(386742,42972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, sie hat mir erzählt, dass ihr Geschwisterteil heute schon drei Kekse ...'::text,'gegessen hat'::text,'gegessen hat'::text,'isst'::text,'Also, sie hat mir erzählt, dass ihr Geschwisterteil heute schon drei Kekse gegessen hat.'::text),
(386746,42972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, вона сказала мені, що її сестра сьогодні вже ... три печива.'::text,'з''їла'::text,'їла'::text,'їсть'::text,'Коротше, вона сказала мені, що її сестра сьогодні вже з''їла три печива.'::text),
(386745,42972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues me dijo que su hermana ya ... tres galletas hoy.'::text,'se ha comido'::text,'ha estado comiendo'::text,'está comiendo'::text,'Vale, pues me dijo que su hermana ya se ha comido tres galletas hoy.'::text),
(386744,42972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, elle m''a dit que sa sœur ... déjà trois cookies aujourd''hui.'::text,'a mangé'::text,'mange'::text,'mange'::text,'Bon, elle m''a dit que sa sœur a mangé déjà trois cookies aujourd''hui.'::text),
(386747,42972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, bana kardeşinin bugün şimdiden üç kurabiye ... söyledi.'::text,'yediğini'::text,'yediğini'::text,'yediğini'::text,'Neyse, bana kardeşinin bugün şimdiden üç kurabiye yediğini söyledi.'::text),
(386748,42972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, hogy a testvére ma már három kekszet ...'::text,'megevett'::text,'evett'::text,'eszik'::text,'Szóval azt mondta, hogy a testvére ma már három kekszet megevett.'::text),
(386751,42973,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Teller leer war, ... jedes Geschwisterteil seinen eigenen Keks genommen.'::text,'hatte'::text,'hat'::text,'nimmt'::text,'Als der Teller leer war, hatte jedes Geschwisterteil seinen eigenen Keks genommen.'::text),
(386755,42973,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли тарілка спорожніла, кожна сестра ... своє печиво.'::text,'вже взяла'::text,'взяла'::text,'бере'::text,'Коли тарілка спорожніла, кожна сестра вже взяла своє печиво.'::text),
(386754,42973,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el plato quedó vacío, cada hermana ... su propia galleta.'::text,'había cogido'::text,'ha cogido'::text,'coge'::text,'Cuando el plato quedó vacío, cada hermana había cogido su propia galleta.'::text),
(386753,42973,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''assiette a été vide, chaque sœur ... son propre cookie.'::text,'avait pris'::text,'a pris'::text,'prend'::text,'Quand l''assiette a été vide, chaque sœur avait pris son propre cookie.'::text),
(386756,42973,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabak boşaldığında her kardeş kendi kurabiyesini ...'::text,'almıştı'::text,'aldı'::text,'alıyor'::text,'Tabak boşaldığında her kardeş kendi kurabiyesini almıştı.'::text),
(386757,42973,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a tányér kiürült, mindegyik testvér ... a saját kekszét.'::text,'elvette már'::text,'elvette'::text,'elveszi'::text,'Mire a tányér kiürült, mindegyik testvér elvette már a saját kekszét.'::text),
(386778,42976,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Höhle, ... die Geschwister aus einer Decke gebaut haben, steht im Wohnzimmer.'::text,'die'::text,'die'::text,'was'::text,'Die Höhle, die die Geschwister aus einer Decke gebaut haben, steht im Wohnzimmer.'::text),
(386782,42976,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курінь, ... сестри збудували з ковдри, стоїть у вітальні.'::text,'який'::text,'що'::text,'що'::text,'Курінь, який сестри збудували з ковдри, стоїть у вітальні.'::text),
(386781,42976,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cabaña, ... las hermanas construyeron con una manta, está en el salón.'::text,'que'::text,'que'::text,'lo que'::text,'La cabaña, que las hermanas construyeron con una manta, está en el salón.'::text),
(386780,42976,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cabane, ... les sœurs ont construite avec une couverture, se trouve dans le salon.'::text,'que'::text,'que'::text,'ce que'::text,'La cabane, que les sœurs ont construite avec une couverture, se trouve dans le salon.'::text),
(386783,42976,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kardeşlerin battaniyeden ... yaptığı kale oturma odasında duruyor.'::text,''::text,NULL::text,NULL::text,'Kardeşlerin battaniyeden yaptığı kale oturma odasında duruyor.'::text),
(386784,42976,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kuckó, ... a testvérek egy takaróból építettek, a nappaliban áll.'::text,'amelyet'::text,'amit'::text,'ami'::text,'A kuckó, amelyet a testvérek egy takaróból építettek, a nappaliban áll.'::text),
(386787,42977,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geschwister, die ... spielen, bauen häufig Höhlen aus Decken.'::text,'zu Hause'::text,'im Zuhause'::text,'in einem Zuhause'::text,'Geschwister, die zu Hause spielen, bauen häufig Höhlen aus Decken.'::text),
(386791,42977,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брати й сестри, які граються ..., часто будують курені з ковдр.'::text,'вдома'::text,'вдома'::text,'вдома'::text,'Брати й сестри, які граються вдома, часто будують курені з ковдр.'::text),
(386790,42977,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los hermanos que juegan ... construyen con frecuencia cabañas con mantas.'::text,'en casa'::text,'en la casa'::text,'en una casa'::text,'Los hermanos que juegan en casa construyen con frecuencia cabañas con mantas.'::text),
(386789,42977,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les frères et sœurs qui jouent ... construisent souvent des cabanes avec des couvertures.'::text,'à la maison'::text,'dans la maison'::text,'dans une maison'::text,'Les frères et sœurs qui jouent à la maison construisent souvent des cabanes avec des couvertures.'::text),
(386792,42977,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... oynayan kardeşler sık sık battaniyelerden kale yapar.'::text,'Evde'::text,'Evde'::text,'Bir evde'::text,'Evde oynayan kardeşler sık sık battaniyelerden kale yapar.'::text),
(386793,42977,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azok a testvérek, akik ... játszanak, gyakran építenek kuckót takarókból.'::text,'otthon'::text,'az otthonban'::text,'egy otthonban'::text,'Azok a testvérek, akik otthon játszanak, gyakran építenek kuckót takarókból.'::text),
(386796,42978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ihrer gemütlichen Höhle begannen die Geschwister einen schrecklichen Krieg um einen einzigen Keks!'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz ihrer gemütlichen Höhle begannen die Geschwister einen schrecklichen Krieg um einen einzigen Keks!'::text),
(386800,42978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... свій затишний курінь, сестри почали жахливу війну за одне печиво!'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри свій затишний курінь, сестри почали жахливу війну за одне печиво!'::text),
(386799,42978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... su acogedora cabaña, las hermanas empezaron una guerra terrible por una galleta!'::text,'A pesar de'::text,'Aunque'::text,'Por culpa de'::text,'¡A pesar de su acogedora cabaña, las hermanas empezaron una guerra terrible por una galleta!'::text),
(386798,42978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... leur cabane douillette, les sœurs ont déclenché une terrible guerre pour un seul cookie !'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré leur cabane douillette, les sœurs ont déclenché une terrible guerre pour un seul cookie !'::text),
(386801,42978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahat kalelerine ..., kardeşler tek bir kurabiye için korkunç bir savaş başlattı!'::text,'rağmen'::text,'karşın'::text,'yüzünden'::text,'Rahat kalelerine rağmen, kardeşler tek bir kurabiye için korkunç bir savaş başlattı!'::text),
(386802,42978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kényelmes kuckójuk ..., a testvérek szörnyű háborút indítottak egyetlen kekszért!'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A kényelmes kuckójuk ellenére, a testvérek szörnyű háborút indítottak egyetlen kekszért!'::text),
(386805,42979,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... mein Geschwisterteil jeden einzelnen Keks im Haus gegessen haben! Katastrophe!'::text,'wird'::text,'wird'::text,'isst'::text,'Bis heute Abend wird mein Geschwisterteil jeden einzelnen Keks im Haus gegessen haben! Katastrophe!'::text),
(386809,42979,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора моя сестра ... кожне печиво в домі! Катастрофа!'::text,'вже з''їсть'::text,'з''їсть'::text,'їсть'::text,'До вечора моя сестра вже з''їсть кожне печиво в домі! Катастрофа!'::text),
(386808,42979,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para esta noche, mi hermana ... todas y cada una de las galletas de la casa! ¡Desastre!'::text,'se habrá comido'::text,'se comerá'::text,'se come'::text,'¡Para esta noche, mi hermana se habrá comido todas y cada una de las galletas de la casa! ¡Desastre!'::text),
(386807,42979,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, ma sœur ... tous les cookies de la maison ! Catastrophe !'::text,'aura mangé'::text,'mangera'::text,'mange'::text,'D''ici ce soir, ma sœur aura mangé tous les cookies de la maison ! Catastrophe !'::text),
(386810,42979,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar kardeşim evdeki her bir kurabiyeyi ...! Felaket!'::text,'yemiş olacak'::text,'yiyecek'::text,'yiyor'::text,'Bu akşama kadar kardeşim evdeki her bir kurabiyeyi yemiş olacak! Felaket!'::text),
(386811,42979,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére a testvérem ... a ház összes kekszét! Katasztrófa!'::text,'megeszi'::text,'meg fogja enni'::text,'eszi'::text,'Estére a testvérem megeszi a ház összes kekszét! Katasztrófa!'::text),
(342840,38094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... an der Ecke die Straße, als ein Auto für ihn anhielt. Wirklich aufregend.'::text,'überquerte gerade'::text,'überquerte'::text,'hat überquert'::text,'Er überquerte gerade an der Ecke die Straße, als ein Auto für ihn anhielt. Wirklich aufregend.'::text),
(342844,38094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... вулицю на розі, коли для нього зупинилася машина. Справді захопливо.'::text,'переходив'::text,'перейшов'::text,'перейшов'::text,'Він переходив вулицю на розі, коли для нього зупинилася машина. Справді захопливо.'::text)
