from (values
(342843,38094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la calle en la esquina cuando un coche paró por él. Verdaderamente emocionante.'::text,'estaba cruzando'::text,'cruzó'::text,'ha cruzado'::text,'Él estaba cruzando la calle en la esquina cuando un coche paró por él. Verdaderamente emocionante.'::text),
(342842,38094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la rue au coin quand une voiture s''est arrêtée pour lui. Vraiment palpitant.'::text,'traversait'::text,'a traversé'::text,'a traversé'::text,'Il traversait la rue au coin quand une voiture s''est arrêtée pour lui. Vraiment palpitant.'::text),
(342845,38094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köşede caddeyi ... bir araba onun için durdu. Gerçekten heyecan verici.'::text,'geçerken'::text,'geçti'::text,'geçti'::text,'Köşede caddeyi geçerken bir araba onun için durdu. Gerçekten heyecan verici.'::text),
(342846,38094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az utcán a saroknál, amikor megállt neki egy autó. Igazán izgalmas.'::text,'kelt át'::text,'átkelt'::text,'átkelt'::text,'Épp kelt át az utcán a saroknál, amikor megállt neki egy autó. Igazán izgalmas.'::text),
(342849,38095,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit ganzen zehn Sekunden an dieser Ecke. Ein echtes Abenteuer, klar.'::text,'steht'::text,'steht'::text,'steht'::text,'Er steht seit ganzen zehn Sekunden an dieser Ecke. Ein echtes Abenteuer, klar.'::text),
(342853,38095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на цьому розі цілих десять секунд. Справжня пригода, ясно.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Він стоїть на цьому розі цілих десять секунд. Справжня пригода, ясно.'::text),
(342852,38095,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... en esta esquina desde hace diez segundos enteros. Toda una aventura, claramente.'::text,'lleva parado'::text,'está parado'::text,'se para'::text,'Él lleva parado en esta esquina desde hace diez segundos enteros. Toda una aventura, claramente.'::text),
(342851,38095,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... à ce coin depuis dix secondes entières. Une vraie aventure, clairement.'::text,'est planté'::text,'est planté'::text,'se tient'::text,'Il est planté à ce coin depuis dix secondes entières. Une vraie aventure, clairement.'::text),
(342854,38095,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu köşede tam on saniyedir ..., gerçek bir macera, belli ki.'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Bu köşede tam on saniyedir duruyor, gerçek bir macera, belli ki.'::text),
(342855,38095,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már tíz teljes másodperce ... ezen a sarkon. Igazi kaland, nyilván.'::text,'áll'::text,'áll'::text,'áll'::text,'Már tíz teljes másodperce áll ezen a sarkon. Igazi kaland, nyilván.'::text),
(342858,38096,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er zur Ecke ..., fuhr ein Radfahrer vorbei.'::text,'lief'::text,'lief'::text,'ist gelaufen'::text,'Während er zur Ecke lief, fuhr ein Radfahrer vorbei.'::text),
(342862,38096,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... до рогу, повз проїхав велосипедист.'::text,'ішов'::text,'пішов'::text,'пішов'::text,'Поки він ішов до рогу, повз проїхав велосипедист.'::text),
(342861,38096,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... hacia la esquina, pasó un ciclista.'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'Mientras caminaba hacia la esquina, pasó un ciclista.'::text),
(342860,38096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... vers le coin, un cycliste est passé.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Pendant qu''il marchait vers le coin, un cycliste est passé.'::text),
(342863,38096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köşeye doğru ..., bir bisikletçi geçti.'::text,'yürürken'::text,'yürüdü'::text,'yürüdü'::text,'O köşeye doğru yürürken, bir bisikletçi geçti.'::text),
(342864,38096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a sarok felé ..., elhaladt mellette egy biciklis.'::text,'sétált'::text,'ment'::text,'ment'::text,'Miközben a sarok felé sétált, elhaladt mellette egy biciklis.'::text),
(342867,38097,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute ... er dreimal an dieser Ecke vorbeigelaufen.'::text,'ist'::text,'ist'::text,'läuft'::text,'Heute ist er dreimal an dieser Ecke vorbeigelaufen.'::text),
(342871,38097,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні він ... повз цей ріг тричі.'::text,'пройшов'::text,'ходив'::text,'іде'::text,'Сьогодні він пройшов повз цей ріг тричі.'::text),
(342870,38097,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... por esta esquina tres veces.'::text,'ha pasado'::text,'ha estado pasando'::text,'está pasando'::text,'Hoy ha pasado por esta esquina tres veces.'::text),
(342869,38097,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... devant ce coin trois fois aujourd''hui.'::text,'est passé'::text,'passe'::text,'passe'::text,'Il est passé devant ce coin trois fois aujourd''hui.'::text),
(342872,38097,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün bu köşeden üç kez ...'::text,'geçti'::text,'geçip duruyor'::text,'geçiyor'::text,'Bugün bu köşeden üç kez geçti.'::text),
(342873,38097,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma már háromszor ... el a sarok mellett.'::text,'ment'::text,'járkált'::text,'megy'::text,'Ma már háromszor ment el a sarok mellett.'::text),
(342876,38098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er die Ecke erreichte, ... der Radfahrer schon an ihm vorbeigefahren.'::text,'war'::text,'ist'::text,'fährt'::text,'Als er die Ecke erreichte, war der Radfahrer schon an ihm vorbeigefahren.'::text),
(342880,38098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він дійшов до рогу, велосипедист уже ... повз нього.'::text,'проїхав'::text,'проїхав'::text,'проїжджає'::text,'Коли він дійшов до рогу, велосипедист уже проїхав повз нього.'::text),
(342879,38098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó a la esquina, el ciclista ya ... a su lado.'::text,'había pasado'::text,'ha pasado'::text,'pasa'::text,'Para cuando llegó a la esquina, el ciclista ya había pasado a su lado.'::text),
(342878,38098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a atteint le coin, le cycliste ... déjà passé à côté de lui.'::text,'était'::text,'est'::text,'passe'::text,'Quand il a atteint le coin, le cycliste était déjà passé à côté de lui.'::text),
(342881,38098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köşeye vardığında bisikletçi yanından çoktan ...'::text,'geçmişti'::text,'geçti'::text,'geçiyor'::text,'O köşeye vardığında bisikletçi yanından çoktan geçmişti.'::text),
(342882,38098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a sarokhoz ért, a biciklis már ... mellette.'::text,'elhajtott'::text,'elhajtott'::text,'elhajt'::text,'Mire a sarokhoz ért, a biciklis már elhajtott mellette.'::text),
(342885,38099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nachdem er an der Ecke die Straße überquert hat, geht er weiter ..., wie jeden Werktag.'::text,'zur Arbeit'::text,'zu der Arbeit'::text,'zu einer Arbeit'::text,'Nachdem er an der Ecke die Straße überquert hat, geht er weiter zur Arbeit, wie jeden Werktag.'::text),
(342889,38099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перейшовши на розі, він іде далі ..., як кожного буднього дня.'::text,'на роботу'::text,'на роботу'::text,'на роботу'::text,'Перейшовши на розі, він іде далі на роботу, як кожного буднього дня.'::text),
(342888,38099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de cruzar en la esquina, sigue andando ... como cada día laborable.'::text,'al trabajo'::text,'al trabajo'::text,'a un trabajo'::text,'Después de cruzar en la esquina, sigue andando al trabajo como cada día laborable.'::text),
(342887,38099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après avoir traversé au coin, il continue ... comme chaque jour de semaine.'::text,'au travail'::text,'au travail'::text,'à un travail'::text,'Après avoir traversé au coin, il continue au travail comme chaque jour de semaine.'::text),
(342890,38099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köşede karşıya geçtikten sonra her hafta içi olduğu gibi ... yürümeye devam ediyor.'::text,'işe'::text,'işe'::text,'bir işe'::text,'Köşede karşıya geçtikten sonra her hafta içi olduğu gibi işe yürümeye devam ediyor.'::text),
(342891,38099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miután átkelt a saroknál, továbbmegy ..., mint minden hétköznap.'::text,'munkába'::text,'a munkába'::text,'egy munkába'::text,'Miután átkelt a saroknál, továbbmegy munkába, mint minden hétköznap.'::text),
(342894,38100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des dichten Verkehrs überquert das Subjekt die Kreuzung an der Ecke ruhig.'::text,'Trotz'::text,'Obwohl'::text,'Aufgrund'::text,'Trotz des dichten Verkehrs überquert das Subjekt die Kreuzung an der Ecke ruhig.'::text),
(342898,38100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... інтенсивний рух, суб''єкт спокійно перетинає перехрестя на розі.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри інтенсивний рух, суб''єкт спокійно перетинає перехрестя на розі.'::text),
(342897,38100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el tráfico denso, el sujeto cruza tranquilamente el cruce de la esquina.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de el tráfico denso, el sujeto cruza tranquilamente el cruce de la esquina.'::text),
(342896,38100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la circulation dense, le sujet traverse calmement le carrefour au coin.'::text,'Malgré'::text,'Bien que'::text,'En raison de'::text,'Malgré la circulation dense, le sujet traverse calmement le carrefour au coin.'::text),
(342899,38100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yoğun trafiğe ..., denek köşedeki kavşaktan sakince geçiyor.'::text,'rağmen'::text,'karşın'::text,'nedeniyle'::text,'Yoğun trafiğe rağmen, denek köşedeki kavşaktan sakince geçiyor.'::text),
(342900,38100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sűrű forgalom ..., az alany nyugodtan kel át a kereszteződésen a saroknál.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A sűrű forgalom ellenére, az alany nyugodtan kel át a kereszteződésen a saroknál.'::text),
(342903,38101,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du wusstest, dass die Autos an der Ecke für dich ..., und das taten sie.'::text,'anhalten würden'::text,'anhalten werden'::text,'gerade anhalten'::text,'Ehrlich, du wusstest, dass die Autos an der Ecke für dich anhalten würden, und das taten sie.'::text),
(342907,38101,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти знав, що машини ... для тебе на тому розі, і вони зупинилися.'::text,'зупиняться'::text,'зупиняться'::text,'зупиняються'::text,'Чесно, ти знав, що машини зупиняться для тебе на тому розі, і вони зупинилися.'::text),
(342906,38101,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, sabías que los coches ... por ti en esa esquina, y así fue.'::text,'pararían'::text,'pararán'::text,'están parando'::text,'Sinceramente, sabías que los coches pararían por ti en esa esquina, y así fue.'::text),
(342905,38101,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu savais que les voitures ... pour toi à ce coin, et c''est ce qu''elles ont fait.'::text,'s''arrêteraient'::text,'s''arrêteront'::text,'s''arrêtent'::text,'Franchement, tu savais que les voitures s''arrêteraient pour toi à ce coin, et c''est ce qu''elles ont fait.'::text),
(342908,38101,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, arabaların o köşede senin için ... biliyordun ve durdular.'::text,'duracağını'::text,'duracağını'::text,'durduğunu'::text,'Açıkçası, arabaların o köşede senin için duracağını biliyordun ve durdular.'::text),
(342909,38101,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, tudtad, hogy az autók ... neked azon a sarkon, és meg is álltak.'::text,'megállnak majd'::text,'meg fognak állni'::text,'megállnak'::text,'Őszintén, tudtad, hogy az autók megállnak majd neked azon a sarkon, és meg is álltak.'::text),
(342912,38102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... du mit Main-Character-Energy an dieser Ecke vorbei, ganz ehrlich.'::text,'läufst'::text,'läufst'::text,'bist gelaufen'::text,'Gerade läufst du mit Main-Character-Energy an dieser Ecke vorbei, ganz ehrlich.'::text),
(342916,38102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз ти ... повз той ріг з енергією головного героя, чесно.'::text,'ідеш'::text,'ідеш'::text,'пройшов'::text,'Саме зараз ти ідеш повз той ріг з енергією головного героя, чесно.'::text),
(342915,38102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... por esa esquina con energía de protagonista, no te voy a mentir.'::text,'estás pasando'::text,'pasas'::text,'has pasado'::text,'Ahora mismo estás pasando por esa esquina con energía de protagonista, no te voy a mentir.'::text),
(342914,38102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, tu ... devant ce coin avec une énergie de personnage principal, je vais pas mentir.'::text,'passes'::text,'passes'::text,'es passé'::text,'En ce moment, tu passes devant ce coin avec une énergie de personnage principal, je vais pas mentir.'::text),
(342917,38102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda o köşeden ana karakter enerjisiyle ..., yalan yok.'::text,'geçiyorsun'::text,'geçersin'::text,'geçtin'::text,'Şu anda o köşeden ana karakter enerjisiyle geçiyorsun, yalan yok.'::text),
(342918,38102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... el azon a sarkon főszereplő-energiával, nem hazudok.'::text,'sétálsz'::text,'sétálsz'::text,'sétáltál'::text,'Épp most sétálsz el azon a sarkon főszereplő-energiával, nem hazudok.'::text),
(342921,38103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du sahst so selbstbewusst aus, als ... du diese Ecke schon hundertmal überquert. Respekt.'::text,'hättest'::text,'hast'::text,'würdest'::text,'Du sahst so selbstbewusst aus, als hättest du diese Ecke schon hundertmal überquert. Respekt.'::text),
(342925,38103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти виглядав таким упевненим, ніби вже сто разів ... той ріг. Респект.'::text,'перейшов'::text,'перейшов'::text,'переходив'::text,'Ти виглядав таким упевненим, ніби вже сто разів перейшов той ріг. Респект.'::text),
(342924,38103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parecías tan seguro, como si ... esa esquina cien veces antes. Respeto.'::text,'hubieras cruzado'::text,'has cruzado'::text,'estuvieras cruzando'::text,'Parecías tan seguro, como si hubieras cruzado esa esquina cien veces antes. Respeto.'::text),
(342923,38103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu avais l''air si sûr de toi, comme si tu ... ce coin cent fois avant. Respect.'::text,'avais traversé'::text,'as traversé'::text,'traversais'::text,'Tu avais l''air si sûr de toi, comme si tu avais traversé ce coin cent fois avant. Respect.'::text),
(342926,38103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köşeyi daha önce yüz kez ... gibi çok özgüvenli görünüyordun. Helal.'::text,'geçmişsin'::text,'geçtin'::text,'geçiyordun'::text,'O köşeyi daha önce yüz kez geçmişsin gibi çok özgüvenli görünüyordun. Helal.'::text),
(342927,38103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan magabiztosnak tűntél, mintha már százszor ... azon a sarkon. Respekt.'::text,'keltél volna át'::text,'keltél át'::text,'kelnél át'::text,'Olyan magabiztosnak tűntél, mintha már százszor keltél volna át azon a sarkon. Respekt.'::text),
(342930,38104,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... er an dieser Ecke etwa fünfzigmal vorbeigekommen sein. Ein aufregendes Leben, klar.'::text,'wird'::text,'wird'::text,'kommt'::text,'Bis heute Abend wird er an dieser Ecke etwa fünfzigmal vorbeigekommen sein. Ein aufregendes Leben, klar.'::text),
(342934,38104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора він ... повз цей ріг десь п''ятдесят разів. Захопливе життя, ясно.'::text,'пройде'::text,'пройде'::text,'проходить'::text,'До вечора він пройде повз цей ріг десь п''ятдесят разів. Захопливе життя, ясно.'::text),
(342933,38104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, ... por esta esquina unas cincuenta veces. Una vida emocionante, claramente.'::text,'habrá pasado'::text,'pasará'::text,'pasa'::text,'Para esta noche, habrá pasado por esta esquina unas cincuenta veces. Una vida emocionante, claramente.'::text),
(342932,38104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, il ... devant ce coin une cinquantaine de fois. Une vie palpitante, clairement.'::text,'sera passé'::text,'passera'::text,'passe'::text,'D''ici ce soir, il sera passé devant ce coin une cinquantaine de fois. Une vie palpitante, clairement.'::text),
(342935,38104,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar bu köşeden elli kez kadar ..., heyecan dolu bir hayat, belli ki.'::text,'geçmiş olacak'::text,'geçecek'::text,'geçer'::text,'Bu akşama kadar bu köşeden elli kez kadar geçmiş olacak, heyecan dolu bir hayat, belli ki.'::text),
(342936,38104,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére nagyjából ötvenszer ... ezen a sarkon. Izgalmas élet, nyilván.'::text,'el fog haladni'::text,'elhalad majd'::text,'elhalad'::text,'Estére nagyjából ötvenszer el fog haladni ezen a sarkon. Izgalmas élet, nyilván.'::text),
(384267,42697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... die riesige Schriftrolle, als die Kameras blitzten, und du bliebst ruhig. Respekt.'::text,'unterschriebst gerade'::text,'unterschriebst'::text,'hast unterschrieben'::text,'Du unterschriebst gerade die riesige Schriftrolle, als die Kameras blitzten, und du bliebst ruhig. Respekt.'::text),
(384271,42697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... величезний сувій, коли спалахнули камери, і залишався спокійним. Респект.'::text,'підписував'::text,'підписав'::text,'підписав'::text,'Ти підписував величезний сувій, коли спалахнули камери, і залишався спокійним. Респект.'::text),
(384270,42697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... el pergamino gigante cuando saltaron los flashes, y mantuviste la calma. Respeto.'::text,'estabas firmando'::text,'firmaste'::text,'has firmado'::text,'Tú estabas firmando el pergamino gigante cuando saltaron los flashes, y mantuviste la calma. Respeto.'::text),
(384269,42697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... le rouleau géant quand les appareils ont flashé, et tu es resté calme. Respect.'::text,'signais'::text,'as signé'::text,'as signé'::text,'Tu signais le rouleau géant quand les appareils ont flashé, et tu es resté calme. Respect.'::text),
(384272,42697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kameralar flaş patlattığında sen dev tomarı ... ve sakin kaldın. Helal.'::text,'imzalıyordun'::text,'imzaladın'::text,'imzaladın'::text,'Kameralar flaş patlattığında sen dev tomarı imzalıyordun ve sakin kaldın. Helal.'::text),
(384273,42697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az óriási tekercset, amikor villantak a kamerák, és nyugodt maradtál. Respekt.'::text,'írtad alá'::text,'aláírtad'::text,'aláírtad'::text,'Épp írtad alá az óriási tekercset, amikor villantak a kamerák, és nyugodt maradtál. Respekt.'::text),
(384276,42698,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Schriftrolle noch länger wäre, ... sie über das Ende des Tisches hängen.'::text,'würde'::text,'wird'::text,'hängt'::text,'Wenn die Schriftrolle noch länger wäre, würde sie über das Ende des Tisches hängen.'::text),
(384280,42698,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сувій був ще довшим, він ... з краю столу.'::text,'звисав би'::text,'звисатиме'::text,'звисає'::text,'Якби сувій був ще довшим, він звисав би з краю столу.'::text),
(384279,42698,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el pergamino fuera más largo, ... por el borde de la mesa.'::text,'colgaría'::text,'colgará'::text,'cuelga'::text,'Si el pergamino fuera más largo, colgaría por el borde de la mesa.'::text),
(384278,42698,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le rouleau était encore plus long, il ... au bout de la table.'::text,'pendrait'::text,'pendra'::text,'pend'::text,'Si le rouleau était encore plus long, il pendrait au bout de la table.'::text),
(384281,42698,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tomar biraz daha uzun olsaydı, masanın ucundan ...'::text,'sarkardı'::text,'sarkacak'::text,'sarkıyor'::text,'Tomar biraz daha uzun olsaydı, masanın ucundan sarkardı.'::text),
(384282,42698,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tekercs még hosszabb lenne, ... az asztal végéről.'::text,'lelógna'::text,'le fog lógni'::text,'lelóg'::text,'Ha a tekercs még hosszabb lenne, lelógna az asztal végéről.'::text),
(384285,42699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die riesige Schriftrolle ... von zwei Assistenten über den Tisch ausgerollt.'::text,'wurde'::text,'rollte'::text,'rollt gerade'::text,'Die riesige Schriftrolle wurde von zwei Assistenten über den Tisch ausgerollt.'::text),
(384289,42699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Величезний сувій ... двома асистентами вздовж столу.'::text,'був розгорнутий'::text,'розгорнув'::text,'розгортає'::text,'Величезний сувій був розгорнутий двома асистентами вздовж столу.'::text),
(384288,42699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pergamino gigante ... sobre la mesa por dos asistentes.'::text,'fue desenrollado'::text,'desenrolló'::text,'está desenrollando'::text,'El pergamino gigante fue desenrollado sobre la mesa por dos asistentes.'::text),
(384287,42699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le rouleau géant ... sur la table par deux assistants.'::text,'a été déroulé'::text,'a déroulé'::text,'est en train de dérouler'::text,'Le rouleau géant a été déroulé sur la table par deux assistants.'::text),
(384290,42699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev tomar iki asistan tarafından masa boyunca ...'::text,'açıldı'::text,'açtı'::text,'açıyor'::text,'Dev tomar iki asistan tarafından masa boyunca açıldı.'::text),
(384291,42699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óriási tekercset két asszisztens ... végig az asztalon.'::text,'tekerte ki'::text,'kitekerte'::text,'tekeri ki'::text,'Az óriási tekercset két asszisztens tekerte ki végig az asztalon.'::text),
(384294,42700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei Assistenten ... die riesige Schriftrolle über den ganzen Tisch aus.'::text,'rollten'::text,'wurden ausgerollt'::text,'ausrollend'::text,'Zwei Assistenten rollten die riesige Schriftrolle über den ganzen Tisch aus.'::text),
(384298,42700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє асистентів ... величезний сувій уздовж усього столу.'::text,'розгорнули'::text,'були розгорнуті'::text,'розгортаючи'::text,'Двоє асистентів розгорнули величезний сувій уздовж усього столу.'::text),
(384297,42700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos asistentes ... el enorme pergamino a lo largo de toda la mesa.'::text,'desenrollaron'::text,'fueron desenrollados'::text,'desenrollando'::text,'Dos asistentes desenrollaron el enorme pergamino a lo largo de toda la mesa.'::text),
(384296,42700,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux assistants ... l''immense rouleau sur toute la table.'::text,'ont déroulé'::text,'ont été déroulés'::text,'déroulant'::text,'Deux assistants ont déroulé l''immense rouleau sur toute la table.'::text),
(384299,42700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki asistan kocaman tomarı bütün masa boyunca ...'::text,'açtı'::text,'açıldı'::text,'açarak'::text,'İki asistan kocaman tomarı bütün masa boyunca açtı.'::text),
(384300,42700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két asszisztens ... a hatalmas tekercset az egész asztalon.'::text,'tekerte ki'::text,'ki lett tekerve'::text,'kitekerve'::text,'Két asszisztens tekerte ki a hatalmas tekercset az egész asztalon.'::text),
(384303,42701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Anwesenheit von Kameras deutet darauf hin, dass die Schriftrolle kein unbedeutendes Dokument sein ...'::text,'kann'::text,'muss'::text,'sollte'::text,'Die Anwesenheit von Kameras deutet darauf hin, dass die Schriftrolle kein unbedeutendes Dokument sein kann.'::text),
(384307,42701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Присутність камер вказує на те, що сувій ... бути незначним документом.'::text,'не може'::text,'мусить'::text,'має'::text,'Присутність камер вказує на те, що сувій не може бути незначним документом.'::text),
(384306,42701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La presencia de cámaras indica que el pergamino ... ser un documento menor.'::text,'no puede'::text,'debe de'::text,'debería'::text,'La presencia de cámaras indica que el pergamino no puede ser un documento menor.'::text),
(384305,42701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La présence de caméras indique que le rouleau ... être un document mineur.'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'La présence de caméras indique que le rouleau ne peut pas être un document mineur.'::text),
(384308,42701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kameraların varlığı, tomarın önemsiz bir belge ... gösteriyor.'::text,'olamayacağını'::text,'olması gerektiğini'::text,'olmasının beklendiğini'::text,'Kameraların varlığı, tomarın önemsiz bir belge olamayacağını gösteriyor.'::text),
(384309,42701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kamerák jelenléte arra utal, hogy a tekercs ... jelentéktelen dokumentum.'::text,'nem lehet'::text,'biztosan'::text,'elvileg'::text,'A kamerák jelenléte arra utal, hogy a tekercs nem lehet jelentéktelen dokumentum.'::text),
(384312,42702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Schriftrolle, ... er unterschrieben hat, wird alles für immer verändern!'::text,'die'::text,'wer'::text,'deren'::text,'Die Schriftrolle, die er unterschrieben hat, wird alles für immer verändern!'::text),
(384316,42702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сувій, ... він підписав, назавжди все змінить!'::text,'який'::text,'хто'::text,'чий'::text,'Сувій, який він підписав, назавжди все змінить!'::text),
(384315,42702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El pergamino ... firmó lo cambiará todo para siempre!'::text,'que'::text,'quien'::text,'cuyo'::text,'¡El pergamino que firmó lo cambiará todo para siempre!'::text),
(384314,42702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le rouleau ... il a signé va tout changer pour toujours !'::text,'qu'''::text,'qui'::text,'dont'::text,'Le rouleau qu'' il a signé va tout changer pour toujours !'::text),
(384317,42702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... İmzaladığı tomar her şeyi sonsuza dek değiştirecek!'::text,''::text,NULL::text,NULL::text,'İmzaladığı tomar her şeyi sonsuza dek değiştirecek!'::text),
(384318,42702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tekercs, ... aláírt, örökre mindent megváltoztat!'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'A tekercs, amelyet aláírt, örökre mindent megváltoztat!'::text),
(384321,42703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, er ... nie wieder eine so große Schriftrolle unterschreiben, es war ein Albtraum!'::text,'würde'::text,'werde'::text,'ist'::text,'Er sagte, er würde nie wieder eine so große Schriftrolle unterschreiben, es war ein Albtraum!'::text),
(384325,42703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що більше ніколи ... такий великий сувій, це був жах!'::text,'не підпише'::text,'не підпише'::text,'не є'::text,'Він сказав, що більше ніколи не підпише такий великий сувій, це був жах!'::text),
(384324,42703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dijo que nunca más ... un pergamino tan grande, fue una pesadilla!'::text,'firmaría'::text,'firmará'::text,'es'::text,'¡Dijo que nunca más firmaría un pergamino tan grande, fue una pesadilla!'::text),
(384323,42703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ne ... plus jamais un rouleau aussi grand, c''était un cauchemar !'::text,'signerait'::text,'signera'::text,'est'::text,'Il a dit qu''il ne signerait plus jamais un rouleau aussi grand, c''était un cauchemar !'::text),
(384326,42703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha asla bu kadar büyük bir tomar ... söyledi, kâbus gibiydi!'::text,'imzalamayacağını'::text,'imzalamayacağını'::text,'imzalamadığını'::text,'Bir daha asla bu kadar büyük bir tomar imzalamayacağını söyledi, kâbus gibiydi!'::text),
(384327,42703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, soha többé nem ... alá ilyen nagy tekercset, rémálom volt!'::text,'írna'::text,'fog írni'::text,'ír'::text,'Azt mondta, soha többé nem írna alá ilyen nagy tekercset, rémálom volt!'::text),
(384330,42704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... jedes Papier mit einem normalen Stift, aber jetzt ist es eine riesige Schriftrolle! Chaos!'::text,'unterschrieb früher'::text,'war gewohnt zu unterschreiben'::text,'ist gewohnt zu unterschreiben'::text,'Er unterschrieb früher jedes Papier mit einem normalen Stift, aber jetzt ist es eine riesige Schriftrolle! Chaos!'::text),
(384334,42704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... кожен папір звичайною ручкою, а тепер це величезний сувій! Хаос!'::text,'колись підписував'::text,'звик підписувати'::text,'звик підписувати'::text,'Він колись підписував кожен папір звичайною ручкою, а тепер це величезний сувій! Хаос!'::text),
(384333,42704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... cada papel con un bolígrafo normal, pero ahora es un pergamino gigante! ¡Caos!'::text,'solía firmar'::text,'estaba acostumbrado a firmar'::text,'está acostumbrado a firmar'::text,'¡Él solía firmar cada papel con un bolígrafo normal, pero ahora es un pergamino gigante! ¡Caos!'::text),
(384332,42704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... chaque papier avec un stylo normal, mais maintenant c''est un rouleau géant ! Chaos !'::text,'signait avant'::text,'était habitué à signer'::text,'est habitué à signer'::text,'Il signait avant chaque papier avec un stylo normal, mais maintenant c''est un rouleau géant ! Chaos !'::text),
(384335,42704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden her kâğıdı normal bir kalemle ..., ama şimdi dev bir tomar! Kaos!'::text,'imzalardı'::text,'imzalamaya alışkındı'::text,'imzalamaya alışkın'::text,'Eskiden her kâğıdı normal bir kalemle imzalardı, ama şimdi dev bir tomar! Kaos!'::text),
(384336,42704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen minden papírt sima tollal ..., de most egy óriási tekercs! Káosz!'::text,'írt alá'::text,'hozzá volt szokva, hogy aláírja'::text,'hozzá van szokva, hogy aláírja'::text,'Régen minden papírt sima tollal írt alá, de most egy óriási tekercs! Káosz!'::text),
(384348,42706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, ich hab gehört, er ... gerade eine riesige Schriftrolle, live im Fernsehen.'::text,'unterschreibt'::text,'unterschreibt'::text,'hat unterschrieben'::text,'Also, ich hab gehört, er unterschreibt gerade eine riesige Schriftrolle, live im Fernsehen.'::text),
(384352,42706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що він саме зараз ... величезний сувій, наживо по телевізору.'::text,'підписує'::text,'підписує'::text,'підписав'::text,'Коротше, я чула, що він саме зараз підписує величезний сувій, наживо по телевізору.'::text),
(384351,42706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, me han dicho que ahora mismo ... un pergamino gigante, en directo en la tele.'::text,'está firmando'::text,'firma'::text,'ha firmado'::text,'Vale, me han dicho que ahora mismo está firmando un pergamino gigante, en directo en la tele.'::text),
(384350,42706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu qu''il ... un rouleau géant en ce moment, en direct à la télé.'::text,'signe'::text,'signe'::text,'a signé'::text,'Bon, j''ai entendu qu''il signe un rouleau géant en ce moment, en direct à la télé.'::text),
(384353,42706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, duydum ki şu anda canlı yayında dev bir tomar ...'::text,'imzalıyormuş'::text,'imzalarmış'::text,'imzalamış'::text,'Neyse, duydum ki şu anda canlı yayında dev bir tomar imzalıyormuş.'::text),
(384354,42706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt hallottam, hogy épp most ... alá egy óriási tekercset, élőben a tévében.'::text,'ír'::text,'ír'::text,'írt'::text,'Szóval azt hallottam, hogy épp most ír alá egy óriási tekercset, élőben a tévében.'::text),
(387327,43037,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit drei Tagen an jedem Wegweiser auf dieser Reise an.'::text,'hält'::text,'hält'::text,'hält'::text,'Sie hält seit drei Tagen an jedem Wegweiser auf dieser Reise an.'::text),
(387331,43037,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже три дні ... біля кожного дороговказу в цій подорожі.'::text,'зупиняється'::text,'зупиняється'::text,'зупиняється'::text,'Вона вже три дні зупиняється біля кожного дороговказу в цій подорожі.'::text),
(387330,43037,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... en cada poste indicador de este viaje desde hace tres días.'::text,'lleva deteniéndose'::text,'se está deteniendo'::text,'se detiene'::text,'Ella lleva deteniéndose en cada poste indicador de este viaje desde hace tres días.'::text),
(387329,43037,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... à chaque panneau indicateur de ce voyage depuis trois jours.'::text,'s''arrête'::text,'s''arrête'::text,'s''arrête'::text,'Elle s''arrête à chaque panneau indicateur de ce voyage depuis trois jours.'::text),
(387332,43037,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç gündür bu gezide her yön tabelasında ...'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Üç gündür bu gezide her yön tabelasında duruyor.'::text),
(387333,43037,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már három napja ... minden útjelző táblánál ezen az úton.'::text,'megáll'::text,'megáll'::text,'megáll'::text,'Már három napja megáll minden útjelző táblánál ezen az úton.'::text),
(387336,43038,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Arm des hölzernen Wegweisers, bog links ab und ging den Weg hinauf.'::text,'berührte'::text,'berührte gerade'::text,'hat berührt'::text,'Sie berührte den Arm des hölzernen Wegweisers, bog links ab und ging den Weg hinauf.'::text),
(387340,43038,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... стрілки дерев''яного дороговказу, повернула ліворуч і пішла вгору стежкою.'::text,'торкнулася'::text,'торкалася'::text,'торкнулася'::text,'Вона торкнулася стрілки дерев''яного дороговказу, повернула ліворуч і пішла вгору стежкою.'::text),
(387339,43038,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el brazo del poste indicador de madera, giró a la izquierda y subió por el camino.'::text,'tocó'::text,'estaba tocando'::text,'ha tocado'::text,'Ella tocó el brazo del poste indicador de madera, giró a la izquierda y subió por el camino.'::text),
(387338,43038,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le bras du panneau indicateur en bois, a tourné à gauche et a remonté le chemin.'::text,'a touché'::text,'touchait'::text,'a touché'::text,'Elle a touché le bras du panneau indicateur en bois, a tourné à gauche et a remonté le chemin.'::text),
(387341,43038,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap yön tabelasının koluna ..., sola döndü ve patikadan yukarı yürüdü.'::text,'dokundu'::text,'dokunuyordu'::text,'dokundu'::text,'Ahşap yön tabelasının koluna dokundu, sola döndü ve patikadan yukarı yürüdü.'::text),
(387342,43038,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a fa útjelző tábla karját, balra fordult, és felment az ösvényen.'::text,'Megérintette'::text,'Érintette'::text,'Megérintette'::text,'Megérintette a fa útjelző tábla karját, balra fordult, és felment az ösvényen.'::text),
(387345,43039,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit dem Frühstück drei verschiedene Wegweiser gelesen.'::text,'hat'::text,'hat'::text,'liest'::text,'Sie hat seit dem Frühstück drei verschiedene Wegweiser gelesen.'::text),
(387349,43039,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Від сніданку вона ... три різні дороговкази.'::text,'прочитала'::text,'читала'::text,'читає'::text,'Від сніданку вона прочитала три різні дороговкази.'::text),
(387348,43039,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde el desayuno, ella ... tres postes indicadores distintos.'::text,'ha leído'::text,'ha estado leyendo'::text,'lee'::text,'Desde el desayuno, ella ha leído tres postes indicadores distintos.'::text),
(387347,43039,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... trois panneaux indicateurs différents depuis le petit-déjeuner.'::text,'a lu'::text,'lit'::text,'lit'::text,'Elle a lu trois panneaux indicateurs différents depuis le petit-déjeuner.'::text),
(387350,43039,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahvaltıdan beri üç farklı yön tabelası ...'::text,'okudu'::text,'okuyor'::text,'okur'::text,'Kahvaltıdan beri üç farklı yön tabelası okudu.'::text),
(387351,43039,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reggeli óta már három különböző útjelző táblát ...'::text,'olvasott el'::text,'olvasgatott'::text,'olvas'::text,'Reggeli óta már három különböző útjelző táblát olvasott el.'::text),
(387354,43040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als du den Wegweiser auf der Klippe erreicht hast, ... du unterwegs jeden Arm gecheckt. Respekt.'::text,'hattest'::text,'hast'::text,'checktest'::text,'Als du den Wegweiser auf der Klippe erreicht hast, hattest du unterwegs jeden Arm gecheckt. Respekt.'::text),
(387358,43040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти дійшла до дороговказу на скелі, ти ... дорогою кожну стрілку. Респект.'::text,'вже перевірила'::text,'перевірила'::text,'перевірила'::text,'Поки ти дійшла до дороговказу на скелі, ти вже перевірила дорогою кожну стрілку. Респект.'::text),
(387357,43040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegaste al poste indicador del acantilado, ya ... cada brazo por el camino. Respeto.'::text,'habías revisado'::text,'has revisado'::text,'revisaste'::text,'Para cuando llegaste al poste indicador del acantilado, ya habías revisado cada brazo por el camino. Respeto.'::text),
(387356,43040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand tu as atteint le panneau au sommet de la falaise, tu ... chaque bras en chemin. Respect.'::text,'avais vérifié'::text,'as vérifié'::text,'as vérifié'::text,'Quand tu as atteint le panneau au sommet de la falaise, tu avais vérifié chaque bras en chemin. Respect.'::text),
(387359,43040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçurumun tepesindeki yön tabelasına vardığında yol boyunca her kolu ..., helal.'::text,'kontrol etmiştin'::text,'kontrol ettin'::text,'kontrol ettin'::text,'Uçurumun tepesindeki yön tabelasına vardığında yol boyunca her kolu kontrol etmiştin, helal.'::text),
(387360,43040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a szikla tetején álló útjelző táblához értél, útközben már ... minden kart. Respekt.'::text,'ellenőriztél'::text,'ellenőriztél'::text,'ellenőriztél'::text,'Mire a szikla tetején álló útjelző táblához értél, útközben már ellenőriztél minden kart. Respekt.'::text),
(387363,43041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, morgen um diese Zeit ... du irgendwo an einem neuen Ort unter einem anderen Wegweiser stehen.'::text,'wirst'::text,'wirst'::text,'stehst'::text,'Ehrlich, morgen um diese Zeit wirst du irgendwo an einem neuen Ort unter einem anderen Wegweiser stehen.'::text),
(387367,43041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, завтра в цей час ти ... під іншим дороговказом десь у новому місці.'::text,'стоятимеш'::text,'станеш'::text,'стоїш'::text,'Чесно, завтра в цей час ти стоятимеш під іншим дороговказом десь у новому місці.'::text),
(387366,43041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, mañana a esta hora ... bajo otro poste indicador en algún sitio nuevo.'::text,'estarás'::text,'te pararás'::text,'estás'::text,'Sinceramente, mañana a esta hora estarás bajo otro poste indicador en algún sitio nuevo.'::text),
(387365,43041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, demain à la même heure, tu ... sous un autre panneau quelque part ailleurs.'::text,'seras'::text,'te tiendras'::text,'es'::text,'Franchement, demain à la même heure, tu seras sous un autre panneau quelque part ailleurs.'::text),
(387368,43041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, yarın bu saatlerde yeni bir yerde başka bir yön tabelasının altında ...'::text,'duruyor olacaksın'::text,'duracaksın'::text,'duruyorsun'::text,'Açıkçası, yarın bu saatlerde yeni bir yerde başka bir yön tabelasının altında duruyor olacaksın.'::text),
(387369,43041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, holnap ilyenkor egy másik útjelző tábla alatt ... valahol egy új helyen.'::text,'fogsz állni'::text,'állsz majd'::text,'állsz'::text,'Őszintén, holnap ilyenkor egy másik útjelző tábla alatt fogsz állni valahol egy új helyen.'::text),
(387372,43042,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ein Wegweiser zwei Arme ..., liest du beide.'::text,'hat'::text,'hatte'::text,'haben wird'::text,'Ehrlich, wenn ein Wegweiser zwei Arme hat, liest du beide.'::text),
(387376,43042,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якщо в дороговказу ... дві стрілки, ти читаєш обидві.'::text,'є'::text,'були'::text,'будуть'::text,'Чесно, якщо в дороговказу є дві стрілки, ти читаєш обидві.'::text),
(387375,43042,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si un poste indicador ... dos brazos, lees los dos.'::text,'tiene'::text,'tenía'::text,'tendrá'::text,'Sinceramente, si un poste indicador tiene dos brazos, lees los dos.'::text),
(387374,43042,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si un panneau ... deux bras, tu lis les deux.'::text,'a'::text,'avait'::text,'aura'::text,'Franchement, si un panneau a deux bras, tu lis les deux.'::text),
(387377,43042,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir yön tabelasının iki kolu ..., ikisini de okursun.'::text,'varsa'::text,'vardıysa'::text,'olacaksa'::text,'Açıkçası, bir yön tabelasının iki kolu varsa, ikisini de okursun.'::text),
(387378,43042,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha egy útjelző táblának két karja ..., mindkettőt elolvasod.'::text,'van'::text,'volt'::text,'lesz'::text,'Őszintén, ha egy útjelző táblának két karja van, mindkettőt elolvasod.'::text),
(387381,43043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekter Plan: Wenn sie jedem Wegweiser folgt, ... sie sich nur zweimal verlaufen.'::text,'wird'::text,'würde'::text,'hat'::text,'Perfekter Plan: Wenn sie jedem Wegweiser folgt, wird sie sich nur zweimal verlaufen.'::text),
(387385,43043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний план: якщо вона йтиме за кожним дороговказом, то ... лише двічі.'::text,'заблукає'::text,'заблукала б'::text,'заблукала'::text,'Бездоганний план: якщо вона йтиме за кожним дороговказом, то заблукає лише двічі.'::text),
(387384,43043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan perfecto: si sigue cada poste indicador, se ... solo dos veces.'::text,'perderá'::text,'perdería'::text,'perdió'::text,'Plan perfecto: si sigue cada poste indicador, se perderá solo dos veces.'::text),
(387383,43043,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan parfait : si elle suit chaque panneau, elle se ... seulement deux fois.'::text,'perdra'::text,'perdrait'::text,'est perdue'::text,'Plan parfait : si elle suit chaque panneau, elle se perdra seulement deux fois.'::text),
(387386,43043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz plan: her yön tabelasını takip ederse sadece iki kez ...'::text,'kaybolacak'::text,'kaybolurdu'::text,'kayboldu'::text,'Kusursuz plan: her yön tabelasını takip ederse sadece iki kez kaybolacak.'::text),
(387387,43043,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan terv: ha minden útjelző táblát követ, csak kétszer ...'::text,'téved el'::text,'tévedne el'::text,'tévedt el'::text,'Hibátlan terv: ha minden útjelző táblát követ, csak kétszer téved el.'::text),
(387390,43044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn dieser Wegweiser auf der Klippe zu einem Café ..., wäre ihr Tag natürlich perfekt.'::text,'zeigte'::text,'zeigt'::text,'zeigen würde'::text,'Wenn dieser Wegweiser auf der Klippe zu einem Café zeigte, wäre ihr Tag natürlich perfekt.'::text),
(387394,43044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби той дороговказ на скелі ... на кафе, її день, звісно, був би бездоганним.'::text,'вказував'::text,'вказує'::text,'вказував би'::text,'Якби той дороговказ на скелі вказував на кафе, її день, звісно, був би бездоганним.'::text),
(387393,43044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ese poste del acantilado ... a una cafetería, su día sería perfecto, obviamente.'::text,'señalara'::text,'señala'::text,'señalaría'::text,'Si ese poste del acantilado señalara a una cafetería, su día sería perfecto, obviamente.'::text),
(387392,43044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ce panneau au sommet de la falaise ... vers un café, sa journée serait évidemment parfaite.'::text,'indiquait'::text,'indique'::text,'indiquerait'::text,'Si ce panneau au sommet de la falaise indiquait vers un café, sa journée serait évidemment parfaite.'::text),
(387395,43044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O uçurum tepesindeki yön tabelası bir kafeyi ..., günü tabii ki kusursuz olurdu.'::text,'gösterseydi'::text,'gösteriyor'::text,'gösterirdi'::text,'O uçurum tepesindeki yön tabelası bir kafeyi gösterseydi, günü tabii ki kusursuz olurdu.'::text),
(387396,43044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az a szikla tetején álló útjelző tábla egy kávézóra ..., a napja nyilván tökéletes lenne.'::text,'mutatna'::text,'mutat'::text,'mutatna'::text,'Ha az a szikla tetején álló útjelző tábla egy kávézóra mutatna, a napja nyilván tökéletes lenne.'::text),
(387408,43046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Verrat! Dieser Wegweiser ... sie bis an den Rand einer Klippe!'::text,'führte'::text,'wurde geführt'::text,'führend'::text,'Verrat! Dieser Wegweiser führte sie bis an den Rand einer Klippe!'::text),
(387412,43046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зрада! Той дороговказ ... її аж до краю скелі!'::text,'довів'::text,'був доведений'::text,'ведучи'::text,'Зрада! Той дороговказ довів її аж до краю скелі!'::text),
(387411,43046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Traición! ¡Ese poste indicador la ... hasta el borde de un acantilado!'::text,'llevó'::text,'fue llevado'::text,'llevando'::text,'¡Traición! ¡Ese poste indicador la llevó hasta el borde de un acantilado!'::text),
(387410,43046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trahison ! Ce panneau ... jusqu''au bord d''une falaise !'::text,'l''a menée'::text,'a été mené'::text,'la menant'::text,'Trahison ! Ce panneau l''a menée jusqu''au bord d''une falaise !'::text),
(387413,43046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İhanet! O yön tabelası onu ta uçurumun kenarına kadar ...!'::text,'götürdü'::text,'götürüldü'::text,'götürerek'::text,'İhanet! O yön tabelası onu ta uçurumun kenarına kadar götürdü!'::text),
(387414,43046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Árulás! Az az útjelző tábla egészen egy szikla széléig ... őt!'::text,'vezette'::text,'vezetve lett'::text,'vezetve'::text,'Árulás! Az az útjelző tábla egészen egy szikla széléig vezette őt!'::text),
(387417,43047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit Armen, die überallhin zeigen, ... dieser Wegweiser der schlimmste Albtraum eines Touristen sein!'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Mit Armen, die überallhin zeigen, muss dieser Wegweiser der schlimmste Albtraum eines Touristen sein!'::text),
(387421,43047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зі стрілками, що вказують усюди, цей дороговказ ... бути найгіршим кошмаром туриста!'::text,'мусить'::text,'не може'::text,'має'::text,'Зі стрілками, що вказують усюди, цей дороговказ мусить бути найгіршим кошмаром туриста!'::text),
(387420,43047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Con brazos que señalan a todas partes, este poste ... ser la peor pesadilla de un turista!'::text,'debe de'::text,'no puede'::text,'debería'::text,'¡Con brazos que señalan a todas partes, este poste debe de ser la peor pesadilla de un turista!'::text),
(387419,43047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec des bras qui pointent partout, ce panneau ... être le pire cauchemar d''un touriste !'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Avec des bras qui pointent partout, ce panneau doit être le pire cauchemar d''un touriste !'::text),
(387422,43047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yönü gösteren kollarıyla bu yön tabelası bir turistin en kötü kâbusu ...!'::text,'olmalı'::text,'olamaz'::text,'olması gerek'::text,'Her yönü gösteren kollarıyla bu yön tabelası bir turistin en kötü kâbusu olmalı!'::text),
(387423,43047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mindenfelé mutató karjaival ez az útjelző tábla ... egy turista legrosszabb rémálma!'::text,'biztosan'::text,'nem lehet'::text,'valószínűleg'::text,'A mindenfelé mutató karjaival ez az útjelző tábla biztosan egy turista legrosszabb rémálma!'::text),
(387714,43080,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat mir gesagt, dass sie den Wolkenkratzer am nächsten Tag wieder ...'::text,'besuchen würde'::text,'besuchen wird'::text,'besucht'::text,'Sie hat mir gesagt, dass sie den Wolkenkratzer am nächsten Tag wieder besuchen würde.'::text),
(387718,43080,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала мені, що ... хмарочос знову наступного дня.'::text,'відвідає'::text,'відвідає'::text,'відвідує'::text,'Вона сказала мені, що відвідає хмарочос знову наступного дня.'::text),
(387717,43080,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me dijo que ... el rascacielos otra vez al día siguiente.'::text,'visitaría'::text,'visitará'::text,'visita'::text,'Me dijo que visitaría el rascacielos otra vez al día siguiente.'::text),
(387716,43080,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle m''a dit qu''elle ... le gratte-ciel le lendemain.'::text,'reviendrait voir'::text,'reviendra voir'::text,'revient voir'::text,'Elle m''a dit qu''elle reviendrait voir le gratte-ciel le lendemain.'::text),
(387719,43080,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bana ertesi gün gökdeleni tekrar ... söyledi.'::text,'ziyaret edeceğini'::text,'ziyaret edeceğini'::text,'ziyaret ettiğini'::text,'Bana ertesi gün gökdeleni tekrar ziyaret edeceğini söyledi.'::text),
(387720,43080,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy másnap újra ... a felhőkarcolót.'::text,'meglátogatja'::text,'meg fogja látogatni'::text,'meglátogatja'::text,'Azt mondta, hogy másnap újra meglátogatja a felhőkarcolót.'::text),
(387723,43081,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... in einer kleinen Stadt ohne einen einzigen Wolkenkratzer.'::text,'wohnte früher'::text,'wohnte'::text,'war es gewohnt zu wohnen'::text,'Sie wohnte früher in einer kleinen Stadt ohne einen einzigen Wolkenkratzer.'::text),
(387727,43081,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... в маленькому місті без жодного хмарочоса.'::text,'колись жила'::text,'жила'::text,'звикла жити'::text,'Вона колись жила в маленькому місті без жодного хмарочоса.'::text),
(387726,43081,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... vivir en un pueblo pequeño sin un solo rascacielos.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Ella solía vivir en un pueblo pequeño sin un solo rascacielos.'::text),
(387725,43081,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans une petite ville sans un seul gratte-ciel.'::text,'vivait avant'::text,'vivait'::text,'était habituée à vivre'::text,'Elle vivait avant dans une petite ville sans un seul gratte-ciel.'::text),
(387728,43081,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir gökdeleni bile olmayan küçük bir kasabada ...'::text,'yaşardı'::text,'yaşardı'::text,'yaşamaya alışkındı'::text,'Tek bir gökdeleni bile olmayan küçük bir kasabada yaşardı.'::text),
(387729,43081,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... egy kisvárosban, ahol egyetlen felhőkarcoló sem volt.'::text,'Régen élt'::text,'Élt'::text,'Hozzá volt szokva, hogy éljen'::text,'Régen élt egy kisvárosban, ahol egyetlen felhőkarcoló sem volt.'::text),
(387732,43082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... immer wieder den Kopf in den Nacken, um die Spitze des Wolkenkratzers zu sehen.'::text,'legt'::text,'zu legen'::text,'leg'::text,'Sie legt immer wieder den Kopf in den Nacken, um die Spitze des Wolkenkratzers zu sehen.'::text),
(387736,43082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона раз у раз ... голову, щоб побачити верхівку хмарочоса.'::text,'закидає'::text,'закидати'::text,'закинь'::text,'Вона раз у раз закидає голову, щоб побачити верхівку хмарочоса.'::text),
(387735,43082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella sigue ... la cabeza hacia atrás para ver lo alto del rascacielos.'::text,'echando'::text,'echar'::text,'echa'::text,'Ella sigue echando la cabeza hacia atrás para ver lo alto del rascacielos.'::text),
(387734,43082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''arrête pas de ... la tête en arrière pour voir le sommet du gratte-ciel.'::text,'pencher'::text,'pencher'::text,'penche'::text,'Elle n''arrête pas de pencher la tête en arrière pour voir le sommet du gratte-ciel.'::text),
(387737,43082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökdelenin tepesini görmek için başını geriye ... duruyor.'::text,'atıp'::text,'atmak'::text,'at'::text,'Gökdelenin tepesini görmek için başını geriye atıp duruyor.'::text),
(387738,43082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Folyton ... a fejét, hogy lássa a felhőkarcoló tetejét.'::text,'hátrahajtja'::text,'hátrahajtani'::text,'hajtsa hátra'::text,'Folyton hátrahajtja a fejét, hogy lássa a felhőkarcoló tetejét.'::text),
(387741,43083,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Wolkenkratzer ist irgendwie krass, ...?'::text,'oder?'::text,'nicht?'::text,'ne?'::text,'Bro, der Wolkenkratzer ist irgendwie krass, oder?'::text),
(387745,43083,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей хмарочос якийсь нереальний, ...?'::text,'правда?'::text,'так?'::text,'хіба ні?'::text,'Бро, цей хмарочос якийсь нереальний, правда?'::text),
(387744,43083,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese rascacielos es medio irreal, ¿...?'::text,'verdad'::text,'no'::text,'o no'::text,'Bro, ese rascacielos es medio irreal, ¿verdad?'::text),
(387743,43083,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ce gratte-ciel est un peu irréel, ... ?'::text,'non'::text,'hein'::text,'pas vrai'::text,'Frérot, ce gratte-ciel est un peu irréel, non ?'::text),
(387746,43083,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o gökdelen biraz gerçek dışı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'öyle mi?'::text,'Kanka, o gökdelen biraz gerçek dışı, değil mi?'::text),
(387747,43083,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a felhőkarcoló elég valószerűtlen, ...?'::text,'ugye?'::text,'nem?'::text,'igaz?'::text,'Tesó, ez a felhőkarcoló elég valószerűtlen, ugye?'::text),
(387750,43084,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ohne Witz, sie wird hier jeden Wolkenkratzer anstarren, und ...'::text,'ich auch.'::text,'ich auch.'::text,'ich auch nicht.'::text,'Ohne Witz, sie wird hier jeden Wolkenkratzer anstarren, und ich auch.'::text),
(387754,43084,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Без жартів, вона витріщатиметься на кожен хмарочос тут, і ...'::text,'я теж.'::text,'я теж.'::text,'я теж ні.'::text,'Без жартів, вона витріщатиметься на кожен хмарочос тут, і я теж.'::text),
(387753,43084,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, se va a quedar mirando cada rascacielos de aquí, y ...'::text,'yo también.'::text,'yo también.'::text,'yo tampoco.'::text,'En serio, se va a quedar mirando cada rascacielos de aquí, y yo también.'::text),
(387752,43084,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, elle va fixer chaque gratte-ciel ici, et ...'::text,'moi aussi.'::text,'moi aussi.'::text,'moi non plus.'::text,'Sans mentir, elle va fixer chaque gratte-ciel ici, et moi aussi.'::text),
(387755,43084,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemin ederim, buradaki her gökdelene bakakalacak, ve ...'::text,'ben de.'::text,'ben de.'::text,'ben de değilim.'::text,'Yemin ederim, buradaki her gökdelene bakakalacak, ve ben de.'::text),
(387756,43084,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Komolyan, itt minden felhőkarcolót meg fog bámulni, és ...'::text,'én is.'::text,'én is.'::text,'én sem.'::text,'Komolyan, itt minden felhőkarcolót meg fog bámulni, és én is.'::text),
(387759,43085,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... schon 40 Minuten gelaufen, bevor das Kundenmeeting im Wolkenkratzer begann.'::text,'war'::text,'ist'::text,'lief'::text,'Sie war schon 40 Minuten gelaufen, bevor das Kundenmeeting im Wolkenkratzer begann.'::text),
(387763,43085,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... 40 хвилин, перш ніж почалася зустріч із клієнтом у хмарочосі.'::text,'ходила вже'::text,'ходить'::text,'ходила'::text,'Вона ходила вже 40 хвилин, перш ніж почалася зустріч із клієнтом у хмарочосі.'::text),
(387762,43085,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... caminando 40 minutos antes de que empezara la reunión con el cliente en el rascacielos.'::text,'llevaba'::text,'ha estado'::text,'estaba'::text,'Ella llevaba caminando 40 minutos antes de que empezara la reunión con el cliente en el rascacielos.'::text),
(387761,43085,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... depuis 40 minutes quand la réunion client dans le gratte-ciel a commencé.'::text,'marchait'::text,'marche'::text,'marchait'::text,'Elle marchait depuis 40 minutes quand la réunion client dans le gratte-ciel a commencé.'::text),
(387764,43085,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökdelendeki müşteri toplantısı başlamadan önce 40 dakikadır ...'::text,'yürüyordu'::text,'yürüyor'::text,'yürüyordu'::text,'Gökdelendeki müşteri toplantısı başlamadan önce 40 dakikadır yürüyordu.'::text),
(387765,43085,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már 40 perce ..., mielőtt elkezdődött az ügyféltalálkozó a felhőkarcolóban.'::text,'gyalogolt'::text,'gyalogol'::text,'gyalogolt'::text,'Már 40 perce gyalogolt, mielőtt elkezdődött az ügyféltalálkozó a felhőkarcolóban.'::text),
(387768,43086,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... sie an jedem Wolkenkratzer in dieser Straße vorbeigelaufen sein.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Sonnenuntergang wird sie an jedem Wolkenkratzer in dieser Straße vorbeigelaufen sein.'::text),
(387772,43086,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця вона ... повз кожен хмарочос на цій вулиці.'::text,'пройде'::text,'пройде'::text,'йтиме'::text,'До заходу сонця вона пройде повз кожен хмарочос на цій вулиці.'::text),
(387771,43086,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, ella ... por delante de cada rascacielos de esta calle.'::text,'habrá pasado'::text,'pasará'::text,'estará pasando'::text,'Para el atardecer, ella habrá pasado por delante de cada rascacielos de esta calle.'::text),
(387770,43086,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, elle ... devant chaque gratte-ciel de cette rue.'::text,'sera passée'::text,'passera'::text,'sera en train de passer'::text,'D''ici le coucher du soleil, elle sera passée devant chaque gratte-ciel de cette rue.'::text),
(387773,43086,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar bu caddedeki her gökdelenin önünden ...'::text,'geçmiş olacak'::text,'geçecek'::text,'geçiyor olacak'::text,'Gün batımına kadar bu caddedeki her gökdelenin önünden geçmiş olacak.'::text),
(387774,43086,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára ... ennek az utcának minden felhőkarcolója mellett.'::text,'el fog sétálni'::text,'elsétál majd'::text,'sétálni fog'::text,'Napnyugtára el fog sétálni ennek az utcának minden felhőkarcolója mellett.'::text),
(387786,43088,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du nicht hochgeschaut hättest, ... du diesen riesigen Wolkenkratzer nicht bemerkt.'::text,'hättest'::text,'wirst'::text,'hast'::text,'Ehrlich, wenn du nicht hochgeschaut hättest, hättest du diesen riesigen Wolkenkratzer nicht bemerkt.'::text),
(387790,43088,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти не глянула вгору, ти ... той величезний хмарочос.'::text,'не помітила б'::text,'не помітиш'::text,'не помітила'::text,'Чесно, якби ти не глянула вгору, ти не помітила б той величезний хмарочос.'::text),
(387789,43088,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si no hubieras mirado hacia arriba, no ... ese rascacielos gigante.'::text,'habrías visto'::text,'verás'::text,'viste'::text,'Sinceramente, si no hubieras mirado hacia arriba, no habrías visto ese rascacielos gigante.'::text),
(387788,43088,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu n''avais pas levé les yeux, tu ... ce gratte-ciel géant.'::text,'n''aurais pas remarqué'::text,'ne remarqueras pas'::text,'n''as pas remarqué'::text,'Franchement, si tu n''avais pas levé les yeux, tu n''aurais pas remarqué ce gratte-ciel géant.'::text),
(387791,43088,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, yukarı bakmasaydın o dev gökdeleni ...'::text,'fark etmezdin'::text,'fark etmeyeceksin'::text,'fark etmedin'::text,'Açıkçası, yukarı bakmasaydın o dev gökdeleni fark etmezdin.'::text),
(387792,43088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nem néztél volna fel, ... azt az óriási felhőkarcolót.'::text,'nem vetted volna észre'::text,'nem fogod észrevenni'::text,'nem vetted észre'::text,'Őszintén, ha nem néztél volna fel, nem vetted volna észre azt az óriási felhőkarcolót.'::text),
(387795,43089,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch: Wärst du nicht in diese Stadt gekommen, ... du jetzt nicht unter diesem Wolkenkratzer spazieren.'::text,'würdest'::text,'wärst'::text,'wirst'::text,'Irgendwie ikonisch: Wärst du nicht in diese Stadt gekommen, würdest du jetzt nicht unter diesem Wolkenkratzer spazieren.'::text),
(387799,43089,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Доволі культово: якби ти не приїхала в це місто, ти ... зараз під тим хмарочосом.'::text,'не йшла б'::text,'не пройшла б'::text,'не підеш'::text,'Доволі культово: якби ти не приїхала в це місто, ти не йшла б зараз під тим хмарочосом.'::text),
(387798,43089,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante icónico: si no hubieras venido a esta ciudad, ahora no ... bajo ese rascacielos.'::text,'estarías caminando'::text,'habrías caminado'::text,'caminarás'::text,'Bastante icónico: si no hubieras venido a esta ciudad, ahora no estarías caminando bajo ese rascacielos.'::text),
(387797,43089,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt iconique : si tu n''étais pas venue dans cette ville, tu ... sous ce gratte-ciel maintenant.'::text,'ne marcherais pas'::text,'n''aurais pas marché'::text,'ne marcheras pas'::text,'Plutôt iconique : si tu n''étais pas venue dans cette ville, tu ne marcherais pas sous ce gratte-ciel maintenant.'::text),
(387800,43089,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Epey ikonik: bu şehre gelmeseydin, şimdi o gökdelenin altında ...'::text,'yürümüyor olurdun'::text,'yürümemiş olurdun'::text,'yürümeyeceksin'::text,'Epey ikonik: bu şehre gelmeseydin, şimdi o gökdelenin altında yürümüyor olurdun.'::text),
(387801,43089,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég ikonikus: ha nem jöttél volna ebbe a városba, most nem ... az alatt a felhőkarcoló alatt.'::text,'sétálnál'::text,'sétáltál volna'::text,'fogsz sétálni'::text,'Elég ikonikus: ha nem jöttél volna ebbe a városba, most nem sétálnál az alatt a felhőkarcoló alatt.'::text),
(376923,41881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... der Büroangestellte auf seiner Tastatur schlafen, statt produktiv zu sein.'::text,'wird'::text,'wird'::text,'schläft'::text,'Morgen um diese Zeit wird der Büroangestellte auf seiner Tastatur schlafen, statt produktiv zu sein.'::text),
(376927,41881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час офісний працівник ... на клавіатурі замість того, щоб бути продуктивним.'::text,'спатиме'::text,'засне'::text,'спить'::text,'Завтра в цей час офісний працівник спатиме на клавіатурі замість того, щоб бути продуктивним.'::text),
(376926,41881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el oficinista ... sobre su teclado en vez de ser productivo.'::text,'estará durmiendo'::text,'dormirá'::text,'duerme'::text,'Mañana a esta hora, el oficinista estará durmiendo sobre su teclado en vez de ser productivo.'::text),
(376925,41881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, l''employé de bureau ... sur son clavier au lieu d''être productif.'::text,'sera en train de dormir'::text,'dormira'::text,'dort'::text,'Demain à la même heure, l''employé de bureau sera en train de dormir sur son clavier au lieu d''être productif.'::text),
(376928,41881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde ofis çalışanı üretken olmak yerine klavyesinin üstünde ...'::text,'uyuyor olacak'::text,'uyuyacak'::text,'uyuyor'::text,'Yarın bu saatlerde ofis çalışanı üretken olmak yerine klavyesinin üstünde uyuyor olacak.'::text),
(376929,41881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor az irodista a billentyűzetén ... ahelyett, hogy produktív lenne.'::text,'fog aludni'::text,'alszik majd'::text,'alszik'::text,'Holnap ilyenkor az irodista a billentyűzetén fog aludni ahelyett, hogy produktív lenne.'::text),
(376932,41882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Büroangestellte verspricht, dass er nach seinem Kaffee produktiver ...'::text,'sein wird'::text,'sein wird'::text,'ist'::text,'Der Büroangestellte verspricht, dass er nach seinem Kaffee produktiver sein wird.'::text),
(376936,41882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офісний працівник обіцяє, що після кави ... продуктивнішим.'::text,'буде'::text,'буде'::text,'є'::text,'Офісний працівник обіцяє, що після кави буде продуктивнішим.'::text),
(376935,41882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El oficinista promete que ... más productivo después de su café.'::text,'será'::text,'estará siendo'::text,'está siendo'::text,'El oficinista promete que será más productivo después de su café.'::text),
(376934,41882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''employé de bureau promet qu''il ... plus productif après son café.'::text,'sera'::text,'sera'::text,'est'::text,'L''employé de bureau promet qu''il sera plus productif après son café.'::text),
(376937,41882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ofis çalışanı kahvesinden sonra daha üretken ... söz veriyor.'::text,'olacağına'::text,'olacağına'::text,'olduğuna'::text,'Ofis çalışanı kahvesinden sonra daha üretken olacağına söz veriyor.'::text),
(376938,41882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az irodista megígéri, hogy a kávéja után produktívabb ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Az irodista megígéri, hogy a kávéja után produktívabb lesz.'::text),
(376941,41883,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Mitarbeiter auf ihren Tastaturen schlafen, ... der produktive Output 40 Prozent unter das Ziel.'::text,'fällt'::text,'fiel'::text,'wird gefallen sein'::text,'Wenn Mitarbeiter auf ihren Tastaturen schlafen, fällt der produktive Output 40 Prozent unter das Ziel.'::text),
(376945,41883,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли працівники сплять на клавіатурах, продуктивний результат ... на 40 відсотків нижче за ціль.'::text,'падає'::text,'впав'::text,'впаде'::text,'Коли працівники сплять на клавіатурах, продуктивний результат падає на 40 відсотків нижче за ціль.'::text),
(376944,41883,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el personal duerme sobre el teclado, la producción ... un 40 por ciento por debajo del objetivo.'::text,'cae'::text,'cayó'::text,'habrá caído'::text,'Si el personal duerme sobre el teclado, la producción cae un 40 por ciento por debajo del objetivo.'::text),
(376943,41883,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le personnel dort sur ses claviers, la production ... à 40 % sous l''objectif.'::text,'tombe'::text,'est tombée'::text,'sera tombée'::text,'Si le personnel dort sur ses claviers, la production tombe à 40 % sous l''objectif.'::text),
(376946,41883,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çalışanlar klavyelerinde uyursa, üretken çıktı hedefin yüzde 40 altına ...'::text,'düşer'::text,'düştü'::text,'düşmüş olacak'::text,'Çalışanlar klavyelerinde uyursa, üretken çıktı hedefin yüzde 40 altına düşer.'::text),
(376947,41883,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a munkatársak a billentyűzetükön alszanak, a produktív teljesítmény 40 százalékkal a cél alá ...'::text,'esik'::text,'esett'::text,'fog esni'::text,'Ha a munkatársak a billentyűzetükön alszanak, a produktív teljesítmény 40 százalékkal a cél alá esik.'::text),
(376959,41885,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Büroangestellte war heute nicht produktiv, und ...'::text,'der Student in der Bibliothek auch nicht.'::text,'der Student in der Bibliothek auch nicht.'::text,'der Student in der Bibliothek auch.'::text,'Der Büroangestellte war heute nicht produktiv, und der Student in der Bibliothek auch nicht.'::text),
(376963,41885,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офісний працівник сьогодні не був продуктивним, і ...'::text,'студент у бібліотеці теж ні.'::text,'студент у бібліотеці теж ні.'::text,'студент у бібліотеці теж.'::text,'Офісний працівник сьогодні не був продуктивним, і студент у бібліотеці теж ні.'::text),
(376962,41885,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El oficinista no fue productivo hoy, y ...'::text,'el estudiante de la biblioteca tampoco.'::text,'el estudiante de la biblioteca tampoco.'::text,'el estudiante de la biblioteca también.'::text,'El oficinista no fue productivo hoy, y el estudiante de la biblioteca tampoco.'::text),
(376961,41885,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''employé de bureau n''a pas été productif aujourd''hui, et ...'::text,'l''étudiant de la bibliothèque non plus.'::text,'l''étudiant de la bibliothèque non plus.'::text,'l''étudiant de la bibliothèque aussi.'::text,'L''employé de bureau n''a pas été productif aujourd''hui, et l''étudiant de la bibliothèque non plus.'::text),
(376964,41885,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ofis çalışanı bugün üretken değildi, ...'::text,'kütüphanedeki öğrenci de değildi.'::text,'kütüphanedeki öğrenci de değildi.'::text,'kütüphanedeki öğrenci de öyleydi.'::text,'Ofis çalışanı bugün üretken değildi, kütüphanedeki öğrenci de değildi.'::text),
(376965,41885,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az irodista ma nem volt produktív, és ...'::text,'a könyvtárban ülő diák sem.'::text,'a könyvtárban ülő diák sem.'::text,'a könyvtárban ülő diák is.'::text,'Az irodista ma nem volt produktív, és a könyvtárban ülő diák sem.'::text),
(376968,41886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Freitag ... er absolut nichts Produktives getan haben, und das ganze Projekt wird zusammenbrechen!'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Freitag wird er absolut nichts Produktives getan haben, und das ganze Projekt wird zusammenbrechen!'::text),
(376972,41886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці він ... абсолютно нічого продуктивного, і весь проєкт завалиться!'::text,'не зробить'::text,'не зробить'::text,'не робитиме'::text,'До п''ятниці він не зробить абсолютно нічого продуктивного, і весь проєкт завалиться!'::text),
(376971,41886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el viernes, no ... absolutamente nada productivo, y todo el proyecto se hundirá!'::text,'habrá hecho'::text,'hará'::text,'estará haciendo'::text,'¡Para el viernes, no habrá hecho absolutamente nada productivo, y todo el proyecto se hundirá!'::text),
(376970,41886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici vendredi, il ... absolument rien de productif, et tout le projet va s''effondrer !'::text,'n''aura fait'::text,'ne fera'::text,'ne sera en train de faire'::text,'D''ici vendredi, il n''aura fait absolument rien de productif, et tout le projet va s''effondrer !'::text),
(376973,41886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumaya kadar kesinlikle üretken hiçbir şey ... ve bütün proje çökecek!'::text,'yapmamış olacak'::text,'yapmayacak'::text,'yapmıyor olacak'::text,'Cumaya kadar kesinlikle üretken hiçbir şey yapmamış olacak ve bütün proje çökecek!'::text),
(376974,41886,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Péntekre semmi produktívat ..., és az egész projekt összeomlik!'::text,'nem végez el'::text,'nem fog elvégezni'::text,'nem fog csinálni'::text,'Péntekre semmi produktívat nem végez el, és az egész projekt összeomlik!'::text),
(376977,41887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er letzte Nacht geschlafen hätte, ... er einen produktiven Tag gehabt statt dieser Katastrophe!'::text,'hätte'::text,'wird'::text,'hatte'::text,'Wenn er letzte Nacht geschlafen hätte, hätte er einen produktiven Tag gehabt statt dieser Katastrophe!'::text),
(376981,41887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він виспався минулої ночі, у нього ... продуктивний день замість цієї катастрофи!'::text,'був би'::text,'буде'::text,'був'::text,'Якби він виспався минулої ночі, у нього був би продуктивний день замість цієї катастрофи!'::text),
(376980,41887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si hubiera dormido anoche, ... un día productivo en lugar de este desastre!'::text,'habría tenido'::text,'tendrá'::text,'tuvo'::text,'¡Si hubiera dormido anoche, habría tenido un día productivo en lugar de este desastre!'::text),
(376979,41887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait dormi la nuit dernière, il ... une journée productive au lieu de ce désastre !'::text,'aurait eu'::text,'aura'::text,'a eu'::text,'S''il avait dormi la nuit dernière, il aurait eu une journée productive au lieu de ce désastre !'::text),
(376982,41887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gece uyusaydı, bu felaket yerine üretken bir günü ...!'::text,'olurdu'::text,'olacak'::text,'oldu'::text,'Dün gece uyusaydı, bu felaket yerine üretken bir günü olurdu!'::text),
(376983,41887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha tegnap éjjel aludt volna, produktív napja ... e katasztrófa helyett!'::text,'lett volna'::text,'lesz'::text,'volt'::text,'Ha tegnap éjjel aludt volna, produktív napja lett volna e katasztrófa helyett!'::text),
(376986,41888,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schwor, heute produktiv ..., und dann brach er komplett auf seiner Tastatur zusammen!'::text,'zu sein'::text,'seiend'::text,'sein'::text,'Er schwor, heute produktiv zu sein, und dann brach er komplett auf seiner Tastatur zusammen!'::text),
(376990,41888,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він присягався ... продуктивним сьогодні, а потім повністю звалився на клавіатуру!'::text,'бути'::text,'будучи'::text,'бути'::text,'Він присягався бути продуктивним сьогодні, а потім повністю звалився на клавіатуру!'::text),
(376989,41888,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Juró ... productivo hoy, y luego se desplomó por completo sobre el teclado!'::text,'ser'::text,'siendo'::text,'ser'::text,'¡Juró ser productivo hoy, y luego se desplomó por completo sobre el teclado!'::text),
(376988,41888,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a juré ... productif aujourd''hui, puis il s''est complètement effondré sur son clavier !'::text,'d''être'::text,'étant'::text,'être'::text,'Il a juré d''être productif aujourd''hui, puis il s''est complètement effondré sur son clavier !'::text),
(376991,41888,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün üretken ... yemin etti, sonra da klavyesinin üstüne tamamen yığıldı!'::text,'olacağına'::text,'olarak'::text,'ol'::text,'Bugün üretken olacağına yemin etti, sonra da klavyesinin üstüne tamamen yığıldı!'::text),
(376992,41888,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megesküdött, hogy ma produktív ..., aztán teljesen ráborult a billentyűzetére!'::text,'lesz'::text,'levén'::text,'legyen'::text,'Megesküdött, hogy ma produktív lesz, aztán teljesen ráborult a billentyűzetére!'::text),
(377004,41890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, sein Chef hat ihn einen Bericht übers Produktivbleiben ... lassen.'::text,'schreiben'::text,'zu schreiben'::text,'schreibend'::text,'Hör mal, ich hab gehört, sein Chef hat ihn einen Bericht übers Produktivbleiben schreiben lassen.'::text),
(377008,41890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що бос змусив його ... звіт про те, як залишатися продуктивним.'::text,'написати'::text,'написати'::text,'писання'::text,'Слухай, я чула, що бос змусив його написати звіт про те, як залишатися продуктивним.'::text),
(377007,41890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que su jefe le hizo ... un informe sobre cómo seguir siendo productivo.'::text,'escribir'::text,'escribir'::text,'escribiendo'::text,'Oye, me han dicho que su jefe le hizo escribir un informe sobre cómo seguir siendo productivo.'::text),
(377006,41890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu que son patron lui a fait ... un rapport sur comment rester productif.'::text,'écrire'::text,'écrire'::text,'écrivant'::text,'Écoute, j''ai entendu que son patron lui a fait écrire un rapport sur comment rester productif.'::text),
(377009,41890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki patronu ona üretken kalmak üzerine bir rapor ...'::text,'yazdırmış'::text,'yazmak'::text,'yazarak'::text,'Dinle, duydum ki patronu ona üretken kalmak üzerine bir rapor yazdırmış.'::text),
(377010,41890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a főnöke ... vele egy jelentést arról, hogyan maradjon produktív.'::text,'megíratott'::text,'megírni'::text,'írva'::text,'Figyelj, azt hallottam, hogy a főnöke megíratott vele egy jelentést arról, hogyan maradjon produktív.'::text),
(377013,41891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Student wünschte, er ... vor der Prüfung produktiver gewesen.'::text,'wäre'::text,'war'::text,'würde'::text,'Der Student wünschte, er wäre vor der Prüfung produktiver gewesen.'::text),
(377017,41891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Студент шкодує, що не ... продуктивнішим перед іспитом.'::text,'був'::text,'був'::text,'був би'::text,'Студент шкодує, що не був продуктивнішим перед іспитом.'::text),
(377016,41891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El estudiante desearía ... más productivo antes del examen.'::text,'haber sido'::text,'estar siendo'::text,'haber sido'::text,'El estudiante desearía haber sido más productivo antes del examen.'::text),
(377015,41891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''étudiant regrette de ne pas ... plus productif avant l''examen.'::text,'avoir été'::text,'être'::text,'avoir été'::text,'L''étudiant regrette de ne pas avoir été plus productif avant l''examen.'::text),
(377018,41891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğrenci keşke sınavdan önce daha üretken ... diyor.'::text,'olsaydım'::text,'oluyor olsaydım'::text,'olurdum'::text,'Öğrenci keşke sınavdan önce daha üretken olsaydım diyor.'::text),
(377019,41891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A diák azt kívánja, bárcsak produktívabb ... a vizsga előtt.'::text,'lett volna'::text,'lenne'::text,'lett volna'::text,'A diák azt kívánja, bárcsak produktívabb lett volna a vizsga előtt.'::text),
(382926,42548,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich bestens gepflegt: Die Burg soll seit Jahrhunderten in Trümmern ...'::text,'gelassen worden sein'::text,'lassen'::text,'gelassen werdend'::text,'Offensichtlich bestens gepflegt: Die Burg soll seit Jahrhunderten in Trümmern gelassen worden sein.'::text),
(382930,42548,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, добре доглянутий: кажуть, замок ... в руїнах століттями.'::text,'залишили'::text,'залишити'::text,'залишаючи'::text,'Очевидно, добре доглянутий: кажуть, замок залишили в руїнах століттями.'::text),
(382929,42548,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente bien cuidado: se dice que el castillo ... en ruinas durante siglos.'::text,'fue dejado'::text,'dejar'::text,'siendo dejado'::text,'Claramente bien cuidado: se dice que el castillo fue dejado en ruinas durante siglos.'::text),
(382928,42548,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visiblement bien entretenu : on dit que le château ... en ruine pendant des siècles.'::text,'a été laissé'::text,'laisser'::text,'étant laissé'::text,'Visiblement bien entretenu : on dit que le château a été laissé en ruine pendant des siècles.'::text),
(382931,42548,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki çok iyi bakılmış: kalenin yüzyıllardır harabe halinde ... söyleniyor.'::text,'bırakıldığı'::text,'bırakmak'::text,'bırakılarak'::text,'Belli ki çok iyi bakılmış: kalenin yüzyıllardır harabe halinde bırakıldığı söyleniyor.'::text),
(382932,42548,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván nagyon gondozott: a várat állítólag évszázadokig romokban ...'::text,'hagyták'::text,'hagyni'::text,'hagyva'::text,'Nyilván nagyon gondozott: a várat állítólag évszázadokig romokban hagyták.'::text),
(382935,42549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie bestand darauf, vor Sonnenaufgang jede Ruine auf dem Hügel ...! Totaler Wahnsinn!'::text,'zu erklimmen'::text,'zu erklimmen'::text,'erklimmt'::text,'Sie bestand darauf, vor Sonnenaufgang jede Ruine auf dem Hügel zu erklimmen! Totaler Wahnsinn!'::text),
(382939,42549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона наполягла на тому, щоб ... на кожну руїну на пагорбі до світанку! Повне божевілля!'::text,'залізти'::text,'залізти'::text,'лізь'::text,'Вона наполягла на тому, щоб залізти на кожну руїну на пагорбі до світанку! Повне божевілля!'::text),
(382938,42549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Insistió en ... cada ruina de la colina antes del amanecer! ¡Una locura total!'::text,'subir'::text,'subir'::text,'sube'::text,'¡Insistió en subir cada ruina de la colina antes del amanecer! ¡Una locura total!'::text),
(382937,42549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a insisté pour ... chaque ruine de la colline avant le lever du soleil ! Pure folie !'::text,'escalader'::text,'escalader'::text,'escalade'::text,'Elle a insisté pour escalader chaque ruine de la colline avant le lever du soleil ! Pure folie !'::text),
(382940,42549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün doğmadan tepedeki her harabeye ... ısrar etti! Tam bir delilik!'::text,'tırmanmakta'::text,'tırmanmaya'::text,'tırman'::text,'Gün doğmadan tepedeki her harabeye tırmanmakta ısrar etti! Tam bir delilik!'::text),
(382941,42549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ragaszkodott hozzá, hogy napfelkelte előtt ... minden romra a dombon! Teljes őrület!'::text,'felmásszon'::text,'felmászni'::text,'mássz fel'::text,'Ragaszkodott hozzá, hogy napfelkelte előtt felmásszon minden romra a dombon! Teljes őrület!'::text),
(382944,42550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Besitzer ... diese Burg nie in Trümmer fallen lassen dürfen! Eine totale Tragödie!'::text,'hätten'::text,'mussten'::text,'konnten'::text,'Die Besitzer hätten diese Burg nie in Trümmer fallen lassen dürfen! Eine totale Tragödie!'::text),
(382948,42550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власникам ... дозволяти цьому замку перетворитися на руїну! Повна трагедія!'::text,'ніколи не слід було'::text,'ніколи не можна було'::text,'не вдалося'::text,'Власникам ніколи не слід було дозволяти цьому замку перетворитися на руїну! Повна трагедія!'::text),
(382947,42550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los dueños nunca ... dejar que este castillo se convirtiera en ruinas! ¡Una tragedia total!'::text,'deberían haber'::text,'debieron'::text,'pudieron'::text,'¡Los dueños nunca deberían haber dejar que este castillo se convirtiera en ruinas! ¡Una tragedia total!'::text),
(382946,42550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les propriétaires ... laisser ce château tomber en ruine ! Une vraie tragédie !'::text,'n''auraient jamais dû'::text,'n''ont jamais dû'::text,'n''ont pas pu'::text,'Les propriétaires n''auraient jamais dû laisser ce château tomber en ruine ! Une vraie tragédie !'::text),
(382949,42550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahipleri bu kalenin harabeye dönmesine asla ...! Tam bir trajedi!'::text,'izin vermemeliydi'::text,'izin vermemiş olmalı'::text,'izin veremedi'::text,'Sahipleri bu kalenin harabeye dönmesine asla izin vermemeliydi! Tam bir trajedi!'::text),
(382950,42550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tulajdonosoknak soha nem ... volna hagyniuk, hogy ez a vár romba dőljön! Teljes tragédia!'::text,'kellett'::text,'szabadott'::text,'tudták'::text,'A tulajdonosoknak soha nem kellett volna hagyniuk, hogy ez a vár romba dőljön! Teljes tragédia!'::text),
(382953,42551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... eine so schöne Ruine bei Sonnenaufgang gesehen.'::text,'hat sie'::text,'sie hat'::text,'sah sie'::text,'Selten hat sie eine so schöne Ruine bei Sonnenaufgang gesehen.'::text),
(382957,42551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... вона таку гарну руїну на світанку.'::text,'бачила'::text,'бачила'::text,'бачила'::text,'Рідко бачила вона таку гарну руїну на світанку.'::text),
(382956,42551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... una ruina tan bonita al amanecer.'::text,'ha visto ella'::text,'ella ha visto'::text,'vio ella'::text,'Pocas veces ha visto ella una ruina tan bonita al amanecer.'::text),
(382955,42551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... une ruine aussi belle au lever du soleil.'::text,'a-t-elle vu'::text,'elle a vu'::text,'vit-elle'::text,'Rarement a-t-elle vu une ruine aussi belle au lever du soleil.'::text),
(382958,42551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün doğarken nadiren böyle güzel bir harabe ...'::text,'görmüştür'::text,'görmüştür'::text,'gördü'::text,'Gün doğarken nadiren böyle güzel bir harabe görmüştür.'::text),
(382959,42551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... ilyen szép romot napfelkeltekor.'::text,'látott'::text,'látott'::text,'látott'::text,'Ritkán látott ilyen szép romot napfelkeltekor.'::text),
(382962,42552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, angeblich hat sie einen Fremden dazu gebracht, sie vor der Ruine zu ...'::text,'filmen'::text,'filmen'::text,'gefilmt'::text,'Okay, angeblich hat sie einen Fremden dazu gebracht, sie vor der Ruine zu filmen.'::text),
(382966,42552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, вона вмовила незнайомця ... її перед руїною.'::text,'зняти'::text,'зняти'::text,'знятий'::text,'Отже, кажуть, вона вмовила незнайомця зняти її перед руїною.'::text),
(382965,42552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, dicen que consiguió que un desconocido la ... delante de la ruina.'::text,'grabara'::text,'grabar'::text,'grabada'::text,'Vale, dicen que consiguió que un desconocido la grabara delante de la ruina.'::text),
(382964,42552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il paraît qu''elle a demandé à un inconnu de la ... devant la ruine.'::text,'filmer'::text,'filmer'::text,'filmée'::text,'Bon, il paraît qu''elle a demandé à un inconnu de la filmer devant la ruine.'::text),
(382967,42552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, dediklerine göre harabenin önünde bir yabancıya kendini ...'::text,'çektirmiş'::text,'çek'::text,'çekilmiş'::text,'Tamam, dediklerine göre harabenin önünde bir yabancıya kendini çektirmiş.'::text),
(382968,42552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag rávett egy idegent, hogy ... őt a rom előtt.'::text,'lefilmezze'::text,'lefilmezni'::text,'lefilmezve'::text,'Szóval, állítólag rávett egy idegent, hogy lefilmezze őt a rom előtt.'::text),
(382971,42553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschte, die Burg ... verfallen, bevor sie sie ganz sehen konnte.'::text,'wäre nicht'::text,'verfiel nicht'::text,'würde nicht'::text,'Sie wünschte, die Burg wäre nicht verfallen, bevor sie sie ganz sehen konnte.'::text),
(382975,42553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона шкодує, що замок ... на руїну, перш ніж вона змогла побачити його цілим.'::text,'перетворився'::text,'перетворився'::text,'перетвориться'::text,'Вона шкодує, що замок перетворився на руїну, перш ніж вона змогла побачити його цілим.'::text),
(382974,42553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella desearía que el castillo no ... en ruinas antes de que pudiera verlo entero.'::text,'hubiera caído'::text,'cayera'::text,'caería'::text,'Ella desearía que el castillo no hubiera caído en ruinas antes de que pudiera verlo entero.'::text),
(382973,42553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait que le château ne ... pas tombé en ruine avant qu''elle puisse le voir entier.'::text,'soit'::text,'tombe'::text,'tomberait'::text,'Elle aimerait que le château ne soit pas tombé en ruine avant qu''elle puisse le voir entier.'::text),
(382976,42553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke kale, onu bütün halde göremeden harabeye ... diyor.'::text,'dönmeseydi'::text,'dönmedi'::text,'dönmezdi'::text,'Keşke kale, onu bütün halde göremeden harabeye dönmeseydi diyor.'::text),
(382977,42553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak a vár ne ... romba, mielőtt egészben láthatta volna.'::text,'dőlt volna'::text,'dőlt'::text,'dőlne'::text,'Azt kívánja, bárcsak a vár ne dőlt volna romba, mielőtt egészben láthatta volna.'::text),
(382989,42555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Burg zerfiel vor Jahrhunderten in ... und wurde nie wieder aufgebaut.'::text,'Trümmer'::text,'eine Ruine'::text,'die Ruine'::text,'Die Burg zerfiel vor Jahrhunderten in Trümmer und wurde nie wieder aufgebaut.'::text),
(382993,42555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Замок перетворився на ... століття тому і так і не був відбудований.'::text,'руїну'::text,'руїну'::text,'руїну'::text,'Замок перетворився на руїну століття тому і так і не був відбудований.'::text),
(382992,42555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El castillo quedó en ... hace siglos y nunca se reconstruyó.'::text,'ruinas'::text,'una ruina'::text,'la ruina'::text,'El castillo quedó en ruinas hace siglos y nunca se reconstruyó.'::text),
(382991,42555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le château est tombé en ... il y a des siècles et n''a jamais été reconstruit.'::text,'ruine'::text,'une ruine'::text,'la ruine'::text,'Le château est tombé en ruine il y a des siècles et n''a jamais été reconstruit.'::text),
(382994,42555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kale yüzyıllar önce ... döndü ve hiç yeniden inşa edilmedi.'::text,'harabeye'::text,'bir harabeye'::text,'harabeye'::text,'Kale yüzyıllar önce harabeye döndü ve hiç yeniden inşa edilmedi.'::text),
(382995,42555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vár évszázadokkal ezelőtt ... dőlt, és soha nem építették újjá.'::text,'romba'::text,'egy romba'::text,'a romba'::text,'A vár évszázadokkal ezelőtt romba dőlt, és soha nem építették újjá.'::text),
(382998,42556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Besucher steigen immer noch auf den Hügel, ... der in Trümmern liegenden Burg.'::text,'trotz'::text,'obwohl'::text,'falls'::text,'Besucher steigen immer noch auf den Hügel, trotz der in Trümmern liegenden Burg.'::text),
(383002,42556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відвідувачі досі піднімаються на пагорб, ... те, що замок лежить у руїнах.'::text,'попри'::text,'хоча'::text,'на випадок'::text,'Відвідувачі досі піднімаються на пагорб, попри те, що замок лежить у руїнах.'::text),
(383001,42556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los visitantes siguen subiendo la colina, ... que el castillo esté en ruinas.'::text,'a pesar de'::text,'aunque'::text,'por si'::text,'Los visitantes siguen subiendo la colina, a pesar de que el castillo esté en ruinas.'::text),
(383000,42556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les visiteurs montent toujours la colline, ... le château en ruine.'::text,'malgré'::text,'bien que'::text,'au cas où'::text,'Les visiteurs montent toujours la colline, malgré le château en ruine.'::text),
(383003,42556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalenin harabe halinde olmasına ..., ziyaretçiler hâlâ tepeye tırmanıyor.'::text,'rağmen'::text,'karşın'::text,'ihtimaline karşı'::text,'Kalenin harabe halinde olmasına rağmen, ziyaretçiler hâlâ tepeye tırmanıyor.'::text),
(383004,42556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látogatók még mindig felmásznak a dombra, ... a vár romokban hever.'::text,'annak ellenére, hogy'::text,'bár'::text,'arra az esetre, ha'::text,'A látogatók még mindig felmásznak a dombra, annak ellenére, hogy a vár romokban hever.'::text),
(383007,42557,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wusste, dass die Burg eine Ruine ..., aber natürlich erwartete sie auch ein Café.'::text,'sein würde'::text,'sein wird'::text,'gerade ist'::text,'Sie wusste, dass die Burg eine Ruine sein würde, aber natürlich erwartete sie auch ein Café.'::text),
(383011,42557,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знала, що замок ... руїною, але, звісно, чекала ще й кафе.'::text,'буде'::text,'буде'::text,'є'::text,'Вона знала, що замок буде руїною, але, звісно, чекала ще й кафе.'::text),
(383010,42557,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que el castillo ... una ruina, pero obviamente también esperaba una cafetería.'::text,'sería'::text,'será'::text,'está siendo'::text,'Sabía que el castillo sería una ruina, pero obviamente también esperaba una cafetería.'::text),
(383009,42557,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle savait que le château ... une ruine, mais évidemment elle s''attendait aussi à un café.'::text,'serait'::text,'sera'::text,'est'::text,'Elle savait que le château serait une ruine, mais évidemment elle s''attendait aussi à un café.'::text),
(383012,42557,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalenin bir harabe ... biliyordu, ama tabii ki bir kafe de bekliyordu.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Kalenin bir harabe olacağını biliyordu, ama tabii ki bir kafe de bekliyordu.'::text),
(383013,42557,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy a vár rom ..., de persze egy kávézót is várt.'::text,'lesz'::text,'lesz'::text,NULL::text,'Tudta, hogy a vár rom lesz, de persze egy kávézót is várt.'::text),
(383016,42558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tadellose Pflege: Die Burg ... seit dreihundert Jahren in Trümmern.'::text,'steht'::text,'steht'::text,'steht'::text,'Tadellose Pflege: Die Burg steht seit dreihundert Jahren in Trümmern.'::text),
(383020,42558,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганний догляд: замок ... в руїнах уже триста років.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Бездоганний догляд: замок стоїть в руїнах уже триста років.'::text),
(383019,42558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mantenimiento impecable: el castillo ... en ruinas desde hace trescientos años.'::text,'está'::text,'está'::text,'está'::text,'Mantenimiento impecable: el castillo está en ruinas desde hace trescientos años.'::text),
(383018,42558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entretien impeccable : le château ... en ruine depuis trois cents ans.'::text,'est'::text,'est'::text,'est'::text,'Entretien impeccable : le château est en ruine depuis trois cents ans.'::text),
(383021,42558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz bakım: kale üç yüz yıldır harabe halinde ...'::text,'duruyor'::text,'durur'::text,'duruyor'::text,'Kusursuz bakım: kale üç yüz yıldır harabe halinde duruyor.'::text),
(383022,42558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan karbantartás: a vár háromszáz éve romokban ...'::text,'áll'::text,'áll'::text,'áll'::text,'Hibátlan karbantartás: a vár háromszáz éve romokban áll.'::text),
(334983,37221,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Parfüm auf ihren Blazer verschüttet, ... er völlig ruiniert!'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn sie das Parfüm auf ihren Blazer verschüttet, ist er völlig ruiniert!'::text),
(334987,37221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона проллє ці парфуми на піджак, він ... повністю зіпсований!'::text,'буде'::text,'був би'::text,'був'::text,'Якщо вона проллє ці парфуми на піджак, він буде повністю зіпсований!'::text),
(334986,37221,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si se derrama ese perfume en la americana, ... completamente arruinada!'::text,'quedará'::text,'quedaría'::text,'quedó'::text,'¡Si se derrama ese perfume en la americana, quedará completamente arruinada!'::text),
(334985,37221,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle renverse ce parfum sur son blazer, il ... complètement fichu !'::text,'sera'::text,'serait'::text,'était'::text,'Si elle renverse ce parfum sur son blazer, il sera complètement fichu !'::text),
(334988,37221,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O parfümü blazer ceketine dökerse, ceket tamamen ...!'::text,'mahvolacak'::text,'mahvolurdu'::text,'mahvoldu'::text,'O parfümü blazer ceketine dökerse, ceket tamamen mahvolacak!'::text),
(334989,37221,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ráönti azt a parfümöt a blézerére, az teljesen tönkre ...!'::text,'megy'::text,'menne'::text,'ment'::text,'Ha ráönti azt a parfümöt a blézerére, az teljesen tönkre megy!'::text),
(334992,37222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie statt des Blazers einen Pullover tragen würde, ... sie weniger formell aus.'::text,'sähe'::text,'wird'::text,'sieht'::text,'Wenn sie statt des Blazers einen Pullover tragen würde, sähe sie weniger formell aus.'::text),
(334996,37222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона вдягла светр замість піджака, вона ... менш офіційно.'::text,'виглядала б'::text,'виглядатиме'::text,'виглядає'::text,'Якби вона вдягла светр замість піджака, вона виглядала б менш офіційно.'::text),
(334995,37222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si llevara un jersey en lugar de la americana, ... menos formal.'::text,'parecería'::text,'parecerá'::text,'parece'::text,'Si llevara un jersey en lugar de la americana, parecería menos formal.'::text),
(334994,37222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle portait un pull au lieu du blazer, elle ... moins formelle.'::text,'aurait l''air'::text,'aura l''air'::text,'a l''air'::text,'Si elle portait un pull au lieu du blazer, elle aurait l''air moins formelle.'::text),
(334997,37222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Blazer yerine kazak giyseydi, daha az resmi ...'::text,'görünürdü'::text,'görünecek'::text,'görünüyor'::text,'Blazer yerine kazak giyseydi, daha az resmi görünürdü.'::text),
(334998,37222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a blézer helyett pulóvert viselne, kevésbé hivatalosnak ...'::text,'tűnne'::text,'fog tűnni'::text,'tűnik'::text,'Ha a blézer helyett pulóvert viselne, kevésbé hivatalosnak tűnne.'::text),
(335001,37223,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... der Blazer letzte Woche in Mailand gekauft.'::text,'wurde'::text,'wird'::text,'kaufte'::text,'Girl, angeblich wurde der Blazer letzte Woche in Mailand gekauft.'::text),
(335005,37223,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, той піджак ... в Мілані минулого тижня.'::text,'купили'::text,'купують'::text,'купила'::text,'Подруго, кажуть, той піджак купили в Мілані минулого тижня.'::text),
(335004,37223,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer esa americana ... en Milán la semana pasada.'::text,'fue comprada'::text,'es comprada'::text,'compró'::text,'Tía, al parecer esa americana fue comprada en Milán la semana pasada.'::text),
(335003,37223,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ce blazer ... à Milan la semaine dernière.'::text,'a été acheté'::text,'est acheté'::text,'a acheté'::text,'Meuf, apparemment ce blazer a été acheté à Milan la semaine dernière.'::text),
(335006,37223,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o blazer geçen hafta Milano''da ...'::text,'alınmış'::text,'alınıyor'::text,'almış'::text,'Kızım, o blazer geçen hafta Milano''da alınmış.'::text),
(335007,37223,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag azt a blézert múlt héten Milánóban ...'::text,'vették'::text,'veszik'::text,'vette'::text,'Csajszi, állítólag azt a blézert múlt héten Milánóban vették.'::text),
(335010,37224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... sie ihren beigen Blazer zum Laden.'::text,'trug'::text,'wurde getragen'::text,'tragend'::text,'Heute Morgen trug sie ihren beigen Blazer zum Laden.'::text),
(335014,37224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці вона ... свій бежевий піджак до магазину.'::text,'вдягла'::text,'була вдягнена'::text,'вдягаючи'::text,'Сьогодні вранці вона вдягла свій бежевий піджак до магазину.'::text),
(335013,37224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana ... su americana beige para ir a la tienda.'::text,'llevó'::text,'fue llevada'::text,'llevando'::text,'Esta mañana llevó su americana beige para ir a la tienda.'::text),
(335012,37224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce matin, elle ... son blazer beige pour aller au magasin.'::text,'a porté'::text,'a été porté'::text,'portant'::text,'Ce matin, elle a porté son blazer beige pour aller au magasin.'::text),
(335015,37224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah mağazaya bej blazerını ...'::text,'giydi'::text,'giyildi'::text,'giyerek'::text,'Bu sabah mağazaya bej blazerını giydi.'::text),
(335016,37224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel a bézs blézerét ... a boltba.'::text,'vette fel'::text,'fel lett véve'::text,'felvéve'::text,'Ma reggel a bézs blézerét vette fel a boltba.'::text),
(335019,37225,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie testet in ihrem Blazer viele Flakons; sie ... ein Geschenk suchen, aber niemand ist sich sicher.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Sie testet in ihrem Blazer viele Flakons; sie könnte ein Geschenk suchen, aber niemand ist sich sicher.'::text),
(335023,37225,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона в піджаку тестує багато флаконів; вона ... шукати подарунок, але ніхто не впевнений.'::text,'може'::text,'мусить'::text,'не може'::text,'Вона в піджаку тестує багато флаконів; вона може шукати подарунок, але ніхто не впевнений.'::text),
(335022,37225,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prueba muchos frascos con su americana; ... estar buscando un regalo, pero nadie está seguro.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Prueba muchos frascos con su americana; podría estar buscando un regalo, pero nadie está seguro.'::text),
(335021,37225,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle teste plein de flacons dans son blazer ; elle ... chercher un cadeau, mais personne n''est sûr.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Elle teste plein de flacons dans son blazer ; elle pourrait chercher un cadeau, mais personne n''est sûr.'::text),
(335024,37225,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Blazerıyla birçok şişe deniyor; bir hediye arıyor ..., ama kimse emin değil.'::text,'olabilir'::text,'olmalı'::text,'olamaz'::text,'Blazerıyla birçok şişe deniyor; bir hediye arıyor olabilir, ama kimse emin değil.'::text),
(335025,37225,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A blézerében sok üveget kipróbál; ... ajándékot keres, de senki sem biztos benne.'::text,'talán'::text,'biztosan'::text,'nem lehet, hogy'::text,'A blézerében sok üveget kipróbál; talán ajándékot keres, de senki sem biztos benne.'::text),
(335037,37227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie fragte die Verkäuferin, ob das Parfüm Flecken auf ihrem Blazer hinterlassen ...'::text,'würde'::text,'wird'::text,NULL::text,'Sie fragte die Verkäuferin, ob das Parfüm Flecken auf ihrem Blazer hinterlassen würde.'::text),
(335041,37227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона запитала продавчиню, чи ... парфуми плями на піджаку.'::text,'залишать'::text,'залишать'::text,NULL::text,'Вона запитала продавчиню, чи залишать парфуми плями на піджаку.'::text),
(335040,37227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le preguntó a la dependienta si el perfume ... su americana.'::text,'mancharía'::text,'manchará'::text,NULL::text,'Le preguntó a la dependienta si el perfume mancharía su americana.'::text),
(335039,37227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a demandé à la vendeuse si le parfum ... son blazer.'::text,'tacherait'::text,'tachera'::text,NULL::text,'Elle a demandé à la vendeuse si le parfum tacherait son blazer.'::text),
(335042,37227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Satış görevlisine parfümün blazerını ... sordu.'::text,'lekeleyip lekelemeyeceğini'::text,'lekeleyip lekelemeyeceğini'::text,NULL::text,'Satış görevlisine parfümün blazerını lekeleyip lekelemeyeceğini sordu.'::text),
(335043,37227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megkérdezte az eladót, hogy a parfüm ... foltot a blézerén.'::text,'hagyna-e'::text,'hagy-e'::text,NULL::text,'Megkérdezte az eladót, hogy a parfüm hagyna-e foltot a blézerén.'::text),
(335046,37228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... früher Blazer. Offensichtlich ist die Phase vorbei.'::text,'hasste'::text,'hasste'::text,'ist gewohnt zu hassen'::text,'Sie hasste früher Blazer. Offensichtlich ist die Phase vorbei.'::text),
(335050,37228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... піджаки. Очевидно, цей етап минув.'::text,'колись ненавиділа'::text,'ненавиділа'::text,'звикла ненавидіти'::text,'Вона колись ненавиділа піджаки. Очевидно, цей етап минув.'::text),
(335049,37228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... odiar las americanas. Obviamente esa fase ya pasó.'::text,'solía'::text,'solía'::text,'está acostumbrada a'::text,'Ella solía odiar las americanas. Obviamente esa fase ya pasó.'::text),
(335048,37228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les blazers avant. Évidemment, cette phase est terminée.'::text,'détestait'::text,'détestait'::text,'est habituée à détester'::text,'Elle détestait les blazers avant. Évidemment, cette phase est terminée.'::text),
(335051,37228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden blazerlardan ..., belli ki o dönem bitti.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkın'::text,'Eskiden blazerlardan nefret ederdi, belli ki o dönem bitti.'::text),
(335052,37228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a blézereket. Nyilván ennek a korszaknak vége.'::text,'utálta'::text,'utálta'::text,'hozzá van szokva, hogy utálja'::text,'Régen utálta a blézereket. Nyilván ennek a korszaknak vége.'::text),
(335055,37229,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... in diesem Blazer immer weiter an Flakons. Ein sehr schneller Einkauf, klar.'::text,'schnuppert'::text,'zu schnuppern'::text,'schnupper'::text,'Sie schnuppert in diesem Blazer immer weiter an Flakons. Ein sehr schneller Einkauf, klar.'::text),
(335059,37229,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона в цьому піджаку все ... флакони. Дуже швидкий шопінг, ясно.'::text,'нюхає'::text,'нюхати'::text,'нюхай'::text,'Вона в цьому піджаку все нюхає флакони. Дуже швидкий шопінг, ясно.'::text),
(335058,37229,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella sigue ... frascos con esa americana. Una compra rapidísima, claramente.'::text,'oliendo'::text,'oler'::text,'huele'::text,'Ella sigue oliendo frascos con esa americana. Una compra rapidísima, claramente.'::text),
(335057,37229,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''arrête pas de ... des flacons dans ce blazer. Des courses très rapides, clairement.'::text,'sentir'::text,'sentir'::text,'sent'::text,'Elle n''arrête pas de sentir des flacons dans ce blazer. Des courses très rapides, clairement.'::text),
(335060,37229,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O blazerla şişeleri ... duruyor. Çok hızlı bir alışveriş, belli ki.'::text,'koklayıp'::text,'koklamak'::text,'kokla'::text,'O blazerla şişeleri koklayıp duruyor. Çok hızlı bir alışveriş, belli ki.'::text),
(335061,37229,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abban a blézerben folyton ... az üvegeket. Nagyon gyors vásárlás, nyilván.'::text,'szagolgatja'::text,'szagolgatni'::text,'szagolgasd'::text,'Abban a blézerben folyton szagolgatja az üvegeket. Nagyon gyors vásárlás, nyilván.'::text),
(335073,37231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... Parfüm über ihren ganzen neuen Blazer gesprüht, bevor sie es überhaupt bemerkte. Was für eine Katastrophe!'::text,'hatte'::text,'hat'::text,'sprühte'::text,'Sie hatte Parfüm über ihren ganzen neuen Blazer gesprüht, bevor sie es überhaupt bemerkte. Was für eine Katastrophe!'::text),
(335077,37231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... парфуми на весь новий піджак, перш ніж узагалі помітила. Яка катастрофа!'::text,'вже набризкала'::text,'набризкала'::text,'бризкала'::text,'Вона вже набризкала парфуми на весь новий піджак, перш ніж узагалі помітила. Яка катастрофа!'::text),
(335076,37231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se ... perfume por toda la americana nueva antes de darse cuenta siquiera. ¡Qué desastre!'::text,'había echado'::text,'ha echado'::text,'estaba echando'::text,'Se había echado perfume por toda la americana nueva antes de darse cuenta siquiera. ¡Qué desastre!'::text),
(335075,37231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... du parfum partout sur son nouveau blazer avant même de s''en rendre compte. Quelle catastrophe !'::text,'avait vaporisé'::text,'a vaporisé'::text,'vaporisait'::text,'Elle avait vaporisé du parfum partout sur son nouveau blazer avant même de s''en rendre compte. Quelle catastrophe !'::text),
(335078,37231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha fark etmeden parfümü ... yeni blazerının her yerine. Ne felaket!'::text,'sıkmıştı'::text,'sıktı'::text,'sıkıyordu'::text,'Daha fark etmeden parfümü sıkmıştı yeni blazerının her yerine. Ne felaket!'::text),
(335079,37231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még mielőtt észrevette volna, ... parfümmel az egész új blézerét. Micsoda katasztrófa!'::text,'telefújta'::text,'telefújta'::text,'fújta'::text,'Még mielőtt észrevette volna, telefújta parfümmel az egész új blézerét. Micsoda katasztrófa!'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
